__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AwakerStory = readonly({
  AwakerStory_100415_Content = {
    Text = "A. F. 3@2年2月12日\n彫像スタジオを訪れた際、完成した彫像作品に塗料を塗った。色彩デザインは独創的であるが、元々の彫像グループのデザイン体系には反している。\nその後、すべての彫像作品の着色作業を無料で引き受けることを約束した。もしかすると、今後一緒に創作する機会があるかもしれない。\n証明者：サンガー\n…………\n\nA. F. 3@2年4月9日\n鍵の墓に遺体を掘り出すことを試みたが、未遂。現場で捕まった後、巡回者に遺体の役を演じてもらった。\n証明者：オジール\n…………\n\nA. F. 3@2年4月11日\n厨房の食材を画作の参考対象として盗んだ。食材は無事に救出されたが、香料の漬け込みのタイミングと食材の風味は台無しになり、価値を失った。\n食材の属性と出所については…………しばらくはお話しできない。\n証明者：ドレセイン\n…………\n\nA. F. 3@2年6月29日\n私自で校の典藏館に侵入し、自ら制作した大作を中央の壁に掲げた。真夜中、学校のシルバーコアのエネルギー密度の影響で、異形の生物が絵から飛び出し、未保護の収蔵品に損害を与えた。\nその後、修理作業を自主的に申請したが、過程で壊した収蔵品はモンスターが壊したものよりも多かった。校側は緊急に彼の修理行為を中止した。\n証明者：ハレト\n…………\n\nA. F. 3@2年7月23日\nブラックプールに侵入し、池の水を塗料として使おうとした。タヴィは彼を妨げなかったが、ブラックプール自体の力によって彼はかなりのダメージを受けた。\n彼がブラックプールでどのような景色を創作するのか、少し楽しみだ。\n証明者：アリステア\n…………\n\n——『ピックマンの記録・違反記録』"
  },
  AwakerStory_100415_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_100415_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_100416_Content = {
    Text = "葬骸城からの招待状を受け取る前、ピックマンはこの世に自分の居場所など永遠にないと思っていた。\n王邸の食卓で見たその極限の狂気の光景は、彼を眠れぬ夜に導いた。異なる世界の光景を見ることができるその目は、この宴席で真の満足を得た。\n夢から目覚め、葬骸城が彼の目の前から消えたとき、ピックマンの後悔はすぐに無限の渇望へと変わった——彼は再び夢の中の都市に行きたく、再びその無限の狂気の絶景を見たいと渇望した。この渇望に沿って、彼はすべての狂気の行動を試みた。最終的に、彼は融食裂隙に飛び込み、融食液で絵を描き、自身をその恐ろしい黒の中に完全にさらけ出した。\n誰もが自分の成し遂げるべきことを持っている。彼は世界の狂気の真実を見ることができる目を持ち、芸術のために燃えるために生まれてきたと信じていた。これが彼の使命だった。\n彼の願い通り、融食は彼に狂気と苦痛をもたらし、再び葬骸城で体験した光景を見せてくれた。彼の目の中のその倒錯した世界は、融食の侵蝕の下でより一層狂野で華やかになった。長い苦痛の中で、彼は筆を取り、日々、一刻も止まることなく描き続けた。彼は職務に忠実な写実派の画家であり、彼だけが見ることのできる光景を記録しなければならなかった。\n苦痛はますます強烈になり、ピックマンがもはや手の中の筆を握ることができなくなったとき、彼は自分の時間が来たことを理解した。最後の絵の最後の一筆を完成させた後、彼は自分があらかじめ用意していた棺に横たわり、死の訪れを待った。\n融食がもたらす痛みと混乱はピックマンの脳を濁らせ、死の冷たい抱擁の中で彼は安らかに目を閉じた。しかし翌日、明るい月光が再び彼を目覚めさせた。融食の痕跡と痛みは奇跡的に消え去った。数日間の成長の中で、彼の肢体は長く曲がり、犬歯と爪は硬く鋭くなった。彼は墓と魂の匂いを嗅ぎ取り、世界の狂気と混乱の光景が彼の目にはかつてないほど明瞭に映った。\n彼は自分の半人半ゾンビの体を喜びに満ちて見つめ、巨大な幸福感が胸に押し寄せた。運命は彼に呪いを与え、その呪いは彼の希少な才能を補った。葬骸城での経験は彼の体内に微薄なゾンビの血脈を呼び覚まし、融食の触媒の下で彼は自らの変貌を遂げた。\n周囲の墓碑はまるで集まった人々のように、彼を囲んで不器用な踊りを踊っていた。巨大な血月は猩紅の目を開き、彼に微笑んだ。彼の芸術はこの世界には属さず、今や彼は自分がどこへ行くのかを知っていた。\nピックマンは自分の棺の上に横たわり、両腕を広げてこの孤独な狂宴に加わった。\n彼は人間の都市を離れ、彼の約束の地へと向かおうとしていた。\n彼は、自分が追い求めているすべてが、そこで彼を待っていることを知っていた。"
  },
  AwakerStory_100416_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_100416_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_100417_Content = {
    Text = "半人半食屍鬼の絵師は、他人が到達し難い天賦を持ち、創作した食屍鬼の絵画は、絵の中の世界とリアルな世界の境界を曖昧にし、観る者を真に没入させる。\nしかしピックマンは決して狂気の超現実主義者という称号を認めない。彼の宣言の中で、彼は始終、リアルな世界を描く写実主義者である。"
  },
  AwakerStory_100417_Title = {
    Text = "基本情報"
  },
  AwakerStory_100417_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_100418_Content = {
    Text = "異類。怪物。モンスターの血が流れる悪種。芸術を冒涜する狂人……\nピックマンの目の前にはキャンバスが広がり、罵声と他の声が一緒になってキャンバスに鮮やかな色彩を塗りつけていく。\n彼はこの華やかな世界に飛び込み、狂気の色彩の中を泳ぎ回る。彼は切に願っていた、他の人々を自分の作品に導き、彼らに世界の最もリアルな姿を証見させることを。\n現実の尖刺が何度も彼の心臓を貫き、人と人との相互理解は二つの世界の境界を開くよりも難しい。\n人間から食屍鬼へ、人間の都市からネクロポリスへ、この道は曲がりくねり長い。彼は何度も中傷され、また何度も立ち上がった。彼はすでに理解していた、リアルも虚偽も存在しないことを。痛みと発狂こそが世界の真実であり、彼の使命はそれを忠実に描写することなのだ。\n描写の意味は、描写そのものにのみある。\n彼は全てのライフと情熱を絵に捧げた。彼の期待にはほとんど応えがなく、彼の追求は決して止まることがなかった。"
  },
  AwakerStory_100418_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_100418_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_100419_Content = {
    Text = "美術学院の絵画科の授業は冗長で退屈で、その大部分は私の人生に何の痕跡も残さなかったが、今でもA.F.3@2年の模写の授業を思い出すことができる。\nマシュー先生は芸術協会で非常に名声が高く、彼の教室は人でいっぱいだった。私たちはマティスの『贅沢、静けさ、楽しみ』の前に群がっていた。その時、私は偶然、隅にいる痩せた若者がスケッチブックに狂ったように描き込んでいるのに気づいた。私は彼の前に近づき、彼の模写を見ようとしたが、そこには墓群の雑然とした石彫が描かれていた。\n「見て！出産中の死体喰い女王が、赤ちゃんの血の宴を準備している……なんて狂気で、なんて優雅なんだ！」\n彼は興奮して私を見上げ、瞳孔はガス灯の下で奇妙な血のような赤色を呈しており、まるで苔に覆われた棺のようだった。私は恐怖と眩暈を感じたが、どうしても目を逸らすことができなかった。その目の中に、私はこの世界には全く属さない光景を見た。\nピックマン、彼に初めて会ったとき、私は彼が私たちとは違うことを知っていた。彼の人生は困難で非凡なものである運命にあるのだ。\n知り合いになってから、私は時々彼のアトリエを訪れた。私は彼が腐敗した死体をモデルにし、自分の鮮血を絵の具にしているのを目の当たりにした。あの狂気の作品の前に立つと、私はキャンバスの中から聞こえてくる噛み砕く音が聞こえるような気がした。\n芸術界のどの流派も、誰もピックマンの創作を認めなかった。すべての展覧会やサロンは彼を拒絶した。彼はまったく気にしていないように見え、依然として楽観的で堅実に芸術を追求し続けたが、彼の純粋さは彼が自らの喪失と痛みを隠すことを決して許さなかった。彼の才能は衝撃的で恐ろしいもので、誰もそれを真に受け入れることができなかった。私も同様だ。\n去る前の最後の時間、ピックマンは巨大な苦痛と興奮が交錯する状態に陥った。私はそれが何らかの必然的に起こる心理的問題だと思っていたが、ある日、彼の曲がった四肢と爪、彼の目の中にある狂った世界を目の当たりにした。その恐怖に抗うことはできず、ただ忘れようと努力するしかなかった。私がピックマンとの関係を完全に終わらせる準備をしていると、彼は自ら私のところにやってきて、別れを告げた。\n今、私は現代美術館の光沢のある展示室に立ち、隅に捨てられたピックマンの本物の作品を見ていると、キャンバスの奥深くから爪が引っかく音が聞こえてくる。『地下の狂宴』、それは私がピックマンに初めて出会ったときに彼が創作した絵であり、彼が私に残した別れの贈り物だ。ピックマンには近づくべきではない禁忌の謎があるかもしれないが、私はその絵を残しておいた。彼に起こったことは私が知るべきではないことかもしれないが、少なくとも一つは確かなことがある——彼は私が見た中で最も才能のある芸術家だ。\n昨夜、私はまた一年生の絵画の授業の教室を夢見た。若きピックマンが部屋の隅で、私に向かって大声で笑っていた。\n「死体喰い？違う、エヴァー、私が描いているのは真実、人間そのものだ！」\n月光が彼の目の中で無数の惨紅の星点に分裂していた。それは深淵が初めて私に微笑みを見せた瞬間だった。\n\n——『画家エヴァー回想録』より抜粋"
  },
  AwakerStory_100419_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_100419_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_11158_Content = {
    Text = "時間：A.F. 299年@1月@2日\n場所：実験室UG-C03、@2@1、@4、ロンディニウム。\n参加者：@1、@2、@4、@3\n実験対象：W\n被験者情報：\n体は成人女性で、A.F. 280年6月18日生まれ。出身地不明。@2大学在学中に病気で死亡。その後、地球外精神生命体@1が体を占有し、生命を取り戻し、元の生活を続けている。\n@1は精神の移動と変換の能力を持ち、融蝕を直感的に観察できる。人間の体では融蝕を観察できないが、@1の種族の能力により、被験者は精神的に融蝕の存在を感じ取っている。そのため、被験者は2年8ヶ月前に初めて融蝕を観測した際、さらなる侵蝕を避けるために精神移動を試みた。\n@1は融蝕を感知する能力を保持しているが、被験者はその影響から逃れることができず、精神体の移動に失敗した。何度も試みた結果、被験者は@3大学に自らを覚醒体にするよう依頼し、今回の実験が行われた。\n——《実験記録：生体からのシルバーコア抽出の可能性》より抜粋"
  },
  AwakerStory_11158_Title = {
    Text = "物語・一"
  },
  AwakerStory_11158_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11159_Content = {
    Text = "銀の鈴のような甘い笑い声が空虚に響き、小柄な体が薄暗いろうそくの光の中に浮かび上がる。\n彼女は罪人の恐怖と渇望、死にゆく者の甘露と毒酒、甘美な痛みとロマンティックな狂気をもたらす。\n彼女がいつも手から離さない鞭が、肉体に叩きつけられる「パチン」という音は、闇の中で奏でられる邪悪な旋律だ。"
  },
  AwakerStory_11159_Title = {
    Text = "基本資料"
  },
  AwakerStory_11159_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11160_Content = {
    Text = "ファイントと再会した後、ティンクトはミサゴ大学に落ち着きました。P-063号オペラハウス@2事件で再び負傷したティンクトは人見知りが激しくなり、引きこもりがちになりました。彼女の高らかな歌声とは対照的に、日常の会話の声は甘美で澄んでいますが、聞いたことのある人はほとんどいません。\n好奇心旺盛な人々は、ティンクトのためにキャンパスでの舞台を盛り上げようとし、どこからか彼女の若い頃のオペラハウスでの公演ポスターを見つけ出し、キャンパスのあちこちの宣伝コーナーに貼り出しました。\nティンクトはこれらの願望に応じたくなく、その熱意は彼女が忘れたい過去の記憶を再び呼び起こすだけです。\n「この馬鹿げた悲劇を終わらせたいのです。あなたがそばに居ればそれだけで良いのです。できることなら、この世界に忘れ去られても構わない」\n「いやよ、ティンクト。これから一緒に過ごす日々は長いの。ここはもう荒れた星じゃないし、私はもうあなたの重荷じゃない。自分のやりたいことを見つけて、自分のために生きるべきよ」"
  },
  AwakerStory_11160_Title = {
    Text = "物語・二"
  },
  AwakerStory_11160_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11161_Content = {
    Text = "ミサゴ大学では、「予科生はロータンと戦わなければ調査員になれない」というキャンパス伝説が広まり、学生たちの黒衣の女剣士への恐怖はピークに達していた。理論研究を専門とする学生の中には、黒いスカートの裾を見ただけで冷や汗をかき、「戦闘狂」と目が合って訓練場で命を落とすのではないかと怯える者もいた。\n編集長のハンナ・ピーズリーは、当事者と短い特別インタビューを行い、その中でロータンは次のように発言した。\n「赤ん坊のままごとに付き合うほど暇ではない」\n「弱虫は我の相手にふさわしくない——お前はその一人か？それとも、混沌に立ち向かう勇気があるのか？」\n\n——記事が発表されるまで、編集長は学生寮から出なかった。今号の《M大学新聞》は、インターン編集者のハワードによって印刷・発行された。"
  },
  AwakerStory_11161_Title = {
    Text = "物語・二"
  },
  AwakerStory_11161_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11162_Content = {
    Text = "A. F. 315年@1月@2日\nシルヴィア医師は私に考えをノートに書き留めるように勧めた。記憶力を鍛えるためだ。みんなが医者は多くのことを知っていると言っているので、きっと助けてくれるだろう。だからお願いだ、明日の私よ、このノートの使い道を忘れないでくれ！\n今日は排気管の製作と組み立てを終えた。これで排気ができるし、補助ホースの動きも邪魔しない。これが最後のステップだろうか？少なくとも今のところ問題は見つからないが、どこかのネジを忘れた可能性もある…………そうだ、何かを忘れているに違いない。ネジかパイプか、あるいはベアリングの潤滑？オイル？正直なところ、ずっとファントム号に何かが足りないと感じている。いつも何か…………欠けている？この言葉で合っているだろうか？エンジンよりも重要な何かが足りない。これがなければ、旅に出ることができない、未知への旅路に踏み出せない。なぜならそれは私たちの@2\nなぜ「私たち」と言ったのだろう？私と誰？私はかつて…………覚えている、たぶん、@2@4@3\nうーん、頭が痛い。\nでもこのノートは役に立ちそうだ。明日またここから思い出せるかもしれないし、もしかしたら本当に思い出せるかもしれない。\n——ナウティラの日記の唯一のページ。"
  },
  AwakerStory_11162_Title = {
    Text = "物語・四"
  },
  AwakerStory_11162_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11163_Content = {
    Text = "御心に触れられぬ者は哀れなものです。\n彼らは不滅の真意を理解できないのですから。\n世俗の争いなど、すべて空しいものです。\nそれは長き道中の浅はかな気晴らしに過ぎません。\n\nわたくしは直にその御姿を仰ぎ、その御業の素晴らしさを知り、すでにこの身の使命を悟っております。\n\nしかし……ああ、運命はなんと残酷なのでしょう！\nなぜあなた様は……最も忠実な祭司である、わたくしを再び選んでくださらなかったのですか？\n\n——きっとあなた様はわたくしに試練を与え、わたくしの信念を試しているのでしょう。\n故国から最も遠く、あなた様の恩寵が届かぬこのときにも、わたくしの信念は万年を経ても揺らぐことはございません。\n\nわたくしはあなた様の再生を迎える者にはなれませんでしたが、再生のためにすべての準備をいたしました。\nわたくしはあなた様のために新たな永遠の国を探します……\n悔恨も、栄誉も、わたくしの身に同時にあり、だからこそ、わたくしはこの責任を一人で負うしかないのです……\n\nどうか、わたくしの醜い嫉妬と憎しみをお赦しください。\n再びあなた様の威光を仰げるのであれば、再びあなた様の王国を築けるのならば、わたくしはどのようなことでも、喜んでいたしましょう。"
  },
  AwakerStory_11163_Title = {
    Text = "物語・四"
  },
  AwakerStory_11163_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11164_Content = {
    Text = "髪にはとりどりの珠玉や翡翠を飾り、薄絹のヴェールを纏って、その内心は極めて艶やかな美の下に隠されている。\n\nタイスを虚栄心の強い軽薄な女だと思い込む者も多いが、それもまた彼女が被っている仮面のひとつに過ぎないのかもしれない。\n\n「あら、何を書いているの？私も手伝うわ——」"
  },
  AwakerStory_11164_Title = {
    Text = "基本資料"
  },
  AwakerStory_11164_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11165_Content = {
    Text = "使用済みのフラスコは新品のように洗浄し、実験で焼けた机は反射するまで磨き、天秤は三日ごとに再校正する。科学と世界の神秘に対する熱狂と敬意から、彼女は周囲の人や物事に非常に高い要求を持っている。\nもちろん、この要求は彼女自身にも適用される——結局、すべての人が死を静かに受け入れ、覚醒体になることを自ら求めるわけではないのだから。"
  },
  AwakerStory_11165_Title = {
    Text = "基本資料"
  },
  AwakerStory_11165_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11166_Content = {
    Text = "A. F. 315年@1月@2日、08:13 a. m.\n審査会現場対応第三小隊及び融蝕物品管理（以下DISM）β7組のメンバーが融蝕区域L-E-933（サザーク・ストリート@2号、ロジャーズ蝋人形館跡地）に到着し、第一小隊とDISM α2組の任務を引き継ぎ、区域の無害化作業を行った。\n09:24 a. m.\nDISMメンバーのジェームズが蝋人形館の地下区域を清掃中に頭痛、吐き気、眩暈などの症状が現れた。\n10:47 a. m.\n第三小隊メンバーのローランド、DISMメンバーのザカリー、ボルトンが地下区域から逃走。三人の報告によると、地下区域の暗闇が彼らを飲み込み、星空の中に浮遊させ、形を持つ色が空間の中で互いに絡み合い、絢爛であると同時に全身が凍りつくような感覚を覚えたという。その後、それらの色が無数の鼠に凝集し、猛烈な速さで彼らに襲いかかった。\nボルトンは作業の続行を拒否し、審査会ロンディニウムオフィスに帰還。第三小隊のローランドとDISMのザカリーは、第三小隊隊長フィッシャーと共に再び地下区域に入り、関連の調査を行った。\n13:03 p. m.\n検査と捜索の結果、第三小隊隊長フィッシャーは地下区域に残留した融蝕蝋の中からシルバーコアL3202を発見し、回収した。その後の処置のため、ミサゴ大学に引き渡された。\n——『融蝕区域L-E-933無害化処理報告書』"
  },
  AwakerStory_11166_Title = {
    Text = "物語・一"
  },
  AwakerStory_11166_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11167_Content = {
    Text = "24は引っ越して1ヶ月も経たないうちに、家に泥棒が入ったことに気づいた。\n\n最初はチーズ、次にパン、牛乳、トマト……家の食べ物がいつの間にか少しずつ減っていく。\n彼女は何日も辛抱強く待ち続け、ついに犯人を見つけた。\nそれは鼠だった。\n鼠は24が仕掛けた罠を巧みにかわし、2つのマッシュルームを掴んで地下室の扉の向こうに消えた。\n\n24は地下室の扉を開けて、湿ったカビ臭い階段を下りていく。\nそこは下水道に通じていた。\n\n鼠はマッシュルームを持って影に飛び込んだ。\n24が後を追うと、暗闇の中に小さなオオカミのような明るい目が見えた。\nその子は汚れた布切れを身にまとい、氷点下に近い温度の中で古い新聞をかぶって震えていた。\n\n24の心が少し痛んだ。\n「そのマッシュルームは生で食べない方がいいわ。病気になるから」\n子供は相変わらず黙っている。\n\n24は上に行ってマッシュルームスープを作り、小さな深皿に盛ってテーブルに置き、寝床についた。\n彼女は毎朝6時に起きて仕事に行かなければならず、ほとんど休む時間がなかったのだ。\n\n翌日、目が覚めると、スープはきれいに飲み干されていた。\n\nそれ以来、24はときどき少し多めに料理を作り、下の階の隣人をもてなすようになった。\n相手もときどきお返しに、小さなアクセサリーやおもちゃなど、どこで拾ってきたのかわからない小さな贈り物をくれるようになった……\n\n新たな暗黙の了解が、ここに生まれた。"
  },
  AwakerStory_11167_Title = {
    Text = "物語・三"
  },
  AwakerStory_11167_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11167_UnlockDesc_1 = {
    Text = "メインストーリー第2章「蝋人形の名において」通常をクリア"
  },
  AwakerStory_11168_Content = {
    Text = "私たちの親友で、何でも知っているハンナ・ピーズリーは、どこからかシレストの研究資料を掘り出した。大胆な行動をするこの記者のおかげで、もともと機密レベルの資料と彼女たちの短いインタビューが、今では誰もが知るところとなった。\n\nハンナは機密資料を読んだ後、普段から感情に乏しいシレストに質問をした。\n「ほとんどの覚醒体には叶えられていない願いがあって、それが大学に協力する理由の一つなんだよね。けどこの資料では、キミの願いは空欄だ。キミにはやり遂げたいことがないの？キミが覚醒体になった意味はどこに？」 \n「あるの、私にはあるの」\n少女の表情はいつも通り虚無で高潔で、隙はなかった。短く焦った返事がなければ、記者は自分の質問が聞こえていないのかと思ったほどだ。\n「私は願いを見つけるわ……皆がそう望んでいるのだから、私は見つけるわ」\n優しい声は、まるで壊れやすい夢のようだった。"
  },
  AwakerStory_11168_Title = {
    Text = "物語・四"
  },
  AwakerStory_11168_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11169_Content = {
    Text = "一言一句に忠誠を、一挙一動に美徳を。\n「礼儀を守り、己に厳しくあれ」という言葉は、魂に深く刻まれている。だがこの美徳の騎士は、まだ子供の姿をしている。\n心配はいらない。たとえ永遠に消えることになろうとも、オジールは主君の命令を全力で果たすだろう。\nどうかその日が来ませんように。"
  },
  AwakerStory_11169_Title = {
    Text = "基本資料"
  },
  AwakerStory_11169_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11170_Content = {
    Text = "幼い王は王座で眠り、夢から覚めると詔を示し、権威は天下に及ぶ。\n夕日が沈む前に、王はすでに疲れていた。彼は自身の権能に飽き、超人的な知恵にも飽き、信者の狂信的な崇拝と供物にも飽き、万古を超える長い夢にも飽きていた。\n彼が長い眠りの中で何を夢見たのかは誰も知らないが、彼らはこの無知の幸福を享受すべきである。"
  },
  AwakerStory_11170_Title = {
    Text = "基本資料"
  },
  AwakerStory_11170_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11171_Content = {
    Text = "「慈悲深い父なる神はかつてこう諭した。『天のもの、地のもの、水のもの、土のものすべてを愛しなさい。なぜなら万物は私の子だから』」\n「だから私は言う。すべての苦しみを私に負わせなさい。そうすれば人生の困難と疫病に苦しむ者たちが解放され、病や狂気が雪のように溶けるでしょう。私の兄弟姉妹たちよ、あなた達が永遠の幸福を得られるように。\n「私を燃やし、骨を砕き、肉体を滅ぼしなさい。あなたたちが安らぎを得るなら、私は何の不満もない」\n――B.F. 1@1、5月30日、サル@1ド・マーティン@2・イ@1アス、@3審判所にて"
  },
  AwakerStory_11171_Title = {
    Text = "物語・四"
  },
  AwakerStory_11171_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11172_Content = {
    Text = "ファイントは色褪せた、殻を破るのが難しい種子だ。\n人々は彼女の欠陥を憐れみ、彼女の弱さを愛おしんだ。\n彼女が自ら殻に留まることを選んだと知っている人は、すでに粉々になり、星の塵となっている。"
  },
  AwakerStory_11172_Title = {
    Text = "基本資料"
  },
  AwakerStory_11172_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11173_Content = {
    Text = "@3@1事件の後、ライカーはミサゴ大学の特別顧問となった。\n\nライカーは実に有能な顧問だった。\n教授の不可解な失踪や、原因不明の機材の故障のような重大な出来事から、猫探しや犬探しのような些細なことまで、迅速で満足のいく結果を出した。\nやがて彼はその独特な容姿と、上品で優雅な物腰、そして人助けを厭わない美徳によって、ミサゴ大学の若者たちのアイドル的な存在となった。\nデクスター教授が「すっかり若者に主役を奪われてしまったよ」と嘆きの声をあげたほどだ。\n\nしかし、彼が次第に学内へ溶け込むにつれて、ライカーが人前に姿を見せる機会は、日を追うごとに減っていった。\nそれと同時に、ミサゴ大学のとある放棄された地下室で、ダイスを振る音が頻繁に響き始めていた。"
  },
  AwakerStory_11173_Title = {
    Text = "物語・二"
  },
  AwakerStory_11173_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11174_Content = {
    Text = "彼女を目にした瞬間、本能が叫ぶ。近づくな、話しかけるな、と。\n生存本能が全力で警告を叫ぶのだ——逃げろ、と。\n\n理性も残さぬ狂人。\nまたは紛れもない獣。\n生まれ変われるなら、彼女は迷わず獣を選んだだろう。人間として生きることは、それほどまでに苛酷だった。\n\n彼女は誰も信じない。\n深紅の双眸があなたを捉えたとき、そこにあるのは疑念ではない——冷酷さと殺意、それだけだ。\n\n疑う必要すらない。\nすべての人間が、彼女の目には等しく卑劣に映るのだから。\n\nひとつ忠告するなら——\n真の獣を飼い慣らそうなどとは考えないことだ。それは決して従順な存在ではない。少しでも隙を見せれば、鋭い爪と牙があなたの喉を貫く。\n\n彼女があなたを狙う前に逃げろ。そして祈れ——\n次の獲物が、あなたでないことを。"
  },
  AwakerStory_11174_Title = {
    Text = "物語・二"
  },
  AwakerStory_11174_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11175_Content = {
    Text = "踊りましょう！楽しいダンスを、狂ったダンスを！彼女と一緒に笑って、雰囲気を最高潮に盛り上げましょう。\nそうして、いよいよ主役の登場です。\nスポットライトの交差点で、狂気のマジシャンはすでに手を長いシルクハットに入れていました。果たして彼女がその無限の虚空から取り出したのは、カラフルなリボンなのか、羽ばたく白い鳩なのか、それとも恐ろしい怪物の鉤爪なのか……それは彼女にしかわからないでしょう。"
  },
  AwakerStory_11175_Title = {
    Text = "基本資料"
  },
  AwakerStory_11175_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11176_Content = {
    Text = "それはデクスター教授がフェイフル海岸からの旅行から戻った際に持ち帰った記念品だ。\nフェイフルの温暖な海洋気候は快適で、百年の歴史を持つセヴァダ療養所が海辺に位置し、毎年多くの旅行者がそこで休暇を楽しんでいる。\nこの水跡と海藻に絡まれたガラス瓶には、少量の透き通った粉末が入っている。それは海難者が残した漂流瓶でも、地元の砂利工芸品でもない。デクスター教授は明らかに気づいていた。その瓶にはシルバーコアの粉末が入っており、つまりそれはそこに宿る意志だ。\n彼はそれを地元の漁師から買ったと言い、漁師は最近遭遇した奇妙な出来事を曖昧に語った。数日前の朝、漁師が海に出た際、奇妙な魚群に遭遇した。産卵や越冬の時期ではないのに、魚群が一箇所に集まり続けていた。重い漁網を引き上げると、奇妙な瓶が網にかかっていた。漁師はそれを不思議に思い、不安を感じた。まるでこの奇妙な瓶に呪われ、不運をもたらされるかのように。その後数日、この海域では魚が全く捕れなくなった。"
  },
  AwakerStory_11176_Title = {
    Text = "物語・一"
  },
  AwakerStory_11176_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11177_Content = {
    Text = "算数：0点。オレッタでさえ2点を取った。\n英語：不合格。「shift」（シフト勤務）と「shit」（クソ）の違いを理解するのに長時間かかった。\n…………\n歴史：不合格。カリグラを最も偉大なローマ皇帝と主張した。理由は彼が多くの競技場を建てたから。\n\n危険評価：C。他の覚醒体と接する際、一定の攻撃性を示す。大きな脅威はなく、特別な注意は不要。\n備考：この学生の自立能力はほぼゼロ（また一人、奴隷制に毒された者）、常に注意が必要で、彼女が再び美肌クリームを歯磨き粉として使わないようにしなければならない。\n――A. F. 313年「ミサゴ年間学生記録」より抜粋"
  },
  AwakerStory_11177_Title = {
    Text = "物語・二"
  },
  AwakerStory_11177_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11178_Content = {
    Text = "@2年、アッコ古城。\n千年の渇望がついに爆発し、殺戮、血を飲み、殺戮、血を飲む——最後に彼の前には広がる砂漠と無数の乾いた死体だけが残り、ハゲワシさえも彼に近づくことを恐れた。\n彼は砂の中で跪き、大笑いした。爽快だ！本当に@1爽快だ！\n次は彼自身がこの殺戮の宴に完璧な終止符を打つ番だ。\n戦士は自分の手首を噛み切り、自分の血を吸い尽くし、この赤い血の池に倒れた。"
  },
  AwakerStory_11178_Title = {
    Text = "物語・四"
  },
  AwakerStory_11178_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11179_Content = {
    Text = "「オルラ、今日からあなたの詩は私が大切に保管するね。これからは私の花と、あなたの詩を交換しよう！」\n「コレット、あなたはきっと戻ってきて、わたくしを助けてくれますよね……？」"
  },
  AwakerStory_11179_Title = {
    Text = "物語・四"
  },
  AwakerStory_11179_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11180_Content = {
    Text = "昨日午後18時、ミサゴ大学プリンスビル地下のCB-101室が何者かに破壊された。\n補強されたドアはひどく損傷し、内外の壁には黒い稲妻状の焦げ跡があり、現場は荒れ果てていた。\n\n「瞬間的な強電流がこのような痕跡を残すことがある」と電気工学のアダムス博士は壁の焦げ跡についてこう評価した。\n「これは非常に大きな電圧を必要とする。\n普通の機器なら非常に大きく、目立つだろう。\nしかしシルバーコアなら…………何でもあり得る」\n\nシルバーコアは長年、覚醒学部の厳重な管理下に置かれており、誰にも気づかれずにシルバーコアを使用することは難しい。\nそのため、体内にシルバーコアのエネルギーを持つ覚醒体に注目が集まっている。\n\n「これは絶対に彼女の仕業だ」と匿名の覚醒学部の学生が記者に語った。\n具体的に誰のことか尋ねられると、彼は少し緊張した様子で「『彼女』だよ、『チクタクマン』と呼ばれているあいつだ！\n彼女の体の中の電流音を聞いたことがないのか？\n電流といえば彼女を思い出すんだ、絶対そうだよ」\n多くの学生が同様の疑いを表明した。\n\nしかし、このゼンマイ仕掛けの人形のように行動し、奇妙な微笑みを浮かべる覚醒体は孤立しておらず、数人の調査員が公然とエリカを支持し、事実と証拠に基づいて個人的な偏見で他人を傷つけないよう呼びかけた。\n\nこれに対し、覚醒学部の代理責任者であるソコロワ博士はコメントを拒否した。\n事件は現在も調査中である。\n——「ミサゴ日報」、「CB-101室爆発事件初探」より抜粋"
  },
  AwakerStory_11180_Title = {
    Text = "物語・二"
  },
  AwakerStory_11180_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11181_Content = {
    Text = "彼女はいつも傲慢に「神の母」と名乗り、冷淡で敵意に満ちた態度で、すべての人を自分の安全圏の外に締め出している。初めて会う人には、彼女をあのわがままな小さなお姫様と結びつけることは難しい。\n「でも本質的には同じ人ですよ」と守秘者はいつも頑固に皆に伝える。「彼女が一人でケーキをがつがつ食べる姿を見れば分かります。」"
  },
  AwakerStory_11181_Title = {
    Text = "基本資料"
  },
  AwakerStory_11181_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11182_Content = {
    Text = "天才と狂人は紙一重。かつてミサゴで最も輝かしい天才だった彼女の堕落は、大きな建物が崩れるように、理性の廃墟から這い出たのは、最も狂気に満ちた悪鬼だけだった。\n彼女はいつものように科学の衣をまとい、生命、人間性、愛と破壊を坩堝に注ぎ込み、世界を破壊する毒薬を作り上げた。"
  },
  AwakerStory_11182_Title = {
    Text = "基本資料"
  },
  AwakerStory_11182_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11183_Content = {
    Text = "クラゲの知性に期待を抱かないでください、オレッタは自分が何を経験したか理解できません、唯一確かなのは、彼女がかつてその無人村に住んでいたことです。過去の話をするたびに、彼女はわからないふりをして話題をそらすため、オレッタは融蝕現象や災厄異動などの学問研究にほとんど役立ちません。\nしかし、覚醒体の中で珍しく無害な性格の個体として、オレッタは覚醒学部の教師や学生に愛され、融蝕生物学研究を主導するハレトも彼女を特に気にかけています。\nちなみに、クラゲの群体意識と融合した彼女は分裂増殖の能力を得ました。たとえ増殖したのが普通のクラゲであっても、オレッタは「仲間」を持ち歩いて家々を自慢しに行きます——仲間の個体を区別できない彼女は、毎回同じクラゲを見せていることに気づいていません。"
  },
  AwakerStory_11183_Title = {
    Text = "物語・二"
  },
  AwakerStory_11183_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11184_Content = {
    Text = "■ファイル番号：AF315-C01\n■覚醒体コードネーム：@2行者\nこの覚醒体はA.F.315年@1月に初めて観測された。\n「人工密境」実験を初めて行った際、同源の精神共鳴の影響を受け、我が校の@2級学生ラモンナ・デクスターの精神領域を基にした「人工密境」が次元の境界を突破した。\n当時の守秘者はその「人工密境」で、次元外の世界の存在を初めて確認し、同時に@2の力がラモンナ・デクスターにどのような影響を与えるかを確認した。\nその後、覚醒学研究所は「真貌覚醒体」に関する研究を正式に開始した。\n同時に、ラモンナ・デクスターの力の制御に関する授業計画も進行中である。"
  },
  AwakerStory_11184_Title = {
    Text = "物語・一"
  },
  AwakerStory_11184_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11185_Content = {
    Text = "黒いヴェール、長いローブ、その下の痩せこけた体。\n\n彼女は静かに佇み、信仰と悲哀の入り混じった表情を浮かべる。\nまるで壁画の聖母像のように、底知れない神秘的な雰囲気を漂わせている。\n\n彼女は全身全霊を注ぎ、特別な時を待っている。\nその約束の日はまもなく訪れようとしている……"
  },
  AwakerStory_11185_Title = {
    Text = "基本資料"
  },
  AwakerStory_11185_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11186_Content = {
    Text = "シレストは入学してすぐ、ドールに連れられて全面的な評価を受けた。\n大学のプロセスを経ずに召喚された覚醒体として、シレストの精神状態は驚くほど安定していた。\nしかしそれに反して、精神体の強度も、シルバーコアの強度の判断基準であるノース指数も、シレストは覚醒体の基準に遠く及ばなかった。\nしかし、虚空に咲く無形の花のように、彼女は覚醒体として世界に降臨した。\n日常活動や外勤任務では異常は見られなかったが、データモニタリングによって、シレストの状況は楽観視できないことがわかった。彼女の体からは、微弱な意志が絶えず流出している。\n現在、覚醒学部は小規模な教団を準備しており、信仰を供給することでシレストの存在を維持しようとしている。参加希望者で水に精通している者は、シルヴィア先生に連絡してほしい。"
  },
  AwakerStory_11186_Title = {
    Text = "物語・二"
  },
  AwakerStory_11186_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11187_Content = {
    Text = "彼の首には大きな傷跡がある。彼の同族は傷跡から死を得たが、彼は傷跡から力を得た。\n領地を追放された負け犬は、敗北と絶望の苦味を舐め、広大な海に囚われたとき、神に超越の力を祈った。\n神の使徒は祈りに応え、彼の首を切り落とした。\n神の使徒は祈りに応え、断首に不朽の欠片を植え付けた。\n神の使徒は祈りに応え、彼を永遠の命の殿堂へと導いた。"
  },
  AwakerStory_11187_Title = {
    Text = "物語・三"
  },
  AwakerStory_11187_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11188_Content = {
    Text = "彼女は羨まれるような生まれを持っていた。唯一の後継者として育てられた孤児。なんて幸運なのだろう。\n彼女は驚くべき天賦の才を持っていた。一歳で話し、二歳で議論し、三歳で世界へ啓蒙を始めた。\n彼女は称賛される才能を持っていた。一度見たものを忘れず、剣を握れば技を習得。驚くべき若さで、ミサゴ大学の厳しい予科課程を満点で通過した。\n彼女には背中を預け合い、共に暗黒と未知に向かう価値のある仲間がいた。\n<Italic:彼女には……>"
  },
  AwakerStory_11188_Title = {
    Text = "物語・三"
  },
  AwakerStory_11188_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11189_Content = {
    Text = "ドールの加入は、ミサゴ大学が外界から見た唯一の輝かしい瞬間だった。\n学界の多くの人々は嘆いた。天才が世俗の束縛から逃れられないことを嘆いた——彼女が財を求めて、名もない大学に組みこまれ、金銭に染まったことを。\n外界が彼女の堕落を非難する中で、ドールはミサゴで金よりも貴重なものを手に入れた。\n彼女は物質科学の境界を越え、現実の領域のヴェールに触れることができた。そのヴェールの下には、彼女が命をかけて追求したいものが隠されていた。\n「シルバーコアテクノロジー」の研究の危険性は、刃の上で踊ることに匹敵し、ドールは最も真剣で勤勉で優れたダンサーとなった。\n融蝕痕が現れたとき、科学のダンサーも踊りを止めず、限られた時間を大切にした。\nたとえ融蝕痕が心にまで広がり、理性を侵食しても。\nそれでも、彼女は真理の中心からはまだ遠かった。\nそのため、生命の火がすでに薄暗くなり、知識を求める光が依然としてまばゆい星は、次のような遺言を残した。「世界がわたしを忘れる前に、わたしを目覚めさせて」"
  },
  AwakerStory_11189_Title = {
    Text = "物語・三"
  },
  AwakerStory_11189_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11190_Content = {
    Text = "司教様が学校を訪れるたびに、教師や学生たちは熱烈に歓迎する。\n心がまだ未熟な覚醒体たちは彼の手を引いて、洪積暦以前の話をもっと聞かせてとせがむ。学生たちは自ら近づいてきて、自分の悩みを聞いていただけますかと司教に尋ねる。一見すると冷たく強靭に見える覚醒体たちや、豊富な見識を持つ教授たちでさえ、司教に暇ができたときには声をかける――ある者は自分の悪夢を語り、ある者は魂の本質について語り合おうと。\n彼はいつも変わらず、辛抱強く、決して面倒がらずに耳を傾ける。誰であっても、彼のもとでは受け入れられ、温もりを得ることができた。\n「もちろんです、我が子よ。私にできることはありますか？」"
  },
  AwakerStory_11190_Title = {
    Text = "物語・二"
  },
  AwakerStory_11190_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11192_Content = {
    Text = "彼女はすべての人、すべての覚醒体に非常に友好的で、攻撃的な傾向を示したことはない。\nほとんどの場合、彼女は静かに部屋にいて、窓の外を眺めている。彼女のベッドのそばには、何度も読まれた古典小説と、メモ用紙に書かれた繊細な字の随筆詩がいくつか見つかった。\n「あの少女に比べれば、私は明らかに幸運だ」彼女は夕日に向かい、きらめくキャンパスの池にささやいた。\n彼女はあまり屋外活動に参加しない。参加したくないというより、どう参加すればいいのかわからないのだろう…………その少女の姿をした覚醒体は、多くの生活常識を欠いているようだ。\n私たちは何度か目撃した。彼女が噴水の魚たちと対話しているのを。泡を吐くような、溺れた者のようなかすれた低い声で。しかし彼女の表情は穏やかで、親しい友人と慰め合い、語り合っているかのようだった。その瞬間、私たちは彼女が本当の安らぎを得たと信じた。"
  },
  AwakerStory_11192_Title = {
    Text = "物語・二"
  },
  AwakerStory_11192_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11193_Content = {
    Text = "今さら「自分の生活」を語るのは、少し無理があるかもしれません。\n私はすでに高空の外に消え、星海に隠れることに慣れています。\n観客が見ているのは私ではなく、オルゴールとして楽しむのも私ではなく、荒れた星空を漂うのも私ではありません。それは生計のために歌声を売る道具であり、ファイントを探すために彷徨う生ける屍です。他人を信じる価値が自分よりも高いと信じることで、すべての努力が価値あるものだと信じられるのです。\nだから、今さら私に気づかせないでください。\n\n「でも、妹よ、過去に囚われ続けないで。\n目を開けて見てごらん？あなたの唯一無二の歌声は、すでに宇宙に響き渡っているのよ」"
  },
  AwakerStory_11193_Title = {
    Text = "物語・四"
  },
  AwakerStory_11193_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11195_Content = {
    Text = "アルバは彼女の義肢に非常に満足している。\n「あの戦いの後、もう立ち上がれないと思っていた。再び正義のために戦える機会を得たことは俺の誇りだ」\n寮から聞こえる真夜中の低い呻き声は、新しい日の出と共に存在しなかったことにしよう。"
  },
  AwakerStory_11195_Title = {
    Text = "基本資料"
  },
  AwakerStory_11195_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11196_Content = {
    Text = "ミリアムは校内で質素な苦行生活を送っている。独りで、静かに考え、祈り、掃除し、働く。繰り返し、日々を過ごす。\n他人の敬意や警戒、議論や好奇心に対して、彼女は無関心である。故国を離れたキャンパスで、彼女は新しい精神修行の方法を見つけたようだ。\n実際、彼女は人と話すことを嫌がらない。ただ、少しの時間を割いて彼女の話を聞いてくれるなら、彼女は不滅の神の偉大さ、史前の遠い文明と賢明な幼王が治める永遠の国について語る。これを話すたびに、彼女の目には聞き手が見たことのない憐れみが浮かぶ。\n注目すべきは、ミリアムがトゥルーに対して異常な執着と尊敬を抱いていることだ。トゥルーは彼女に特別な態度を示していないにもかかわらず。\nもしミリアムと交渉する必要があるなら、トゥルーに頼むことで状況が有利に変わるかもしれない。"
  },
  AwakerStory_11196_Title = {
    Text = "物語・二"
  },
  AwakerStory_11196_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11197_Content = {
    Text = "召喚されてから三ヶ月目、調査員たちと守秘者はナウティラのためにチームを開いた。彼女がここに来たことを祝うのではなく、彼女がついにミサゴ大学の名前を覚えたことを祝うために。\n彼女は翌日にはまた忘れてしまったが、チームはまた開ける。誰にもわからないが、もしかしたら三ヶ月後には本当に覚えるかもしれない。\nナウティラの金魚のような記憶力が融蝕の後遺症なのか、シルバーコアの欠損の結果なのかはわからない。しかし、短期記憶が必ずしも悪いことを意味するわけではない。仕事に真剣に取り組む機械工にとって、どのネジを締めたかを忘れることは、すべてのネジをもう一度、二度、三度締め直すことを意味する。したがって、ナウティラの手で修理された機械は、他の機械よりも頑丈な構造を持ち、より長い寿命を持つことが多い。\nドールはそのため彼女を非常に気に入っている。結局、誰もが一度の修理で十年持つ技術を持っているわけではない。"
  },
  AwakerStory_11197_Title = {
    Text = "物語・二"
  },
  AwakerStory_11197_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11198_Content = {
    Text = "ドールは彼女について非常に詳細な調査を行ったが、胴体や四肢、頭部や骨盤のどこにも、彼女が声を出すための部品は見つからなかった。彼女がどのように話しているのかは、ミサゴの数多くの未解決の謎の一つとなっている。ほとんどの場合、彼女は普通に人と会話できるが、時折その謎の発声部位が意識を持っているかのように、ゾッとするような言葉を発することがある。"
  },
  AwakerStory_11198_Title = {
    Text = "基本資料"
  },
  AwakerStory_11198_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11199_Content = {
    Text = "ハンナ：解名前に何があったか覚えてる？\nエリカ：オートマタの行動が制御不能になり始め、意識に断層が生じ、その断層の間にすべてを破壊するすべてが電流と炎の中で滅び……\nハンナ：エリカ？\nエリカ：……\nハンナ：「チクタクマン効果」に遭遇するなんて、私の運もここまでかな……エリカ？\n\nエリカ：頭部コンポーネントが再起動しました。\n先ほどはご不便をおかけして申し訳ありません。\n先ほど申し上げたように、オートマタは自分が人類にとって脅威であることを認識し始め、当時オートマタはまだ自分を人間だと考えていたため、非常に苦しんでいました。\nハンナ：さっき言ってた保護って、人間を守るってこと？\nエリカ：オートマタは保護を望んでいました、その通り。\nハンナ：じゃあ、なんでさっき教えてくれなかったの？\nエリカ：……\n\nハンナ：質問を変えたほうがいい？\nエリカ：いいえ。今の私は感情に囚われていないので、答えられます。\n自分が危険であることを認識したオートマタは、意識の断片が生じる前に体をショートさせ、体が自ら破壊を引き起こす可能性を減らそうとした。\n保護は最終的に失敗し、人間の友人は死んだ。\nオートマタは悲しみ、後悔し、絶望した。\nオートマタは爆発して自爆し、これ以上の破壊を引き起こさないようにした。\nその後、シルバーコアはミサゴ大学に回収され、私、エリカ、躯体番号EA307881が作られた。\n\n——ハンナ・ピーズリーの録音《0711、チクタクマンインタビュー》より抜粋"
  },
  AwakerStory_11199_Title = {
    Text = "物語・四"
  },
  AwakerStory_11199_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11200_Content = {
    Text = "海水が特に澄んだ漁村、真夏の夜に天の川のように飾られた海岸、巡回キャラバンの軽やかな笑い声が響く——そんなもう存在しない記憶が時折フラッシュバックし、すぐに忘れ去られる。\n仲間がそばにいれば、いつでも新しい思い出を作れるし、クラゲたちもいる——オレッタはそう考えている。\n結局、流れに身を任せて繁殖し、数で強敵に対抗するのがクラゲの本能と運命なのだから。"
  },
  AwakerStory_11200_Title = {
    Text = "物語・四"
  },
  AwakerStory_11200_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11201_Content = {
    Text = "「パンディアには気をつけろ、彼女の危険性は見た目とは全く違う。彼女は悪魔だ」\nこれは無数の調査員の血と涙の経験から生まれた心からの言葉だ。\nパンディアはいつも甘い罠を仕掛け、他の研究者や覚醒体を主従契約に誘い込み、相手の感情と魂を弄ぶ。\nパンディアとの会話は無駄に終わり、彼女は新しい恋人と共に喜びの種を作り、共有し、撒いているだけだと主張する。契約は双方の合意によるものだと。結局、彼女も奴隷たちに甘い果実を味わわせているのだから。\nしかし、校内にはパンディアの天敵もいる。ソレールがパンディアの宿舎の前を通ると、どんな話題をしていてもパンディアは突然黙りこむという噂がある。パンディアはソレールを誘惑しようとして大きな攻撃を受けたことがあるらしいが、真相は未だに謎のままだ。"
  },
  AwakerStory_11201_Title = {
    Text = "物語・二"
  },
  AwakerStory_11201_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11202_Content = {
    Text = "A.F.297年@1月@1日03時47分、アグロ共和国@3州@1@2@1町の南東で不明な爆発が発生。衝撃波により、現地でマグニチュード3.8の地震が発生し、@1@2@1町から5キロ離れた村々にも影響を及ぼした。事件後、@1@2@1町は他の地域との連絡を失い、周辺住民は町の所在を思い出せなくなった。これを受け、審査会はメンバーを派遣して調査を行い、@1@2@1町の境界で融蝕物質を検出した。町を封鎖した後、ミサゴ大学の調査員が融蝕生物の除去作業を行い、爆発の中心と思われる強融蝕領域からE-1929号シルバーコアを回収した。E-1929は特殊で、霊性指数が長期にわたり不規則に変動し、歯車のようなカチカチという音を自発的に発する。強融蝕領域から回収された機械の破片と接続することで、短期間の安定を維持できる。この特性に基づき、ミサゴ大学覚醒学部は機械の破片でE-1929を包み、霊性指数が安定した後、迅速に覚醒を行った。——《E-1929シルバーコアの取得および覚醒報告書の要約》"
  },
  AwakerStory_11202_Title = {
    Text = "物語・一"
  },
  AwakerStory_11202_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11203_Content = {
    Text = "歴史の怒りがすべてを焼き尽くす前、アグリッパはカプアの最も輝かしい宝石だった。\n彼女は傍若無人で、鞭はいつも沈黙の剣闘士に激しく振り下ろされた。彼女は直視されることを嫌い、それが彼女の内なる弱さを露呈するからだ。しかし奴隷を調教することにかけては、アグリッパはプロであり、彼女の寝室にある20本の異なるデザインの鞭を見学することに興味があるかもしれない——特にあなたのために用意されたものだ。"
  },
  AwakerStory_11203_Title = {
    Text = "基本資料"
  },
  AwakerStory_11203_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11204_Content = {
    Text = "柔らかい黒髪、ふっくらとした頬、宝石のように輝く瞳、赤い唇——カレンはその美貌ゆえに幼い頃から優遇されてきた。大人になってからは、毎日男たちが贈るプレゼントや花が、家の前に小山を作るほどだった。だから、宮殿の執事が彼女を宮殿に連れて行き、高貴な王の侍女として訓練すると発表したときも、彼女は驚かなかった。当然のことではないか？彼女は生まれつき羨望を集める存在であり、生まれつき特別であり、生まれつき人々の注目を集めるべき存在だった。\nしかし、宮殿には美しいものが溢れていた。小さな町の花はどれほど美しくても、ここでは普通で素朴に見える。美貌ではもう特別な待遇を受けられず、彼女が憧れていた百年祭の宴で大広間に入って仕える機会も、別の少女に奪われてしまった。\nどうして？あの子にあるものはカレンにもあるのに、どうしてカレンじゃないの？\nそして彼女は、相手の耳にかかっている銀のイヤリングを見て、ハッとした。\n宴の日、彼女は少女を湖で溺れさせ、あの銀白のイヤリングを手に入れた。彼女は念願通り侍女の中で最も輝く存在となり、王の側に仕えることを許された。羨望や嫉妒の目が彼女を喜ばせた——そう、そう、すべてはこうあるべき、これが彼女の人生で最も幸せな日だった。\nその後、彼女は王城全体を飲み込む緑色の濃霧の中で、人生の終わりを迎えた。"
  },
  AwakerStory_11204_Title = {
    Text = "物語・三"
  },
  AwakerStory_11204_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11205_Content = {
    Text = "夢は記憶の投影であり、日常生活の縮図であり、人間そのものの総集だ。\n幼い頃から、ラモンナは同じ夢をよく見ていた。\n暖かく濁った水の中に身を置き、未知の存在と唇を重ね、単調な鼓動が水中で波紋を広げる。\n夢から覚めると、心のどこかが空虚に感じられ、何かが彼女の命から奪われ、消されたように思えた。\nしかし、父が心配する顔を見せないために、忙しい師匠たちに迷惑をかけないために、ラモンナは喉から飛び出しそうな疑問を飲み込み、日常に戻った。"
  },
  AwakerStory_11205_Title = {
    Text = "物語・三"
  },
  AwakerStory_11205_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11206_Content = {
    Text = "この世に生を受けてから、彼女が味わったものは苦しみだけだった。善良さ、寛容、同情、信頼——人の心の柔らかな部分はことごとく抉り取られ、血肉を滴らせたまま投げ捨てられた。\n\n彼女の辞書に、許しという文字はない。血と憎しみを消し去れるものがあるとすれば、それは他者の血と憎しみだけだ。\n\n血には血を——\n戦士も奴隷も等しく信じる、最も公平な掟。\n\n千年分の怒りが、一夜にして噴き出した。冥界から一本の手が伸び、人の世へと這い出した。\n\nそれは復讐の悪霊。この世を紅い河で満たすまで、決して止まらない。"
  },
  AwakerStory_11206_Title = {
    Text = "物語・四"
  },
  AwakerStory_11206_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11207_Content = {
    Text = "「お母さん、お母さん、リリーは注射で泣かなかったよ！」\n「リリーは本当に勇敢だね！」\n「うん、リリーは痛くないよ、お母さんが戻ってきてくれると思うと痛くないの！」\n……\n「ご主人、命令をください」\n「手術台に横になって、15分後に手術を始める。薬は時間通りに飲んだか？」\n「飲みました、ご主人」\n「ここを切っても痛くないか？」\n\n「……痛くないです、ご主人」"
  },
  AwakerStory_11207_Title = {
    Text = "物語・三"
  },
  AwakerStory_11207_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11207_UnlockDesc_1 = {
    Text = "メイン第4章「無音の中で」通常をクリア"
  },
  AwakerStory_11208_Content = {
    Text = "オルラには不思議な魔力があるようだった。\n詩や美を愛する教師や学生たちは、いつも知らず知らずのうちに彼女に引き寄せられ、その傍らに集まるのだ。\n\nオルラは自分の詩を発表することを好まなかった。\nそれでも、ミサゴ大学の学生たちはあらゆる手を尽くし、彼女のわずかな言葉の断片を目にしようとした。\n彼女の筆先から流れ出る詩句は、いつも瞬く間に学内で広まり、人気を博した。\n\n朝露が降りると、誰かが鐘楼の下で彼女の詩をそっと口ずさんでいる。\n夕暮れ、ニムフィーアは広場のベンチに座り、彼女の詩集をめくる。\n夜になると、学生たちは講堂に集まり、彼女の書いた詩を元にした劇を演じる。\n\nしかし、どんなに熱心に誘われても、オルラはこれらの活動に目を向けることはほとんどなく、ましてや自ら参加することもなかった。\n哀愁を帯びた調べや涙を誘う場面は、彼女に居心地の悪さを感じさせることが多かった。\n\n「わたくしは、また新しい悲しみを広めてしまったのでしょうか……？」"
  },
  AwakerStory_11208_Title = {
    Text = "物語・二"
  },
  AwakerStory_11208_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11209_Content = {
    Text = "ラモンナが初めてキャンパスに現れたとき、大騒ぎが起こった。\n覚醒体があちこちにいて、変わり者がどこにでもいるミサゴ大学では、銀髪や異なる瞳は特に気にするほどの特徴ではない。ラモンナが話題になったのは、彼女が「教授の娘」であるという身分だった。\n皆が数学科のオフィスの前に集まり、デクスター嬢の姿を一目見ようとした。人が多すぎて、教授はロータンに助けを求め、ようやく人々は渋々と散っていった。\nラモンナが少し成長し、教授がようやく安心して彼女をキャンパスで自由に走り回らせるようになったとき、ロータンに追い払われた学生たちは再び彼女に話しかける機会を得た。\n「勲爵夫人はどんな人かって？ごめんなさい、その人物は今のところ存在しないの。私は孤児で、父が親切に養子にしてくれただけだから」\n絡まれるのを避けるため、小さな少女は冷静に真実を語り、皆が罪悪感に陥っている隙に、悠然と去った。"
  },
  AwakerStory_11209_Title = {
    Text = "物語・一"
  },
  AwakerStory_11209_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11210_Content = {
    Text = "それは……目を眩ませるような天光と熱波、声色に溺れる極楽の狂宴。\n歓声が波のように耳元で鳴り響き、戦士は競技場で血と栄光を浴びる。\n少女は不満げに家に帰り、いつものように鞭を振り、無情に目の前の無口な剣闘士を打つ。\n\nここが彼女の戦場だ。\n\n激しい対決も、花や拍手もない。高い勇士たちは最も従順な鹿であり、彼女のすべての罵りと怒りは暗い空洞に吸い込まれ、一片の風も残らない。"
  },
  AwakerStory_11210_Title = {
    Text = "物語・四"
  },
  AwakerStory_11210_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11211_Content = {
    Text = "一目でわかる小柄な姉とは異なり、ティンクトの異形は他の面に現れています。\nヤドリギでも、ヤドカリでも、ティンクトは他の個体から離れると生きられない精神体のようです。\n荒れた星にいた時、彼女がしたことはすべてファイントの病を治すためで、姉の命を維持するためのあらゆる方法を試みました。たとえ常人には耐えられない代償を払うことになっても。\n貴族たちの嘲笑や侮辱を気にせず、常に穏やかに不平等な取引を行い、彼らの慈悲を求めました――その慈悲は彼女に荒れた星から逃れる席をもたらしましたが、彼女は手に入れた瞬間、ためらわずにファイントに譲りました。\nファイントは最後の瞬間にティンクトを荒れた星から逃れる星流に押し上げました――妹が自分から解放され、新しい星で人生を始めることを望んで。\nしかし荒れた星が消滅した後、ティンクトはファイントを探すために自我を失った漂流の旅に出ました。他人に操られることも気にせず。そんなティンクトは@2教会に発見され、@3の手に渡りました。\nティンクトは抵抗しませんでした。むしろ、誰かが自分に何をすればいいか教えてくれることを望んでいました――たとえそれが嘘であっても、欺瞞であっても、一瞬の幻であっても、何もできずに立ち尽くすよりはましでした。\n少なくとも、それはファイントの未来に希望があることを示していました。"
  },
  AwakerStory_11211_Title = {
    Text = "物語・三"
  },
  AwakerStory_11211_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11214_Content = {
    Text = "ハンナ：ミサゴ大学がキミを助けられるって、どこで知ったの？世間の私たちに対する認識は「辺鄙な普通の大学」のままだし…………ラモンナが教えてくれたのかな？\nウインクル：ああ、違う違う。確かに彼女が私をここに連れてきたけど、ラモンナとはあまり親しくないの。私の種族、@1は時空を超えて精神を移動させる能力があるから、いろんなことを知っているのよ…………ミサゴについての知識もその一つ。\nハンナ：じゃあ、その「知識」で霧を抜けて、直接扉を開ける方法を知ったの？\nウインクル：霧の存在は知らなかった。あのときはただ歩き続けて、気づいたらここに着いてたんだ。霧といえば、あの道がどれだけ怖いか知ってる？街灯がないのはまだいいけど、霧が出ると太陽の光まで弱くなって、影がたくさんできて…………。\nハンナ：それがオフィスから出たくない理由？影への恐怖？\nウインクル：影？違う違う、あなたにはわからない？影だけじゃなくて、黒いものがたくさんある、あれが隠れているかもしれない場所がたくさん…………。\nハンナ：あれ？\nウインクル：しっ！声が大きい！あれを呼んでしまう…………あれには知能がないのに、どうして、どうしてここに来ても@2@3@1\nハンナ：ウインクル、大丈夫！？\nウインクル：@2@3@1…………\nハンナ：ウインクル？\nウインクル：もういい、出て行って！インタビューはやめる！あなたの影も、録音機もノートも全部黒い黒い黒い出て行って出て行って出て行って！\nハンナ：ウインクル——\n——ハンナ・ピーズリー「0810、ウインクルインタビュー（試み失敗1）」より抜粋"
  },
  AwakerStory_11214_Title = {
    Text = "物語・二"
  },
  AwakerStory_11214_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11215_Content = {
    Text = "《P-063号オペラハウス@2事件》で、焼け落ちたオペラハウスの裏手の隅から金属の箱を発見し、そのシルバーコアを回収しました。\nミサゴ大学に現存する機器では箱の材質を特定できず、ドール教授は@2文献を調べた後、その彫刻技術から箱が数百年前に爆発で消滅した荒れた星の文明から来た可能性を分析しました。\nそのシルバーコアは箱の中にあると静かで普通ですが、取り出すとブーンという音を発します。ドールはこの金属の箱が特定の周波数信号を遮断し、シルバーコアの共振を防ぐ遮蔽器であると疑っています。\n共振を引き起こすシルバーコアのモデルも判明しました。"
  },
  AwakerStory_11215_Title = {
    Text = "物語・一"
  },
  AwakerStory_11215_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11216_Content = {
    Text = "覚醒体番号：MA-C06\n危険度：A\n特殊収容措置：MA-C06は現在、7号覚醒体観察室に暗い照明とともに配置されている。\n\n@3に精神を奪われることを恐れて、MA-C06は眠ることを拒否し、部屋には椅子が一脚しかない。\n\n良好な行動と友好的な態度が続いているため、MA-C06は温室の使用が許可されている。\nまた、調査員が少なくとも1人付き添うことを条件に、キャンパスの一部地域を探索することも許可されている。\n\n——《覚醒体収容ファイル・MA-C06》"
  },
  AwakerStory_11216_Title = {
    Text = "物語・一"
  },
  AwakerStory_11216_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11217_Content = {
    Text = "ミサゴは死者の体から析出したシルバーコアを使って覚醒体を精錬した。\n彫刻家協会は生体からシルバーコアを育て、覚醒体を精錬した。\nこれはまったく異なる二つの理念であり、後者は非常に高い上限を持っているが、倫理に明らかに反しているため、禁じられない禁忌研究となっている。\nワックス像館事件の後、24はミサゴに連れ戻された。彼女は長い間キャンパスの観察室と研究室を転々としており、外出には専任の付き添いが必要だった。\n間違いなく、これは非常に制御不能な生きた覚醒体である。後続の観察の半年間で、24の体内には多くの人格が次々と分裂していった。\n彼女は突然見知らぬ友人や敵ができたり、奇妙なものをたくさん買ったり、知らないうちに中国語を話せるようになったりした。\n彼女の人生には常に「驚き」が欠かせない。\n「24は一連の孤立した点で構成される離散関数だ」とドールは評価し、「彼女の言うことをすべて信じてはいけない」と言った。"
  },
  AwakerStory_11217_Title = {
    Text = "物語・二"
  },
  AwakerStory_11217_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11218_Content = {
    Text = "「あたしは孤児じゃない」六歳のジェンキンは言った。「母さんは仕事に行ってるだけ、終わったら迎えに来るから」\n彼女は決して揺るがなかったし、揺るぐことを許さなかった。この信念は、毎晩黒い粘液にまみれた悪夢から目覚めるたびの護身の呪文であり、母親の顔を思い出そうとしても黒い影しか見えないときの唯一の慰めだった。\n彼女は歯を食いしばり、福祉院の門前で春夏秋冬を過ごした。福祉院が解散したその朝、彼女は誰にも見えない涙を拭い、鼠の友達と共に去った。\n「あたしは孤児」十歳のジェンキンは言った。「父さんも母さんもいない、いるのはブラウンだけ」\n彼女はそう自分に言い聞かせ、肩の鼠にもそう言った。事実その通りだった。突然近づいてくる子供には警戒する人もいるだろう――東区の浮浪児はロンディニウム中で有名だった――しかし足元を走り抜ける鼠にそこまで疑いを抱く者はいなかった。息の合った連携のおかげで、彼女はたまにお腹いっぱい食べることができ、下水道で暖炉やお菓子の夢を見ることができた。\nだが、寒い冬は誰にも容赦せず、彼女に病気と高熱をもたらし、死神が彼女のそばに立った。少女は瀕死の状態で横たわり、鼠だけが周りを急かすように駆け回り、鳴き声で誰かの――誰でもいいから――注意を引こうとした。\n若い女性が足を止め、少女を温かい胸に包んだ。\n「あたしは孤児じゃない」十三歳のジェンキンは言った。「メイソン姉ちゃんと、友達のブラウンがいるもん！」\n少女は鼠を抱きしめ、古びた家の前で明るい笑顔を浮かべた。"
  },
  AwakerStory_11218_Title = {
    Text = "物語・三"
  },
  AwakerStory_11218_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11219_Content = {
    Text = "ラモンナの体を占有している間、「ラモンナ」はキャンパスを歩くことはなかった。\nロータンの豪放さ、オジールの控えめな忠誠心、ウィリアムの冷静さ、ドールの厳格さ……彼女ほどこれらの瞬間を心に刻んだ者はいない。\nしかし彼女は常に心に留めている。これらの美しいものは、もはや彼女のものではない。\n今の彼女は、別の運命の人を守ることに全力を注ぐ必要がある……それはまた、危機に瀕した別の世界を守るため、無垢な自分を守るためでもある。"
  },
  AwakerStory_11219_Title = {
    Text = "物語・四"
  },
  AwakerStory_11219_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11220_Content = {
    Text = "ジェンキンのあまりに器用な手先のため、彼女はミサゴ大学の新しい《日報》の常連になるのではないかと心配されていました。——インタビュー対象としてではなく、いくつかの盗難事件の首謀者として。\n彼女は最終的に《ミサゴ日報》の常連になりましたが、それは習慣が変わらなかったからではありません。——十分なケーキの用意がある限り、ストリートサバイバルの達人でさえ、これまでの手段を放棄して鼠の相棒とめったにない引退生活を楽しむことを喜ぶでしょう。\n彼女が頻繁に記事に登場する理由はただ一つ。《日報》のすばらしい編集長があまりにも多くを与えてくれるからです。\nしっ——静かに、彼女がどこの片隅にいるかわからないですよ。聞いた情報を使ってハンナともっとお菓子やケーキを交換しようとしているかもしれません。"
  },
  AwakerStory_11220_Title = {
    Text = "物語・二"
  },
  AwakerStory_11220_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11221_Content = {
    Text = "科学と知識の新星が、普通の労働者家庭から昇り始めた。\nドールの幼少期の大半は、シリンダーの鼓動音やギアの作動音で満たされていた。\nしかし、機械への愛だけでは、少女を険しい科学の山に登らせるには足りなかった。\n彼女を求知の道に導いたのは、疫病だった。\n未知の狂気が都市を荒らし、病院は満員、遺体安置所は手に負えず、誰もが恐怖に駆られていた。\n「街中の墓地が足りないから、祖母を掘り出すか、母を焼くか、選ばなければならない」\nこうして、ドールは母親が炎の中に消えていくのを見守った。\n他の火葬された人々とは異なり、彼女が「母親」と呼んでいた砕けた骨と灰の中には、輝く銀質が流れていた。\n「わたしは知りたい、もう一度彼女に会えるのかどうか」\n「わたしは知りたい、その中に彼女の優しい魂があるのかどうか」\n「わたしは知りたい、その銀質が生命の本源であり、魂の本質なのかどうか」\n「わたしは知りたい、この世の万物に共通の起点があるのかどうか」\n答えを知るまでは、ドールは融蝕現象に屈するつもりはない。"
  },
  AwakerStory_11221_Title = {
    Text = "物語・四"
  },
  AwakerStory_11221_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11222_Content = {
    Text = "彼女の儚い姿は、羽ばたこうとするカモメを思わせる。海風に白いドレスがなびくたび、見る者はユートピアへ飛び立つ鳥の姿を思い描く。\nマストの横木に腰かける少女も、自分が飛び立つ姿を想像したことがあるのだろうか。"
  },
  AwakerStory_11222_Title = {
    Text = "基本資料"
  },
  AwakerStory_11222_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11223_Content = {
    Text = "ルビーのイヤリング、サファイアのネックレス、ガーネットと孔雀石で編まれた美しいヘアアクセサリー……それらはなんて眩しく、なんて美しく、なんて魅力的なのだろう。\n\nそれらがあるところには、人々が群がる。\n\nこれらのジュエリーは「装飾品」ではない、それらこそが世界の主役なのだ。\n\nターコイズのネックレスをつけた貴族の令嬢は、詩人に歌われ、エメラルドのイヤリングをつけた老婦人は、高貴な象徴とされる。\n\n彼女と同じように身分の低い少女たちも、手首の安っぽいブレスレットのおかげで、「真珠の少女」と呼ばれ、無数の人々の注目を集めている。\n\n枯れ枝や腐った骨でさえ、美しい宝石を飾れば、誰もが求める存在になれる。\n\nもし彼女もあのネックレスやイヤリング、ブレスレットやヘアアクセサリーを身につけることができれば、きっとみんなの注目の的になれるはず。"
  },
  AwakerStory_11223_Title = {
    Text = "物語・四"
  },
  AwakerStory_11223_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11224_Content = {
    Text = "流れる言葉は蕾から放たれる蜜の香り。\n\n王や家臣は揺らめく花芯に群がる蜂や蝶。\n\n彼らの欲望が育んだ茨は、いつの間にか彼らの権力ごと絡めとっていた。\n\nたとえ人格を非難されようと、手が血まみれになろうと、彼女は手に入れた権力を手放さない。\n\nそれこそが、薔薇を咲かせるための養分なのだから。"
  },
  AwakerStory_11224_Title = {
    Text = "基本資料"
  },
  AwakerStory_11224_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11225_Content = {
    Text = "彼女はその夫人の愛情と教えの下で、善良で優しい姿に育った。本物の貴族の令嬢のように。しかし、奴隷への無意識の助けが一度あっただけで、「両親」に無情に捨てられた。\nスパルタ人は彼女を受け入れず、同族も彼女を憎んだ。\n彼女は一瞬で皆の目に裏切り者となり、自分の存在の場所を失った。\n牢獄の中では誰もが強い悪意を放ち、まるで伝染する病のようで、彼らは互いに知らないはずなのに。\n暗闇の中での拷問は永遠のようで、彼女は神経質に誰かが近づくことを恐れ、毎日眠れず、時折昏睡する時だけが安らかに目を閉じることができた。しかし目を開けると再び終わりのない悪夢に落ちる。\n彼女は一体何を間違えたのか？すべてのことがどうしてこうなったのか？\n彼女の怨恨は茫然と行き場を失い、運命の論理を理解できない。\n彼女が罪を犯したからなのか？\nしかし彼女が罪を犯したなら、すべての人の罪は十倍になる。\nその憎しみは日々積もり怨憤となり、尽きることのない怒りが日夜彼女の血液を燃やし続け、ついにある日、彼女を閉じ込めていた牢獄を焼き尽くした。\n彼女を長年縛っていた鎖は今や一つ一つの叫ぶ首に巻きつき、長年の間に鎖は彼女の体と一体化していた。それは実に手に馴染み、彼女は血に染まった鎖を握り、一つ一つの汚れた魂を追い求める。\n赤、赤、温かい赤、生臭い赤。\n見てごらん、彼女は知っていた、誰の魂も純白ではないことを。"
  },
  AwakerStory_11225_Title = {
    Text = "物語・三"
  },
  AwakerStory_11225_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11226_Content = {
    Text = "彼女はすべてを知っている。\n彼女は時計塔が緊急時に鳴ることを知っており、エリダヌス座流星群が十年後に来ることを知っており、自分の中に異なる力が流れていることを知っている。\n彼女は何も知らない。\n彼女は食堂のカレーの秘伝スパイスを知らず、惑星が消滅した後の半径を計算する方法を知らず、自分の未来がどこに引っ張られるのかを知らない。\n彼女は身の回りのすべてを手放すことができず、直感が指し示す道に抗うこともできない。\n真実と真理への旅路で、ラモンナは堅固な人々と共に歩み、日常に戻る道を守ってもらう必要がある。"
  },
  AwakerStory_11226_Title = {
    Text = "物語・四"
  },
  AwakerStory_11226_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11227_Content = {
    Text = "目覚めなければよかった、深淵に沈んだ者は輝く太陽を見てはならなかった。\n\n彼女は麻痺した実験素材であり、この世界に埋葬された者であり、痛みの感覚や愛される渇望を持つべきではない。\n\n母の未練が彼女の人生の悲劇を生み、リリーは「世界の計らいに従うべきか」という迷いに陥っている。\n\nおそらくいつか、運命に抗う誰かから答えを得るだろう。"
  },
  AwakerStory_11227_Title = {
    Text = "物語・四"
  },
  AwakerStory_11227_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11227_UnlockDesc_1 = {
    Text = "メイン第4章「無音の中で」通常をクリア"
  },
  AwakerStory_11228_Content = {
    Text = "私は何か超自然的な事件に巻き込まれたようだ。発見したことをすべてここに記録する……\n\nエフロタスの最終調査を締めくくるはずだったその夜、目が覚めると仲間は誰もいなかった。そしてこの町は、一夜にして千年前へと遡っていた。\n\n崩れ果てていたはずの古代建築が再びそびえ立ち、町本来の姿を取り戻していた。白骨と化した住民たちまで含めて。\n\n興奮、驚愕、恐怖が同時に私の脳を鷲掴みにした。無数の骸骨を見てきた私ですら、この光景の前では震えが止まらない。同じ目に遭えば、誰でも私より恐れおののくだろう。\n\nこの町の住民はすべて、同一人物によって残虐に虐殺されたようだ。無数の白骨が街路に横たわり、家の中に倒れていた。町の門はなぜか固く閉ざされ、逃げようとして殺された者たちの骸骨が門のそばに白骨の小山をなしていた。\n\n例外は一人もいない。男、女、老人、子供。\n無数の命が巨大な鈍器で体ごと、砕かれていた。乾いた骸骨を前に、私はふと幻を見た。血が町全体に溢れている。\n\nここで何が起きたのか？\n……\n\n手がかりを求めて茫然と歩き回り、ついに町の監獄へ踏み込んだ。\n\nここは特に凄惨だった。何者かは激しい怒りで監獄を破壊し尽くし、壁には血で書かれたねじれた文字が残っていた。誰かが死の間際に書き記した訴えのようだ。目を凝らすと——悪霊、と読めた。\n\n悪霊？これは虐殺した犯人を指すのか、それとも本当に何か超自然的なものを目撃したのか？\n\n一人の力で町全体を屠るなど到底信じがたい。これほど多くの命を残忍に刈り取れるとすれば、悪霊以外に考えられない。\n\n監獄を出ると、町はどこか微妙に変わっていた。鼻にかすかな血の匂いが漂い続け、消えない。\n\n出口を探していたそのとき、突然、鎖の音が町中に響いた。何か重いものを引きずるような音だ。\n\n悪霊だ！\n悪霊に見つかった！\n必死に走ったが、どこへ逃げても、あの恐ろしい鎖を引きずる音がついてくる。\n\nもう走れない。ある民家のテーブルの下に身を潜め、扉に鍵をかけた。それでも鎖の音は追いかけてくる。近づいてくる、どんどん近くなる……\n\n夢であってほしい。目が覚めればすべて消えてほしい。……音が消えた。悪霊は去ったのか？\n……\n\n（研究者注：ここで通常の筆跡は途絶え、最後にねじれた三文字のみが残る。鑑定の結果、おそらくこう読める——）\n\n門が開いた\n\n——エフロタス考古団、故考古学者の日記より抜粋"
  },
  AwakerStory_11228_Title = {
    Text = "物語・一"
  },
  AwakerStory_11228_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11229_Content = {
    Text = "剣闘士たちが訓練場を完全に焼き払い、彼女の両親の首を高い壁に掛けたときでさえ、アグリッパは信じられなかった――これらの卑しい、従順な奴隷がどうしてそんな勇気を持てるのか？\nローマでは、人は2種類に分けられる。他人を奴隷にする者と、他人に奴隷にされる者。\nアグリッパは幸運だった。彼女はカプア最大の剣闘士訓練場のオーナーの娘だった。彼女は横行し、傍若無人で、彼女ができないこと、しないことは何もなかった。\nしかし今、彼女は怯えたウサギのように地下室の隅に縮こまり、外の狂騒は彼女にとって地獄のように見えた。\n奴隷反乱。なんと馴染みのない言葉。アグリッパはまだ15歳で、この世界には彼女が理解できないことがたくさんある。\n彼女は影の中で赤く光る目を見た。それはユウハシュ、訓練場の最大の金のなる木で、あまりにも危険なため長年地下に閉じ込められていた。\n二人は元々仲が悪く、彼らがその夜に何を話したのか誰も知らない。炎が舐める血なまぐさい夜が終わった後、アグリッパは暗い地下で死んでいるのが発見され、彼女のそばには誰もいなかった。彼女は奴隷に殺されたのではない――誰かが彼女の血を吸い尽くし、一滴も残さなかった。\nもちろん、彼女の首も最後には切り落とされ、彼女の両親の隣に掛けられ、ローマの方向に向かって風に揺れていた。"
  },
  AwakerStory_11229_Title = {
    Text = "物語・三"
  },
  AwakerStory_11229_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11230_Content = {
    Text = "ハンナ：オートマタだった頃と今の自分に、違いはある？\nエリカ：あの頃の私は「感情」を持っていました。\nハンナ：具体的にはどんな感情を？よければ教えてくれない？\nエリカ：申し訳ありませんが、質問の意図がわかりません。\nハンナ：ええと、もしこの質問がプライベートなものであれば、答えなくても良いよ。\nエリカ：「答えたくない」という感情を感知できません。申し訳ありません。\nハンナ：じゃあ、当時の感情を教えてくれる？\nエリカ：血肉の私は爆発を生き延びた：嬉しい、安堵。\n自分の精神がオートマタに移されていることを知った：緊張、興奮。\n意識が徐々に制御できなくなり、強い破壊欲求が生まれた：緊張、恐怖、保護。\nハンナ：保護？\nエリカ：申し訳ありません、詳細情報は失われています。\nハンナ：なら、別の質問をするよ！これも本紙の読者が知りたがっていることなんだけど、どうして今は感情がないの？何があったの？\nエリカ：不明な理由により、精神リンクを通じて理性を回復することができず、大学は必要な措置を講じ、シルバーコア補助機器によってすべての感情を抑制し、攻撃性と危険性を低下させ、知能を保ち、実用性を維持しました。\n——《ミサゴ日報》、《覚醒体教職員インタビュー：チクタクマン》より抜粋"
  },
  AwakerStory_11230_Title = {
    Text = "物語・三"
  },
  AwakerStory_11230_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11231_Content = {
    Text = "コーンウォール州南部海岸での調査中、地図に存在しない廃村を発見しました。調査の結果、これは融蝕現象の爆発により「存在を抹消された」村であることが確認されました。\n村では、異常な海洋生物のサンプルを大量に収集しました。肉食性を示すシャコガイ、耐熱能力を持つ氷海天使、その中で最も常識に反するのは至る所にいる「両生クラゲ」です。\nクラゲの巣になった旧家屋で、流体状のシルバーコアを回収しました。重量は約11.85ドラムです。このシルバーコアを現場から持ち出す際、調査隊員は異化クラゲの襲撃を受けましたが、幸運にもこれらの異常な両生クラゲの腺体はすべて腐敗しており、神経毒性はありませんでした。\n——《A.F.308年第三次生物系フィールド調査記録》"
  },
  AwakerStory_11231_Title = {
    Text = "物語・一"
  },
  AwakerStory_11231_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11232_Content = {
    Text = "光が怖い、視線が怖い、愛が怖い、抱擁が怖い。\n光を求め、注視を求め、愛を求め、抱擁を求める。\nもし自分が他人に害を与えなければいいのに、もし自分が他人に迷惑をかけなければいいのに、もし自分がテューグのように賢い子だったら、もし自分がジェンキンのように勇敢な子だったら、もし自分が……\nそうすれば、灼熱の太陽に焼かれることもなく、他人に嫌われることもないだろうか？\n非現実的な不安を抱えたぬいぐるみは、影の中から、陽光の境界に向かって、白くてほとんど透明な小さな手を恐る恐る伸ばした。"
  },
  AwakerStory_11232_Title = {
    Text = "物語・四"
  },
  AwakerStory_11232_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11233_Content = {
    Text = "彼女は緑炎に包まれて踊り、幽かな火が踊り子の幼くも敬虔な顔を照らし出す。シャネの旋回する舞に合わせ、翠の炎はすべての悪党の魂を燃やし、舞台の穢れを焼き尽くした。"
  },
  AwakerStory_11233_Title = {
    Text = "基本資料"
  },
  AwakerStory_11233_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11234_Content = {
    Text = "三月\n大西洲巡回水族館へようこそ！今回の解説員はオレッタです、クラゲのワゴンに乗る際は足元に気をつけてくださいね！\n水槽には熱帯海域からの珍しいクラゲが展示されています、じゃんじゃん！ご覧ください——\n四月\nこ、これはどういうこと…………みんなはどこに行ったの…………館長！館長！クラゲたち、オレッタのクラゲたちが消えた！\n水族館にはクラゲの展示品がなかった？でも確かに覚えている…………\n五月\n展示品が少なすぎて、お客さんが来ないから経営できない…………うぅ……みんなさようなら…………\nもし、もしまた巡回展示ができるなら、必ずオレッタを探しに来てくださいね！\n六月\nオレッタは疲れた……病気かな…………\nあぁ…………クラゲたちだ！ごめんね、オレッタはみんなに珪藻を撒けない。\nオレッタが元気になったら、また一緒に泳ぎましょう…………"
  },
  AwakerStory_11234_Title = {
    Text = "物語・三"
  },
  AwakerStory_11234_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11235_Content = {
    Text = "極楽鳥に従って31日目、ソナニール号は霧の海域に入った。\nシレストはマストの高いところに座り、下の人々を見渡していた。そこからは、リュートの甘い旋律と、航海の無事を祈る歌声が聞こえてくる。\n\n彼女はこの航海の目的地を知らず、この旅がどれほどの富と名誉をもたらすかも知らない。祈る者が敬虔であるかどうかも、海で密かに広まっている、彼女が霊験あらたかでないという悪評も、彼女にとってはどうでもよかった。船の加護を求められた以上、彼女は黙って使命を果たす。\n\n歌声が止み、霧が晴れると、船員たちの前に怒涛の嵐の海が現れた。稲妻が空を引き裂き、黒い汚れた雨が降り注ぎ、激流が脆い船体を巻き上げ、恐ろしい深淵へと投げ込んだ。\n\n「神は私たちを見捨てた！」絶望した親族たちは叫び、怒鳴り、彼女を暗闇の牢獄に閉じ込めた。\n失職した守護者がなぜ使命を果たせなかったのか、今では誰も深く追及しない。シレストには最後に小さな疑問が残った。\n\n…………なぜあの船は沈んだのだろう？\n\nマストに彼女を縛り付けていた鎖が水しぶきを上げ、彼女は深海へと沈んでいく…………\n翼を折られた白鳥のように。"
  },
  AwakerStory_11235_Title = {
    Text = "物語・三"
  },
  AwakerStory_11235_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11236_Content = {
    Text = "彼は名実ともに巨人だった。強靭な肉体は、畏怖を感じさせる力を示している。誰にも持ちあげられない巨大な刃を使い、戦争と血の祭りの養分で、その表面は油を塗った毛皮のように光っている。その牙は、数え切れないほどの敵や同族の首を切り落とし、彼自身の首も切り落とした。"
  },
  AwakerStory_11236_Title = {
    Text = "基本資料"
  },
  AwakerStory_11236_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11237_Content = {
    Text = "ロンディニウム聖堂区異常事件報告（機密）\n\nA.F. 315年@2月@3日、ロンディニウム聖堂区異常事件において、聖堂区司教サルバドルは、ミサゴの守秘者とその場にいたロンディニウム市民を救うため、「祝福」の力を使用し、結果、彼が覚醒体であると露見した。\n事件の過程で、リンク者の精神力が不足したため、リンク者への負担を避けるべく、サルバドル司教は自己消耗によって「祝福」を支え続けた。最終的に、守秘者とオジール覚醒体が異常現象の中核――儀式の鏡――を打ち砕いた。その後、守秘者がサルバドル司教のリンクを引き継いだことで、「祝福」によって現場の全員が治癒され、人的被害は回避された。\n調査によれば、サルバドル司教の元リンク者は前聖堂区司教であり、現在のロンディニウム大司教@4である。\nA.F.300年、大司教は聖灰との接触によりサルバドルを偶然覚醒させた。その後の5年間、サルバドルは助任司祭として聖堂区で活動し、■■■■■の昇進後、その後任として聖堂区司教となった。\n事件後、守秘者はサルバドル司教が覚醒体である事を秘匿することに同意した。そのため、この情報はミステイア協定審査会には報告されていない。ミサゴ大学の中核メンバーを除き、現在彼が覚醒体だと知る者はいない。"
  },
  AwakerStory_11237_Title = {
    Text = "物語・一"
  },
  AwakerStory_11237_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11238_Content = {
    Text = "その年の11月の雪の日、24は病気になった。\n\n一週間の激務の後、彼女はひどい熱を出して、家で何日も寝込んでいた。\n\nぼんやりとした意識の中で、小さな鼠が耳元で泣いているのが聞こえた。\nどれくらい経ったかわからないが、誰かが彼女のそばに立った。\n彼女はその目を知っていた——下水道のあの子供だ。\n\n泥だらけのその子は、汚れた薬を24に差し出した。\n「これを、飲んで」\n子供はぎこちなく言ったが、その声はとても美しかった——その子は女の子だったのだ。\n\n24は少女の肘と顔の傷を見つめ、薬がどこから来たのかは聞かなかった。\n彼女は少女の手をしっかりと握った。\n少女は不安そうに鼻を鳴らし、子供をあやすようにクールに言った。\n「あたし、どこにも行かないよ。……あんたがよくなるまで」\n\nよくなっても行かないで。\n24は心の中で答えた。\n\n初冬のロンディニウムは一週間雪が降り続けた。\n雪が止んだ日、24はとても嬉しかった。\n熱が下がっただけでなく、妹もできたのだから。"
  },
  AwakerStory_11238_Title = {
    Text = "物語・四"
  },
  AwakerStory_11238_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11238_UnlockDesc_1 = {
    Text = "メインストーリー第2章「蝋人形の名において」通常をクリア"
  },
  AwakerStory_11239_Content = {
    Text = "「罪を犯した者よ、ここは欲望の淵、地獄の底だ。黒犬がここで吠え、悪臭がここで漂い、喪鐘がここで鳴り響く。お前たちは放縦な欲望と残忍な行為のためにここに集まり、待ち受けるのは苦難と死だ」\nパンディアはかつて新門監獄に勤めていた。そこはロンディニウムで最も陰鬱で最も薄暗く最も日の光が届かない汚れた場所だった。かつて血にまみれた重罪犯が手錠と枷をはめられ、尊厳を奪われ、迷宮のような牢房区域で彼女にひざまずき、彼女のブーツに口づけし、謙虚に彼女の奴隷と称した。\n新たな絞首刑が執行されるたびに、彼女は新しい死刑囚を呼び出し、彼らに自分の末路を見せた。執行される者が麻縄の中でもがきながら死にゆくとき、彼女は高い場所に座り、恐怖と絶望に震える凶悪犯を観賞するのが好きだった。\nしかし、「地獄の猫」は、パンディアが何度も新門監獄の鉄門のそばに来て、つま先立ちでロンディニウムの城外を見渡し、遠くからの訪問者を待っているかのようにしているのを観察したことがある。\n「実際、あたしはこの暗く湿った悲惨な牢獄から永遠に離れられない囚人の一人に過ぎないもの」"
  },
  AwakerStory_11239_Title = {
    Text = "物語・三"
  },
  AwakerStory_11239_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11240_Content = {
    Text = "A.F.3@1年7月3日、ネイサニエル・フォーブス・グリーン財団の招待を受け、ミサゴ大学は「幽霊船」ソナニール号の調査に参加した。\n十年前に沈没が発表されたこの三本マストの帆船に乗り込んだ調査員フィンゴル・ヨハンソンは、すぐに通信信号を失った。\nA.F.3@1年7月10日、大学が再び彼と連絡を取ったとき、ヨハンソン調査員は300海里離れたレオ高地の北岸にいた。ヨハンソン調査員によると、船に乗り込んですぐに時間と空間の概念を失い、ソナニール号で起こったことはどうしても思い出せないという。\n今日まで、ヨハンソン調査員は「永遠の楽園」という言葉をかろうじて覚えているだけである。幽霊船自体が無害であることから、ミサゴ大学は本日（A.F.3@1年12月24日）調査を中止することを決定した。\n——《資料：ソナニール号の難破調査》"
  },
  AwakerStory_11240_Title = {
    Text = "物語・一"
  },
  AwakerStory_11240_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11241_Content = {
    Text = "彼女にとって、路上生活は難しいことではなかった。\n腹が減れば仕事を探し、なければ自分の手で稼ぐ。\nブラウンとの息はぴったりで、誰の助けも借りず、食べていくことができた。\n「あたしたちは誰も必要としない」彼女は相棒の鼠と誓った。「あたしたちにはお互いがいればいい」\nしかし雪の降る夜になると、彼女はいつも、薄暗い明かりが灯る窓の中を見てしまう。\n貧しい夕食を囲み、互いに抱き合い、祝福し合う人々を。\n彼女は確かに、屋根も高級なベッドも必要とせず、信頼できる仲間もいる。\nそれでも彼女は、家を持つことがどんな感じなのか、ずっと気になっていた。\nその答えは、メイソンに引き取られてから、ようやくわかった。"
  },
  AwakerStory_11241_Title = {
    Text = "物語・四"
  },
  AwakerStory_11241_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11242_Content = {
    Text = "「ラモンナ」は現れることに非常に慎重だった。彼女が言ったように、守秘者が呼ぶときだけ、彼女はラモンナの体を借りて現れる。\n彼女はいつも急いで去り、戦闘以外では私たちの世界とあまり関わりたくないようだった。\n彼女を悩ませる悪夢を恐れているのか？それとも、彼女が失ったものに執着することを恐れているのか……私たちにはわからない。"
  },
  AwakerStory_11242_Title = {
    Text = "物語・二"
  },
  AwakerStory_11242_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11243_Content = {
    Text = "A.F.1@2年@1月@1日\n10:31、警察は@1@1邸で血痕が発見されたとの通報を受けた。\n警察署のベルフォード刑事は直ちに現場に赴き、調査を開始。\n血痕の中から成分不明の青緑色の粘液を発見した。\n\n13:44、ベルフォード刑事が報告書を提出し、ミスティア協定審査会が事件を引き継いだ。\n\n14:25、審査会第七対応班が邸に到着、関係者を拘束し現場を封鎖。\n現場の状況から、隊長は邸内に少なくとも5人の被害者が存在し、複数の融蝕が発生していると推測した。\n\n18:00、ミサゴ大学の調査員が現場に到着、融蝕現象を確認し、覚醒体を連れて邸内の清掃と調査を行った。\n\n23:11、邸の清掃が完了。\n調査員は邸の地下室と書斎の密室で大量のオカルト文書と儀式用具を発見し、不完全な覚醒体を発見した。\n覚醒体は「メイドのカレン」と名乗り、@3公爵の首席侍女であると語った。\n発見時、覚醒体はメイド服を着ており、さまざまなスタイルのアクセサリーを身につけ、地下室を一生懸命掃除していた。\n人間の姿をしており、青緑色の肌を持ち、手足の末端は半透明の粘液状で、不完全または誤った召喚の産物であると推測される。\n彼女の体から分泌された粘液は、残骸に付着していた物質と質感と色が完全に一致した。\n調査員が尋問したところ、メイドのカレンは@1の事実を認め、すべては主人の注目を集めるためだと述べた。\n@3公爵が逮捕されることを知ると「では私の新しいご主人様はどこ？」と呟き、シルバーコアを残してジェル状に溶け去った。\n\n01:37、審査会第七対応班の隊長が関係者を取り調べ、《協定》に基づき@1@1邸の主人@3公爵を拘留。\n\n03:09、調査員がミサゴ大学に戻り、K-033号シルバーコアを登録。\n——《@1@1邸事件記録》"
  },
  AwakerStory_11243_Title = {
    Text = "物語・一"
  },
  AwakerStory_11243_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11244_Content = {
    Text = "A. F. 3@2年、アグロ共和国の沿岸都市で融蝕現象が発生。この融蝕現象は港を中心に螺旋状に拡散し、数百メートルの範囲に影響を及ぼし、@1人が死亡した。\n調査によると、融蝕現象は港の漁船で最初に発生した。この船はA. F. 3@2年@1月@1@1日に出航し、銀色の螺旋模様を持つタラに似た生物を捕獲した。\nこの生物の体は柔らかく、鋭利なもので切断されると全体が破裂し、貝殻や他の残骸が混ざった流体物質が流れ出た。漁船が港に到着した後、魚の獲物にはすでに貝殻のような増殖が見られたが、注意を引くことはなく、一人の漁師が自分を貝殻と見なして体をねじろうとして重傷を負い入院したことで、事件が報告された。\nその後、ミサゴの関係者が@4缶詰工場で融蝕の根源を発見し、それを除去してO-36シルバーコアを取得した。\n——『覚醒学部シルバーコア取得報告：O-36』"
  },
  AwakerStory_11244_Title = {
    Text = "物語・一"
  },
  AwakerStory_11244_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11245_Content = {
    Text = "ジェンキンは心理相談室のドアの隙間に耳を当てて盗み聞きしていた。\nシルヴィアの声は穏やかで親しみやすく、アイギスの声は蚊の鳴き声のように断続的で聞き取りにくい。\n「アイギス、断ることを学びましょう」\n「でも私…………迷惑を…………恩返ししたくて…………」\n「アイギスは誰にも迷惑をかけていないわ。ほら、守秘者は学校で自由に活動することを許してくれて、何の拘束もしていない。それは信頼の証でしょう？」\n「私と約束して、他の人の無理な要求を気軽に引き受けないで。特にカラブの代わりに禁閉や掃除をするのは、守秘者に迷惑をかけることになるのよ？」\n「ジェンキン、どうして入ってきたの？」\n「ジェ、ジェンキン！カラブには…………私が自分で引き受けたの！衝、衝動的にならないで！」"
  },
  AwakerStory_11245_Title = {
    Text = "物語・二"
  },
  AwakerStory_11245_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11245_UnlockDesc_1 = {
    Text = "メインストーリー通常第1章「東区の秘め事」クリア"
  },
  AwakerStory_11246_Content = {
    Text = "ウインクルにはかつて、彼女自身の名前があった。\nその名前は両親の愛情に満ち、\n友人に何度も書かれ、思い出となり、\n誕生日と一緒にカレンダーに記されていた。\n\nウインクルにはかつて、彼女自身の顔があった。\nその顔は両親の見守る中で成長し、\n友人と共に喜び、悲しみ、\n思い出と共に写真に残されていた。\n\nウインクルにはかつて、彼女自身の家があった。\nカダスとは遠く離れ、似ても似つかない場所。\nそれは両親と共に消え去った。\n黒い@2に飲み込まれ、跡形もなく消え去った。\n\nウインクルには深い恐怖がある。\nそれは漆黒で、恐ろしく、すべてを飲み込み、理不尽だ。\nすべてを腐蝕し、侵蝕し、消し去る。\n一度触れれば、存在そのものが灰になる。\n\nウインクルには、かつての名前しか残っていない。\n人間の体では発音することも、真似ることすらできない。\n彼女は極度に疲れたとき、目を閉じる。\n懐かしい呼び声が聞こえる夢を、祈りながら。"
  },
  AwakerStory_11246_Title = {
    Text = "物語・三"
  },
  AwakerStory_11246_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11247_Content = {
    Text = "彼女が生まれたのは、人類史の記録よりも前の、もはや確かめようのない旧き文明の時代である。\nそこでは、星々より来た民が輝かしい王国と、不朽の神を祀る神殿を築いていた。\n彼女はその信仰の只中で育ち、幼い頃から敬虔に神を敬い、いつか神の使徒となることを志していた。\n\nだが、神の啓示を、それほど容易に授かるはずもない。\n彼女は奇跡と霊的な幻影を切望していたが、一度たりともそれを目にすることはなかった。\n\nやがてトゥルーが王位に就き、勤勉な彼女もついに大祭司の位へと昇った。\nそれは彼女の生涯で忘れられない瞬間であった。\n強烈な恍惚と喜びが彼女の魂を満たし、精神を震わせた。\n\nそのとき、彼女はついに奇跡を見たのだ。\n彼女はついに真意を悟った。\nこの幼き王こそが、自分の求めてきた存在、人の世に顕現した不滅の化身なのだと。\n\nそれから数年後、文明を滅ぼす大洪水が降りかかる。\n彼女はトゥルーから不滅にまつわる最後の予言を聞きとげると、最後の瞬間まで神殿で祈り続けた。\n\nその後、幾度も海は陸となり、陸は海へと変わり、新たな人類がまた大地で繁栄を始めた。\nだが、旧き文明の出来事を知る者は、二度と現れなかった。\n\nここから、ミリアムの試練が始まったのである。"
  },
  AwakerStory_11247_Title = {
    Text = "物語・三"
  },
  AwakerStory_11247_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11248_Content = {
    Text = "生きることは本能であり、捨てられない重荷でもある。記憶すら残せない死の前で、彼女だけが彼らの存在を証明している——彼女の両親、彼女の友人、彼女の故郷のすべてを。だから彼女は逃げた。まだ黒に染まっていない世界へ、海に覆われたこの星へ、死んだ人間の少女の体で新しい人生を得た。しかし黒い死神は、決して焦らない。人間の目には融蝕は見えないが、彼女は意識の端にある寒さが何を意味するのか、脳裏の暗闇が何を表しているのかを知っていた——人間に融蝕と呼ばれる死が追いかけてきて、彼女の知らないうちに、彼女の精神と体を一つに縛り付けた。彼女は何度も逃げようとし、何度も失敗し、ついには疲れ果て、精神も限界まで引き裂かれ、唯一の救いを与えてくれるかもしれない場所へと歩いていった。どうしても、彼女は生き延びたかった。"
  },
  AwakerStory_11248_Title = {
    Text = "物語・四"
  },
  AwakerStory_11248_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11249_Content = {
    Text = "ライカーは警察の友人から「幸運の探偵」と呼ばれていた。\n\nその名のとおり、彼はとびきり運のいい男だ。\n賭ければ元手の10倍は勝ち取り、勘に頼れば、必ず正解を選び当てる。\n\n別に探偵になるつもりだったわけではない。\nただ偶然の重なりで、いくつもの怪事件を解決してしまい、気がつけば人々に担ぎ上げられ、探偵としての道を歩むことになった。\n\n彼は推理ではなく、運で事件を解決する。\n現場を一周すれば犯人にぶつかり、道を歩けば重要な証拠を拾う。\nそんな幸運に恵まれ、彼は順風満帆な25年を過ごしてきた。\n\n過去を悔やむこともなく。\n未来を憂うこともなく。"
  },
  AwakerStory_11249_Title = {
    Text = "基本資料"
  },
  AwakerStory_11249_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11251_Content = {
    Text = "A.F.3@2年4月1日、シルバーコア保管管理室、ミサゴ大学覚醒学部、ロンディニウム\nG411号シルバーコアとG410号シルバーコアは共に、デクスター卿が「水仙夫人」から購入した。個体の長さは1.85センチ、最も広い部分は0.4センチで、全体の形状は斜方六面体に近い。どの角度や方位から観測しても、G411は観測者の視覚中心を中心に、周囲に明るい黄色の菱形の波紋を広げる。長時間注視すると観測者の精神が散漫になり、感情のフィードバックが弱まり、さらには木偶の症候群（可能な症状には、完全な感情の欠如、欲望の欠如、食欲の欠如による栄養失調や死亡など）を引き起こす可能性があるため、心理的および感情的な介入が必要である。\nその負の効果は大部分のシルバーコアと比較して穏やかであるが、それでも密封保存を推奨し、取り出した後は直視を避け、G411の影響による感情障害の可能性を減らすことが望ましい。\n\n——《ミサゴ大学シルバーコア保管記録》より抜粋"
  },
  AwakerStory_11251_Title = {
    Text = "物語・一"
  },
  AwakerStory_11251_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11252_Content = {
    Text = "彼女が覚えているのは、血の色だけだ。\n\nかつての穏やかで温かな記憶は、まるで偽りの夢のようにぼやけてひび割れ、鋭い破片となって一片一片、彼女の体に突き刺さる。\n\nかつての優しい抱擁も、気にかけてくれた顔も、もはや思い出せない。\n心に残るのは、永遠の憎しみと問いかけだけだ。\n\n痛み、屈辱、裏切り……\nこの苦しみに、意味などあるのか？\n\n彼女は日々問い続けた。\n自由を得るその日まで。\n\n答えは返ってこなかった。\n\nならば自ら答えを探すまでだ。叫び喚く者たちの胸を裂き、汚れた心臓に直接問いただせばいい。"
  },
  AwakerStory_11252_Title = {
    Text = "基本資料"
  },
  AwakerStory_11252_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11253_Content = {
    Text = "歴史の流れに埋もれるはずだった小さな魂は、母の願いと@1@2@1の魔法陣に充満した霊気により、アイズルワースの氷下に眠る巨大生物と結びつき、少女の怪物「リリー」として復活した。\n不完全な召喚のため、初期のリリーは意識がなく、命令に従う戦闘人形に過ぎなかった。\n彫刻家協会のメンバー、フランシス・オズウッドはリリーを素体として、@2年にわたる違法実験を行った。フランシスの日記から、当時のリリーの状態は非常に不安定で、しばしば制御不能になり小規模な破壊を引き起こし、フランシスは頻繁に住居を変えざるを得なかったことがわかる。\n霊知の薬剤の摂取とシルバーコアの植え付けにより、リリーは記録されていない、とある日に感覚と一部の記憶を取り戻した。その後、フランシスは倒産寸前のライ療養所を引き継ぎ、実験場に改造した。\nL-776号ライの街「地獄の番犬」事件で、母フランシス・オズウッドは自身が作り出した異常次元に囚われ、連絡が途絶えた。"
  },
  AwakerStory_11253_Title = {
    Text = "物語・五"
  },
  AwakerStory_11253_UnlockDesc = {
    Text = "同調率レベル10で解放"
  },
  AwakerStory_11253_UnlockDesc_1 = {
    Text = "メイン第4章「無音の中で」通常をクリア"
  },
  AwakerStory_11254_Content = {
    Text = "人類が今世紀に極地に上陸するという噂が広まり、ミサゴ大学とミスティア協定審査会は協力し、合同調査隊を結成した。\n合同調査隊はA. F. 3@1年12月にアイズルワース氷原に入り、世俗の探検隊が上陸する前に神秘学的な産物を回収することを目的とした。\n…………\nA. F. 3@1年12月10日、ヨハンソン調査員が氷穴に落ち、氷原の下に空洞があることを発見した。標高が低すぎて、融けた氷が三日以内に空洞を埋めるだろう。気温がさらに上昇する前に探索を完了する必要がある。\nA. F. 3@1年12月12日、世界には長期間空洞を祭坑として使用していた教団が存在すると信じる理由がある。空洞の底で、無数の人型生物の骨格を発見した。そう、人型生物であり、その頭蓋骨には一部のひれ状軟骨が接続されている。\n…………\nA. F. 3@1年12月13日、なんてことだ、なんてことだ！骨の山の最上部で、調査員は最近死亡した人間の遺体を発見した！！！\n教団は極地をまだ去っていない可能性がある。審査会の愚かな「主張」に基づき、今回の調査には覚醒体調査員の同行が許可されていない。早く離れなければ！\n――「ウィルド海航路封鎖の動議書・その一」"
  },
  AwakerStory_11254_Title = {
    Text = "物語・一"
  },
  AwakerStory_11254_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11255_Content = {
    Text = "ワンダは聡明で、裕福で、美しく、彼女自身の言葉通り、生きる目的は快楽を追い求めるためだった。\n\n彼女は男たちを奴隷にし、月光のように冷たい足で、奴隷の背中を踏みにじる。\n\n冠を戴いたヴィーナス——邪悪と夢幻の化身であり、この暗く陰鬱な影の中で、ただ彼女のすらりとした姿だけが輝いている。"
  },
  AwakerStory_11255_Title = {
    Text = "基本資料"
  },
  AwakerStory_11255_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11256_Content = {
    Text = "リリー・オズウッドの記録を調べようとした際、エリカは81件の誤警報を発した。世界に忘れられた者として、リリーの出生記録や診療記録は黒い泥と化している。\nしかし、特殊な装置を使って彼女のシルバーコアの形状を観察できる。細く巻きつき、数本の絡み合った髪の毛のよう――正確には、子供の産毛のようだ。\n特に注意すべきは、リリーがリンクする者に特別な愛着を示すことだ。「仲間」や「主人」と称するよりも「母親」として接することで、彼女との関係をより早く縮めることができるかもしれない。"
  },
  AwakerStory_11256_Title = {
    Text = "物語・一"
  },
  AwakerStory_11256_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11257_Content = {
    Text = "ラモンナは十歳から大学の訓練場の常連となった。人間の身で黒衣の剣士の指導を受ける彼女は、多くの調査員の憧れの的となった。\n正式に予科課程を受け始めると、彼女は記憶力、満点の試験、優雅で致命的な剣技を武器に、ミサゴでの地位を高めていった。自律と優秀さが彼女の代名詞となった。\nしかし、多くの人が不思議に思ったのは、これほど優秀でありながら、ラモンナが独立して任務を遂行する資格を得られなかったことだ。彼女は早期入学したにもかかわらず、五年間も予科課程を受け続け、次々と調査員が神秘学の世界に飛び込むのを見送った。\n彼女は一体何を待っているのか？どんな使命を与えられているのか？\nこの疑問は、新しい守秘者が入学した後に解決された。"
  },
  AwakerStory_11257_Title = {
    Text = "物語・二"
  },
  AwakerStory_11257_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11258_Content = {
    Text = "制服はスチームでアイロンをかけ、布団は手洗いし、夏は暖炉をきれいにし、冬は常に火を絶やさないようにする。床はピカピカに磨き、書棚は埃一つないようにし、紅茶はいつでも飲めるように適温に保つ。\n高貴で特別で唯一無二の新しい主人、彼女に再び命を与えてくれた守秘者のためなら、何でもできる。彼女は世界一のメイドだから、どんな仕事も完璧にこなし、細部までこだわる。\n主人に褒められると、とても嬉しいけど、まだ足りない。\nどうすればもっと主人の注目を集められるのか？どうすればもっと目立てるのか？\n「きっとピアスとネックレスとブレスレットと指輪とヘッドドレスが足りないんだ！」彼女はほうきを地面に突き刺し、独り言を言った。「キラキラの宝石を身につければ、カレンはもっと可愛くなって、みんなもっとカレンを見てくれるはず！」"
  },
  AwakerStory_11258_Title = {
    Text = "物語・二"
  },
  AwakerStory_11258_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11259_Content = {
    Text = "A.F.3@2年初頭、シディという都市で再開発中に、火災で失われた庭園で異変が発見された。\n灰は蔦のように焼けた温室の壁面を這い上がり、その蔦に咲く灰色の薔薇は金属のような光沢を帯びていた。\n\n蔦に導かれるまま、ミサゴ大学の調査員はそこにあったシルバーコアを拾った。\nその銀色の粉に触れた瞬間、彼女の指先は黒く焦げたが、痛みはなく、頬にはなぜか涙が伝った。\n\n理由のない悲しみは、瞬く間に灰の中に消えていった。"
  },
  AwakerStory_11259_Title = {
    Text = "物語・一"
  },
  AwakerStory_11259_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11260_Content = {
    Text = "登山家がアイズルワースの頂上に到達したとき。\n競技者が世界一のトロフィーを掲げたとき。\n信者が夢の中で啓示を聞いたとき。\n\nあまりにも簡単に勝利を得ると、それに伴う満足感は平凡な惰性となる。\n見渡す限り、敵も楽しみもない。\n\n表向き、ライカーは情熱的なゲームを望み、オールインした後に喉から飛び出す心臓を望み、アドレナリンが迸る瞬間を望んでいる。\n\n「そんな建前はいいでしょう。あなたを本当に理解しているのは私だけ。あなたが望んでいるのは、ただの敗北でしょう。ならば……\n\n私がこの上なく甘美な敗北を与えてあげましょう」"
  },
  AwakerStory_11260_Title = {
    Text = "物語・四"
  },
  AwakerStory_11260_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11261_Content = {
    Text = "ヘロットは鋭く冷たい刃だ。\n彼女と一緒に任務を遂行した覚醒体たちは皆、ヘロットは非常に使いやすい武器だと言う。彼女は十分に強く、いつも任務を完了し、殺害命令を受ければ、どんなに強力な敵であろうと必ず突入し、敵の首を取る。\nしかしそれだけだ。\n彼女は同行者を守るかもしれないが、それは命令に従うだけで、仲間を気にかけているわけではない。彼女は彼らを信頼しておらず、彼らも彼女に背中を預けることはできない。\n彼らが知らないのは、彼女にとって、味方に向けた刃は卑劣で、下劣で、罰せられるべきものだということだ。\n彼女は裏切りの醜さをよく知っているため、決して仲間に刃を向けることはない。"
  },
  AwakerStory_11261_Title = {
    Text = "物語・二"
  },
  AwakerStory_11261_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11262_Content = {
    Text = "不完全な召喚の後遺症とリンクする者の変更による心理的刺激が、リリーの性格と精神にある程度の退行をもたらし、大学内での彼女の沈黙は誰の目にも明らかだ。\n\n守秘者や覚醒体ロータンのそばにいるとき以外、リリーはキャンパスに一人で現れることはほとんどない。\n教室に現れることもなく、年少の覚醒体たちのゲームにも参加しない。\n戦闘に出ないときは、寮で静かに指令を待っている。\n\nリリーの部屋の窓はキャンパスの後ろの鍵塚に面しており、夕日が沈むとき、彼女は窓辺に立ち、黄昏の光に包まれた鍵塚をぼんやりと眺める。\n\nシルバーキーの形をした墓石は、低く垂れた夕日の光で長い影を引き、窓の前に立つリリーはその墓石と同じように沈黙している。"
  },
  AwakerStory_11262_Title = {
    Text = "物語・二"
  },
  AwakerStory_11262_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11263_Content = {
    Text = "ここは花と詩の街。ここでは、情熱的なラブレターは新鮮なバラの花束と同じ価値があり、三人家族の一週間分の食料と交換できる。優れた作品が生まれることは、天才詩人が名声を得ることを意味する。彼女はかつて肥料と枯れ枝に囲まれていた庭師だった。彼女は詩の雅やかな言葉がもたらす称賛と熱狂を楽しみ、園芸を放棄し、温室に鍵をかけ、誰も花房に入れなくなった。人に聞かれると、彼女は温室に「啓示」があると答えた。彼女たちは貴族の忠実な召使いの子供だった。コンスタン連邦が成立し、旧貴族が粛清されると、彼女たちも居場所を失った。彼女はお嬢様と一緒に育った侍女だったが、早くから文章に対する才能を示していた——しかし、召使いが詩を読むことなどできるのだろうか？周囲の環境は常に変化しており、詩の才能は少女に生きる力を与えることはできなかった。すべてが少女をより不安にさせ、より憂鬱にさせた。庭師が彼女に手を差し伸べるまでは——その茨で切り裂かれた手は、彼女に庭を与えた。この小さな王国で、彼女たちは人生で最も幸せな時を過ごした。穏やかな生活は、庭師が受け取った一編の詩から変わり始めた。友人の才能はとても魅力的で、彼女はもっと多くの人にこの詩を見てもらいたいと思った。内気で憂鬱な友人は署名を嫌がったので、庭師は自分の名前を署名した——「発表されたら、彼らが賞金を送るのに便利だろうから」。庭師の変化は、最初の原稿料から始まった。彼女には理解できなかった。なぜ突然、守るべき存在から厄介者になってしまったのか。なぜ友人はすべての愛と称賛を簡単に手に入れることができるのに、自分の苦労は才能の前では無力なのか。欲望と嫉妬に駆られた彼女は、友人の信頼を利用して作品を騙し取るようになった。欺瞞は後戻りできず、種は最初から庭師の心に埋められ、天才詩人の名が広まるにつれて芽を出し、街頭インタビューで蕾をつけた——熱狂的なファンが詩の中の秘められた情感を庭師に問いかけるが、詩をまったく理解できない庭師は汗だくになり、慌ててその場を離れた。深夜に花房に戻り、友人の心配そうな顔を前に、恐怖の花が咲いた。シディを震撼させた大火の後、天才詩人は筆を封じ、短期間で得た富と名声を持って姿を消した。"
  },
  AwakerStory_11263_Title = {
    Text = "物語・三"
  },
  AwakerStory_11263_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11264_Content = {
    Text = "過去三年間、モングル三角海域で多くの船舶事故が発生し、船全体が行方不明になる事件も数件あった。\nある船員の証言によれば、事故の救助に参加した際、遭難船の甲板で「頭が光る女性」を目撃したという。\n外勤調査員がモングル三角海域に急行したが、船は一時音信不通になった。増援隊が船を見つけたとき、先遣船は動力を失い、海流に流されてモングル三角の中心に向かっていた。すべての船員は高度に脱水し、極度に衰弱し、強烈な幻覚を経験したと述べた。\n船員の医療検査中、エイヴァース調査員の所持品からシルバーコアが発見されたが、調査員本人は船が覚醒体と接触したことを否定し続けた。\nこのシルバーコアは後に覚醒体系に封印され、番号6291-S-S-01としてA.F.315年に予科調査員の覚醒教育に使用される予定である。"
  },
  AwakerStory_11264_Title = {
    Text = "物語・一"
  },
  AwakerStory_11264_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11265_Content = {
    Text = "覚醒体となった後、私たちはついに、マーフィーが教団にいた頃、どのような生活を送っていたのかを知ることになった。\n\n日傘を差し、外出の前には長い時間をかけて身なりを整える。\n午後の紅茶は必ず午後四時。ミルクティーに、イチゴジャムを添えたスコーンを合わせる。\n清潔さと上品さを保つこと。それこそが淑女の宿命。\n彼女はどこにいても淑女としての生活を貫いていた。\n（記録員の注釈：彼女が手で直接スエットプディングを掴む姿は到底淑女とは言えないと思うが……）\n\n今では彼女に仕える使用人はいないが、彼女は自分の望む生活を続けている。\nこれは確かに称賛に値することだ。\n彼女は今、覚醒体のミリアムやゴリアテと接触することを避け、故意に無視することさえある。\nまた、覚醒体のトゥルーと出会ったとき、彼女は非常に複雑な表情を見せた。\n\n過去の話題を出すと、彼女はとたんに機嫌が悪くなる。\nきっと、心の整理をつけるには、もう少し時間が必要なのだろう。"
  },
  AwakerStory_11265_Title = {
    Text = "物語・二"
  },
  AwakerStory_11265_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11266_Content = {
    Text = "彼の黒い眼帯を恐れる必要はない、交差する闇は彼の慈悲を覆い隠さない。\n\n盲目の体はすでに消え去り、救済の意志は永遠に残る。\n\n彼の前では、すべてが愛されるべきであり、すべてが愛されるだろう。\n\n父なる神の言葉は石板に刻まれ、この祝福された骨血を通じて、彼はあなたたちに「祝福」を与えるだろう。"
  },
  AwakerStory_11266_Title = {
    Text = "基本資料"
  },
  AwakerStory_11266_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11267_Content = {
    Text = "彼はいつも陰鬱な顔をして、湖畔を一人でさまよっていた。次第に、学生たちは湖畔を「陰鬱な半魚人の領地」と呼ぶようになった。彼は領主のように毎日厳かに訪れ、湖底に飛び込むと、泡が優しく彼を包み込んだ。水中では、岸からの嘲笑もあまり聞こえなかった。"
  },
  AwakerStory_11267_Title = {
    Text = "基本資料"
  },
  AwakerStory_11267_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11268_Content = {
    Text = "真の神の最も敬虔な信徒、王の最も忠実な臣民、信仰の光で巡礼の道を照らす。\n永遠の王国の崩壊と沈没は、ファロスにとって城楼が基礎を失い、蔓が土壌を失ったようなものだ。永遠の王国への信仰が彼女をこの世に浮遊させているが、長く探し求めても見つからない悲しみと無限の孤独が最終的に哀れな旅人を押しつぶした。\nファロスは彼女が愛し憎む大海に深く潜り込み、巨大な波を巻き起こし、海水が記憶の中の祭礼の焰のように華やかに翻騰し、彼女にわずかな慰めを与えた。\n英雄に首を切られた時、その如く目が向けられたのは、彼女が手放せない永遠の王国だったのだろう。"
  },
  AwakerStory_11268_Title = {
    Text = "物語・三"
  },
  AwakerStory_11268_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11269_Content = {
    Text = "彼女はいつも「ファントム号」と名付けられたオートバイの周りをうろついているようだ。\nここでネジを締め、あそこでパイプを調整する……\nこれは終わりのない作業で、多くの人が彼女がすでに修理を完璧に行ったと考えているにもかかわらず、彼女は日々それに没頭している。\nその理由は、どこからともなく湧き立つ「何かが足りない」という感覚にある。"
  },
  AwakerStory_11269_Title = {
    Text = "基本資料"
  },
  AwakerStory_11269_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11270_Content = {
    Text = "「4:30 イシス川沿いを6マイルの朝ラン。途中で通りすがりの老婦人と口論し、プードルを蹴飛ばす。\n……\n12:00 昼食を楽しむ。ハニーパンケーキ、オリーブの前菜に……5皿のローストラム肉？信じられない。\n13:00 トラウトファイトクラブへ。戦績：10勝0敗、最速記録3秒——相手が恐怖のあまり自ら棄権。\n19:00 守秘者と共にコヴェント劇場で《牧人王》を観賞、高声で危険な政治的発言をしたため追い出される。\n22:00 聖マリアンヌ病院付近を徘徊しているのを発見され、血液パックを盗もうとしていると推測される。\n以上の観察終了、危険度評価：SSS」\n——《ハンナの覚醒体観察ノート》より抜粋"
  },
  AwakerStory_11270_Title = {
    Text = "物語・二"
  },
  AwakerStory_11270_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11271_Content = {
    Text = "ファイントは実験室でこっそり涙を流す学生を見た。\n彼女が最も好きな学生ではないが、最も彼女を好きな学生だった。\n女学生はファイントの拒絶と疎遠を気にせず、彼女の制御不能な能力を恐れなかった。\n生活費を使ってすべての甘いものを買い、彼女のエネルギー不足を心配し、重い防護服を着て彼女の乱れた長髪を整えた。\n……彼女に報いるために、ファイントはできることをした。\n——もし試験不合格を心配して泣いているだけなら、他の人に成績を諦めさせればいいのでは？"
  },
  AwakerStory_11271_Title = {
    Text = "物語・二"
  },
  AwakerStory_11271_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11272_Content = {
    Text = "ミサゴは多くの覚醒体を呼び覚まし収容しているが、タイスほど特異な者はいない。\n彼女は女子学生のデートメイクを手伝い、失意の人に希望を取り戻させ、精神崩壊した調査員を陰鬱から救い出す。\n恋人のようであり、姉妹のようであり、母親のようでもある。彼女は「愛」という名の泥沼を構築し、人を密かに深く引き込み、知らぬ間に彼女のためにすべてを捧げたくなるようにする——\n学生がタイスの提供する神秘的な液体を飲むのを三度阻止した後、覚醒体管理局は彼女に対する制限令を発布した。\n「守秘者の同伴なしに、タイスがすべての学生に近づくことを厳禁とする」"
  },
  AwakerStory_11272_Title = {
    Text = "物語・二"
  },
  AwakerStory_11272_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11273_Content = {
    Text = "すべての意味は砂のように消え去り、世界の偽りの幕が彼女の目の前で剥がれ落ち、すべてが最も原始的な暗闇に戻った。\nこの漆黒の舞台での最後の演出で、科学の舞者は依然として全力で舞い続ける。\n彼女はもはや融蝕にゆっくりと飲み込まれることを気にしない、なぜならその劇の結末は最初からすでに書かれていたからだ。\nいつものように、彼女は天才の力を惜しみなく世界に捧げ、最も真理に近い方法で。\nもし少しでも問いただせば、彼女は自分がまだ人類と世界への愛を持っていると主張するだろう。彼女は人間のすべての苦痛を終わらせ、人々を真の、最初の故郷に連れ戻すつもりだ。"
  },
  AwakerStory_11273_Title = {
    Text = "物語・四"
  },
  AwakerStory_11273_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11274_Content = {
    Text = "A.F.3@1年 @1月。\nアグロ共和国東部海岸のデビルリーフで、地元の漁師が「奇妙な形の死体」を引き上げたと報告した——体は小さく曲がり、眼球が突出し、皮膚の一部が硬化し、指の間に水かきがあり、最も奇妙なのは首の両側に対称的な赤い痕があることだった。もし彼が学生の制服を着ていなければ、「人間の死体」として扱われることは難しかっただろう。\n調査員が到着したとき、その奇妙な死体は不吉なものとして恐れられた漁師によって焼かれ、当時学生の間で流行していた手提げ箱だけが残された。箱の中には着替えはなく、かすれた文字の手稿、羅針盤、そして中年女性の写真が入っていた。"
  },
  AwakerStory_11274_Title = {
    Text = "物語・一"
  },
  AwakerStory_11274_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11275_Content = {
    Text = "少女は質素な衣服を着ており、肌は先ほどの粗暴な洗浄でかすかに痛んでいた。彼女はなぜ兵士たちにここに連れてこられたのか理解できなかった。貴族の家は奴隷が自由に出入りできる場所ではなく、彼女はまだここで仕える年齢には程遠かった。\n白い長いローブを着た夫人が椅子に座り、少女は頭を垂れ、恐怖と緊張で震えていた。\n「やっぱり間違ってなかった……」夫人は言った。「とても似ている、本当に似ている」\n似ている？誰かに似ているということ？\n「素晴らしい、素晴らしいわ」夫人は嬉しそうに手を叩いた。「今日から私はあなたのママよ、覚えている？」\nママ？でも彼女にはもうママがいる。家にいて、彼女が連れて行かれるときに大声で泣いていた。\n彼女のママはどうなるの？\n疑問と困惑が少女の頭の中を巡り、答えを知りたいと思ったが、主人の意志は奴隷の命令であり、命令に逆らう奴隷は厳しく罰せられることも理解していた。\n「覚えました、夫人」\n「本当にいい子ね。考えてみると……あなたをヘロットと呼びましょう。この名前が好き？きっと好きよね。さあ、このドレスを着てママに見せて」"
  },
  AwakerStory_11275_Title = {
    Text = "物語・三"
  },
  AwakerStory_11275_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11276_Content = {
    Text = "ゴリアテは横暴で傲慢だが、彼の強さは疑いようがない。エリカ嬢の戦闘記録からもわかるように、あの粗暴な力は彼一人で危険を突破するのに十分だ。ゴリアテがパートナーの能力の強さを気にしないのは、彼の世界には彼より強い人間がいないからだと思う。\nしかしゴリアテはミリアムに対して、いつも無意識に少し恐れを見せる。いったいどんな存在が、この強大なリーダーである暴虐な旧王に畏敬の念を抱かせるのか、想像しがたい。\nまた、彼はマーフィー嬢に対して並々ならぬ関心を示している。彼は時々、マーフィーが任務を終えて帰ってくるのを待つかのように、学校の迷宮の周りをうろつくことがある。また、マーフィーが任務中に怪我をしていないか、こっそり観察することもある。\nピズリー嬢もこのことに気づいており、「ねえ、彼は普通の父親になろうとしているんじゃない？」と半ば冗談めかして言っていた。\n——《ある研修生の観察記録》より"
  },
  AwakerStory_11276_Title = {
    Text = "物語・二"
  },
  AwakerStory_11276_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11277_Content = {
    Text = "ウインクルのオフィスは、ミサゴ大学の北極星と呼ばれている。そこは常に明るく、あらゆる照明器具で影ができる場所を照らしている。ランタンから石油ランプ、タングステン電球からロウソクまで、さまざまな照明が置かれているのだ。暗闇への恐怖から、彼女は眠ることすら拒み、いつも一番大きなランプの下で、誰にも理解できない記号を、散らばった原稿用紙に書き続けている。昼夜を問わず、ずっと。"
  },
  AwakerStory_11277_Title = {
    Text = "基本資料"
  },
  AwakerStory_11277_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11278_Content = {
    Text = "カエクスは人間を嫌っていた。彼がまだ子供の頃から、彼は彼らを嫌っていた。\n彼は溺れた少女を救ったが、他の子供たちに害を与える者として非難された。彼は彼らを避けて遠くに逃げたが、「臭いカエル人間」と追いかけられた。\n\nその十数年の陰鬱な日々の中で、彼に少しの希望を与えたのは、叔父・アウンからの手紙だけだった。彼の博識には無限の怪談が含まれており、小さなカエクスは夢中になった。しかし、良い時期は長く続かず、数年後にはアウンは行方不明になった。\n16歳の年にカエクスが祖父の家を訪れたとき、偶然アウンの手稿を見つけた。彼はついに体に刻まれた歪んだ模様に隠された高貴な意味を知った。\nああ、人間は結局劣等な下等生物に過ぎない。\nそれ以来、彼は悲観的になることはなく、運命が訪れる日を静かに待つことにした。"
  },
  AwakerStory_11278_Title = {
    Text = "物語・三"
  },
  AwakerStory_11278_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11279_Content = {
    Text = "少年がかつて「死の騎士」と呼ばれていたことを覚えている者は、校内にはほとんどいない。\nだが真夜中になると、あの日の光景が悪夢となって少年の夢に忍びこむ。キャンパスに侵入した融蝕生物、崩れた鐘楼、瀕死の「守秘者」。\n 「泣かないでオジール、これはあなたのせいじゃない……」\n祖国に侵入した鉄騎、崩れた離宮、姫の指から流れた黒い血。\n「私のために犠牲にならないで、オジール、あなたはもう十分頑張った……」\n記憶の砂が痛みを伴い、少年の魂を削る。"
  },
  AwakerStory_11279_Title = {
    Text = "物語・三"
  },
  AwakerStory_11279_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11280_Content = {
    Text = "覚醒体の中には、覚醒た後に新しい体や新しい生活に適応できない者もいれば、すぐに現状を受け入れ、積極的に第二の人生を始める者もいる。\nトゥルーはどちらにも属さない。彼ほど露骨に現代世界に興味を示さない者はいない。\n彼の素質は非常に優れており、現代世界の情勢や危機をすでに洞察しているかもしれないが、彼はむしろ多くの時間を睡眠に費やすことを好む。\n本人の望みではないが、彼は学校の人間と覚醒体の間でかなりの名声を持っている。研究者たちは彼の一挙一動を観察し、時折論文を発表する。考古学系や天文学系からはさまざまな名目の学術討論の招待が頻繁に届き、大部分は彼を指名して参加を求める。\nトゥルーは覚醒体の間でもかなりの影響力を持っている。マーフィーは彼を見ると不機嫌になり、ゴリアテは彼と密かに競い合いたがっているようで、ミリアムは彼の言葉をすべて聖旨として受け止めている。\nこれらに対して、彼は特別な態度を示したことはなく、期待も要求もしていない。\n時には、気まぐれに一部の要求に応じることもあれば、応じないこともある。"
  },
  AwakerStory_11280_Title = {
    Text = "物語・二"
  },
  AwakerStory_11280_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11281_Content = {
    Text = "覚醒体となった今でも、ソレールは彼女に媚びへつらう貴族たちを忘れられない。諂いに満ちた顔の数々を忘れられない。\nその笑顔はどれほど嫌悪感を抱かせることか。油っぽく、俗っぽく、彼女への欲望と計算が透けて見える。しかし彼女はそんな顔に優しい網を編まねばならなかった。\n彼女は最も緻密な網を編み、あらゆる陰暗な隅々に入り込み、すべての人を取り込み、すべての手がかりを掌握する必要があった。\n彼女はまた、徐々に温度が上がる水のように、彼らをその中に溺れさせ、仮面を外そうとしたときにはもう逃れられないことに気づかせる必要があった。\nしかし、気づいたときには、逃れられないのは彼女自身だった。\n逃げられない、気を緩められない、諦められない。\nソレールにはもう後戻りする権利はなく、すべての人の上に立つ以外に道はない。"
  },
  AwakerStory_11281_Title = {
    Text = "物語・四"
  },
  AwakerStory_11281_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11282_Content = {
    Text = "「葡萄酒のように黒いアメジストをつけたい」\n「ダチョウの羽毛で作った豪華なドレスを着たい」\n「チームで一番輝く存在になりたい」\n琥珀色の瞳をした侍女は、まだまだたくさんの願いがあったが、もうそれを口にすることはできなかった。固まった彼女の前には、果てしなく続く緑炎が、漆黒の夜に咲き誇っていた。"
  },
  AwakerStory_11282_Title = {
    Text = "基本資料"
  },
  AwakerStory_11282_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11283_Content = {
    Text = "彼女は剣を振る速度を計算し、攻撃を避ける角度を計算した。\n彼女は逃走計画の実現可能性を計算し、世界が未来に進む確率を計算した。\n最後まで、彼女は計算を諦めなかった。\nそれは彼女がこの無人の地を歩むことを決して諦めなかったように。"
  },
  AwakerStory_11283_Title = {
    Text = "基本資料"
  },
  AwakerStory_11283_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11284_Content = {
    Text = "シディから来た芸術家は人間に関心を持たない。\nある種の絶対的な純粋な美だけを追求し、一瞬の瞬間を永遠に刻みこんでいく。\nインスピレーションの泉が湧き出し、彫刻刀は止まらない。\n作品を完成させるたびに、珊瑚色の靄が身体を蝕み、痛みと喜びが共存するが、倫理なき芸術家は自分自身のことなど気にもとめない。"
  },
  AwakerStory_11284_Title = {
    Text = "基本資料"
  },
  AwakerStory_11284_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11285_Content = {
    Text = "@3は第二サムニウム時代に建てられ、精巧な第三ポンペイとレムワヒ化スタイルで装飾されており、これはローマ時代の裕福な商人階級の典型的な住宅である。2つの中庭、4つのトリクリニアを持ち、@1@1\n…………あの有名な奴隷反乱で焼き尽くされた…………同時期の逸話によれば、廃墟の地下には巨大な白い蜘蛛が封印されており、地元の人々はそれを「迷宮の神」と呼び、その領域に足を踏み入れた人間は無数の通路と入口で方向を見失い、最終的にその子孫の宿主になると信じている。\n面白い恐怖の物語だが、私たちを阻むことはない@2@1\n――「@2廃墟考古ノート」より抜粋\n\n…………状況は非常に悪い、グッドマン卿。モレッティ一行は数日間行方不明で、私たちは「迷宮の神」の伝説とは関係がないことを理解しているが、それは確かに不安を引き起こす。現在、私たちは調査を早期に終了し、ダラムに戻ることを決定した。\nさらに、考古学チームは廃墟で銀色のコア状物を発見し、これは以前にあなたが言及した@1と関係があるかもしれない…………\n――クラークソン・ジョンソン「グッドマンへの手紙」より抜粋"
  },
  AwakerStory_11285_Title = {
    Text = "物語・一"
  },
  AwakerStory_11285_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11286_Content = {
    Text = "A.F.2@2年11月、ベレン地区で大地震が発生した。\n翌日、二人の教授が震災地に向かうよう命じられ、震災後に連絡が取れなくなったミサゴの調査員チームを探すことになった。\nチームは失踪前、陸間海沿岸で活動しており、主な任務は歴史的遺跡の探査と発掘、「融蝕現象」に関連する可能性のある手がかりを探すことだった。\n11月8日、チームメンバーの最後の目撃情報があった場所で、@2教授は史料に記録されていない離宮の遺跡を発見し、ミサゴの制式シルバーキー、番号I-@2を回収したが、チームのメンバーは見つからなかった。\n11月9日、遺跡から2つのシルバーコアが発掘され、後にレンティニエンに持ち帰られ、歴史的価値があるため封印され、後日覚醒させることになった。"
  },
  AwakerStory_11286_Title = {
    Text = "物語・一"
  },
  AwakerStory_11286_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11287_Content = {
    Text = "ワンダはミサゴに来た初日に「他人を無作為に踏みつけた」として厳しく非難された。\n\nある匿名の学生によると、彼は図書館の前を通りかかった際にワンダと偶然目が合った。\nそれだけで、すぐに地面に叩きつけられ、@3を@2で縛り上げられたという。\n（※当該学生はこれ以上の詳細な説明を拒否している）\n\n傷害の過程は発生から終了まで5分もかからず、その行為の悪質さと衝撃は、見る者すべてを戦慄させた。\n\nミサゴ大学の規律委員会（以下、MDC）はこの状況を重く受け止め、深い同情を示し、特別な調査チームを結成した。\n\n今後、ワンダに対して思想および行動両面での徹底的な更生指導を行い、彼女が一日も早く学園生活に適応できるよう支援を続けていくとのことだ。"
  },
  AwakerStory_11287_Title = {
    Text = "物語・二"
  },
  AwakerStory_11287_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11288_Content = {
    Text = "「@1月@1日、大学墓地が再び破壊された。これまでに、今月三回目の悪質な墓荒らし事件が発生している。\n協会メンバーは数週間にわたる追跡調査の末、覚醒体珊を容疑者として特定した。\nこの倫理なき芸術家の作業場を訪れた人は皆、形態が異なり、奇妙で冒涜的な海洋テーマの彫刻に驚き、その素材の出所に疑問を抱く。ここで可哀想なナターシャが埋葬されたときに着けていた貝殻のネックレスと、墓石と同じ材質のアバディーン花崗岩が発見された。創作理念の説明に熱心なピックマンとは異なり、サンガーは捉えどころがなく、微笑みながらも我々の疑問を完全に無視した。\n彼女の彫刻刀に触れないように、彼女と作業場に二人きりにならないように——デクスター教授はそう警告したが、墓荒らし事件の真相を解明するためには、過激な手段が必要だ。\n今は@1月@1日0時45分、推理愛好者協会のメンバー@2がサンガーの作業場に潜入した、幸運を祈って@3」\n——《推理愛好者協会、調査記録S-618》より抜粋"
  },
  AwakerStory_11288_Title = {
    Text = "物語・二"
  },
  AwakerStory_11288_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11289_Content = {
    Text = "ロータンには多くのレッテルが貼られており、誰もこの黒衣の剣士とどう接すればいいのかわからない。\n謙虚すぎると、つまらないと言われ膝を砕かれ、傲慢すぎると、大剣で無礼を断ち切られ、強硬すぎると、戦いで魂を骨抜きにされる。\nだが、これこそが惑星の初子の傲慢なのかもしれない。かつての守護者として、彼女は傲慢である権利を享受しているのだ。"
  },
  AwakerStory_11289_Title = {
    Text = "基本資料"
  },
  AwakerStory_11289_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11290_Content = {
    Text = "夜が訪れるたびに、ナウティラは母親と一緒に倉庫に入り、さまざまな工具を手に取り、集めた部品で「ファントム号」と名付けた一輪のオートバイを組み立てる。\n「どうして直接買わないの？」幼い彼女は顔を上げ、工具を持つ母親に尋ねた。「そうすればすぐに冒険に出られるのに」\n母親は彼女の手を握り、金属を早く上手に溶接する方法を教えながら言った。\n「機械も人間と同じで、それぞれに異なる気性と性格がある。私たちを本当に理解してくれる人だけが、私たちと一緒に長い時間を過ごせるのよ」\n「友達みたいに？」\n「機械が私たちの作ったものであることを除けば、そうね。友達みたいに」\n巨大なホイールハブは頑丈でなければならず、搭載されたエンジンは耐久性がなければならない。なぜなら、一度出発したら、簡単には振り返らないからだ。彼女たちは一緒に世界を巡り、大冒険を成し遂げるのだ。\n病気が彼女の母親を連れ去り、工具でいっぱいの空っぽの修理工場だけが残った。ナウティラは未完成のファントム号を抱きしめ、この冷たい友と共に母との夢を実現することを決意した。\n最後の航海まで。"
  },
  AwakerStory_11290_Title = {
    Text = "物語・三"
  },
  AwakerStory_11290_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11291_Content = {
    Text = "A.F.3@2年の夏。\nイリアン島では海の怪物の伝説が広まりつつあった。\nある漁師は、近海でおよそ五階建ての建物ほどの高さを持つ頭足類の生物を目撃したと主張した。\nその全身は深紅に染まり、触手には黒い同心円状の模様が刻まれていたという。\n\nその奇妙な噂を耳にしたとき、私はヨハンソン先輩と共に、メダン地区で発生したとされる融蝕現象の調査を行っていた。\n翌日、先輩はすぐにイリアン島へ向かう船を手配し、私はアミランテ洋の真ん中でこの報告書を書き始めた。\n\n航海三日目、海面には無数の魚の死骸が浮かんでいた。\nサバ、ヒラメ、イルカ……そして、私は誓って言える。\nその群れの中には、妊娠したマッコウクジラの死体もあったのだ。\n古い船乗りたちは、過剰繁殖による海水の酸素不足が魚の死因だと言ったが、私はどうしても、我々が何かを見落としているような気がしてならなかった……\n\n航海八日目、私の船酔いはますます酷くなり、激しい吐き気で食事もほとんど喉を通らない。\n目的地のイリアン島までもうすぐだったが、ヨハンソン先輩は強い口調で@3への帰航を要求していた……\n理由は分からなかったが、私は彼の判断を信じることにした。\n\n——ベル・コロンブス《A.F.3@2年夏季実習報告書》"
  },
  AwakerStory_11291_Title = {
    Text = "物語・一"
  },
  AwakerStory_11291_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11292_Content = {
    Text = "誕妄・マーフィーはかつて一度、死を経験した。\n喜んでとは言えない形で「神降」と呼ばれる扉をくぐった後、彼女は「神明」が自らの胸に降臨するのを目撃した。\nなんと滑稽なことか。それは意識も感覚もない醜い塊に過ぎなかったのに、彼女はそのために輝かしい人生を捧げなければならなかった。\nさらに皮肉なことに、倒錯した運命は常に容赦なく彼女を追い続けた。神明が世に降臨した瞬間、彼女は激しい苦痛に耐えながら、心から望んでいたわけでもない犠牲を受け入れた。長い、まるで眠りのような時を経た後、マーフィーは驚愕して目を開け、目の前の光景が臨終前と何ら変わらないことに気づいた。\n\n「マーフィー」は死に、「誕妄・マーフィー」が目覚めた。\n\n彼女の連結者は、彼女自身が産んだ、耳も聞こえず、口も利けない蠢く血の塊だった。\n神明が王女を産み、王女が再び神明を宿し、そして神明が再び彼女の遺骸を目覚めさせた。病的な運命が彼女にしっかりと絡みつき、永遠に日の目を見ることなく、断ち切ることもできない。\n彼女の敬虔な母は狂喜し、蹈海者たちは地に伏して祈り、彼女の栄誉は続き、かつてよりもさらに盛んになった。\nしかしあの「マーフィー」は結局、永遠に消えてしまった。かつて愚かな純粋さを胸に、不公平な運命に反逆しようとした少女は、一度は嫌悪した虚栄の冠を抱きしめ、永遠に対岸に辿り着けない客船に乗り込んだ。"
  },
  AwakerStory_11292_Title = {
    Text = "物語・三"
  },
  AwakerStory_11292_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11293_Content = {
    Text = "私は海が好き。フェイフルの海。プルシアンブルーの海。湿った暖かい風が吹く海。療養所の窓枠から見ると絵画のような海。帰帆を運ぶ海。母のように無数の命を育む海。\n今、私はついに静かな海に戻り、未だ生まれていなかった頃に戻り、母の羊水に包まれた胎内に戻った。海流が不幸な破片を拾いあげ、白骨と珊瑚の間で私を組み立てる。深海の魚たちが泳ぎながら、運命の苦難についてのため息を聞いている。\n母よ、もしもう一度この世に生まれることができたなら、私はもっと幸せになれるのでしょうか？"
  },
  AwakerStory_11293_Title = {
    Text = "物語・四"
  },
  AwakerStory_11293_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11294_Content = {
    Text = "エフロタス考古チームは怪病に悩まされてから十日が経過し、状況は依然として改善されていない。\n怪病は予兆もなく現れたが、勢いは凶猛だ。患者は通常、重度の幻覚を伴い、身体感覚の喪失、感覚の喪失などの症状を示し、時間が経つにつれて悪化し、最終的には半身または全身の麻痺に至る。現在のところ、病気の感染範囲はエフロタス川西岸の考古現場に限定されており、患者も考古現場のスタッフや駐在学者が多いが、当局は周囲への拡散の可能性を排除できない。\n考古現場で働いていたある労働者が記者に明かしたところによると、怪病は十五日前にすでに兆しを見せていた——それはエフロタスの手錠が発掘された日だった。考古学関連のニュースに関心のある読者は、この保存状態が良く、錆びた痕跡が一切ないが、確かに古代文明から来た手錠を覚えているだろう。それは昨日レオ王国に到着し、ミサゴ大学が後続の研究を引き継いだ。怪病と手錠の関連性は、より神秘的な色彩を帯びている。\n「それを掘り出してから、キャンプはおかしくなった」その労働者は記者に指摘した。「多くの人が奇妙な夢を見て、鎖で檻に閉じ込められた少女を夢に見た人もいる。夜中に……これは呪いだ、手錠の呪いだ！他に説明はない」\n報道日現在、関連部門がその地域を管理し、いかなる人員の出入りも厳禁されている。エフロタス考古活動は完全に停止している。\n——《古代の呪い？怪病がエフロタス考古チームを襲う》"
  },
  AwakerStory_11294_Title = {
    Text = "物語・一"
  },
  AwakerStory_11294_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11295_Content = {
    Text = "ライカーを覚醒させたシルバーコアは、ヴォルムワヒで有名な「三角の巨塔」の内部から出土した。\n\n流線型の完璧な弾丸型をしており、サイズと形状はSAAリボルバー用の弾丸と一致していた。\nそして、それは若い男性の頭蓋骨に埋まっていた。\n\nこのシルバーコアに触れると、壮大で美しい三角の巨塔が目の前に現れ、体が勝手に委縮し、地に伏せてしまう。\n必死に抗った場合、前を見上げると、逆光の中に冠をかぶった男の姿がおぼろげに見えるが、意識は途切れて、シルバーコアは自然に手から離れる。\n\n「三角の巨塔の尖塔がまだ摩耗していない状態であることから、これは建設されてから間もない頃の景色のはずだ」\n——実験員B・R・ラングマン\n\n「暗い魂の奥底から恐ろしい囁きが聞こえる」\n——実験員K・ウォーターズ\n\n「ミサゴ大学が私たちに行わせた非人道的な実験を告発する。シルバーコアに繰り返し触れることによる副作用は、肉体の制御能力を完全に失う可能性がある。とにかく、私はこれに触れることを今後、断固として拒否する」\n——実験員L・ロペス"
  },
  AwakerStory_11295_Title = {
    Text = "物語・一"
  },
  AwakerStory_11295_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11296_Content = {
    Text = "A. F. 18@1年@1月、@2歩兵団、レムワヒ王国、アレクサンドリア港\nアレクサンドリア港の状況は徐々に安定し、歩兵団の第三営、第四営、そして三つの連隊の火銃兵が運河を通って@4へ次の作戦に向かっている。現在、第一営と一連の火銃兵のみがアレクサンドリアを守っている。\nパトロール中の小隊が反乱軍に遭遇し、迅速に解決した。彼らは面白い小物を持ち帰った。それは銀のように見えるが、銀よりも重い。私はそれを金庫にしまった。指揮官はこの贈り物を気に入るだろう。\n…………\n駐留13日目、異常行動を示す兵士が各連隊で現れた。具体的な行動には、仲間や上官への攻撃、物資補給や軍事装備の破壊などが含まれる。これらの者たちは、以前の暴動を起こした狂人たちと共に、私の監視下で拘束されている。\n彼らの目は赤く、唾を飛ばし、兵士というよりも哀れな動物のようだ。ここには何か狂気が蔓延しており、それが疫病に発展するのではないかと心配している。\n…………\n駐留30日目。\n今日までに、370名の兵士が狂気の行動を示し、そのうち331名が重度のヒステリーを示してから20日後に四肢の麻痺を起こした。彼らの攻撃性は依然として強く、2名の軍医が患者の診察を試みた際に噛まれた。\n狂気は依然として広がっている。私は状況を報告し、早急な対応を求めている。\n…………\n審査会がアレクサンドリア駐留軍を引き継いでから10日が経過したが、人々は依然として狂気に陥っている。私の仲間たちも次々と狂気に陥っている。なぜ我々だけがこの忌まわしい疫病に苦しめられるのか理解できない。なぜ地元の人々や我々に常に問題を起こす反乱軍は無事なのか？\n頭痛がますますひどくなり、軍医たちは無力だ——彼らは私よりも早く狂気に陥り、地面に倒れて噛みつく怪物の一部となっている。\n私も狂気に陥るのではないかと心配している。\nあの連中はミサゴ大学の人間を待たなければならないと言っている。くそったれ、我々は国のために命を懸けているのに、こんな扱いを受けるべきではない。\n…………\nわかった、ついにわかった。それは怨霊であり、その銀の中に宿っていて、この土地を侵略したすべての者に復讐しようとしている。片足のないあの女は我々に立ち去れと言っている。彼女は我々全員に立ち去れと言い、ここのすべてを元の主人に返せと言っている。そうだ、そうだ、そうあるべきだ、そうあるべきなのだ、我々はここに来るべきではなかった、この戦争を始めるべきではなかった、私は@1@3@4@2@1@2@3\n——抜粋自『@2歩兵団第一営代理指揮官日誌』"
  },
  AwakerStory_11296_Title = {
    Text = "物語・一"
  },
  AwakerStory_11296_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11297_Content = {
    Text = "彼女は血を飲んで生きているわけではなく、かつては儚い花のような熱烈で短い温情を浴びていた。裏切りと牢獄の災いが反逆の炎を育て、復讐の火がメシアを焼き尽くし、絶え間ない憎しみに染まった彼女の心は、もはや誰にも開かれることはない……"
  },
  AwakerStory_11297_Title = {
    Text = "基本資料"
  },
  AwakerStory_11297_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11298_Content = {
    Text = "この前身が「缶の中の脳」である真貌覚醒体は、S355拘束器からの脱出歴があるため、現在ハレト学長によって移送され、新型特殊融蝕制限器に配置されている。\nこの制限器は昏き海の深部に位置し、制限器周囲30メートル半径に他の機器や物品が存在しないことを保証した上で、昏き海監視チームが少なくとも60分ごとに巡回監視を行う。\n監視中に発見されたのは、この覚醒体が常に意識を保ち、ほとんど眠ることがないということだ。この覚醒体は巡回メンバーに対して以前行った違法なシルバーコア改造実験について話そうとしたことがあり、一人のチームメンバーが短時間の交流で狂気に陥った。\n現在、すべての巡回チームは三人で構成され、この覚醒体との接触や会話を厳禁し、巡回時には常に防音イヤーマフを着用する。\n……\nこの覚醒体の機密制限レベルは覚醒体管理の最大レベルに達しており、知っている者はミサゴ内外にこの覚醒体に関する情報を漏らしてはならず、院長の承認と護送がない限り、誰も訪問を禁止されている。\n——《ミサゴ昏き海監視チーム報告記録》より抜粋"
  },
  AwakerStory_11298_Title = {
    Text = "物語・二"
  },
  AwakerStory_11298_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11299_Content = {
    Text = "そのモノは実在している。\nそのモノは神の目が宇宙に向けて伸ばした枝葉である。\nそのモノは歴史の壮大さを楽しみ、文明の繁栄を渇望している。\nそのモノは枯れゆくものを超え、死をも超えたいと願っている。\n\n彼女は低く響く詠唱、砂と塩気を含む風、銀色の葉とモスルの月光を望んでいる。\n妖婦、魔女、女巫……世間の目はただのノイズに過ぎない。\nたとえ一滴の血でも黒き浸蝕から逃れられるなら、そのモノは再び永遠を抱きしめることができるのだから。"
  },
  AwakerStory_11299_Title = {
    Text = "物語・四"
  },
  AwakerStory_11299_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11300_Content = {
    Text = "薔薇の鋭い棘が詩篇の頁を裂いて、透明な血の痕を残した。\n酒精の香りが立ち上り、無色の炎が静かに広がる。\n\nその烈火のただ中、オルラは最後の詩章を胸に、温室に身を潜める天才詩人の末路に、無言の注釈を書き添えた。"
  },
  AwakerStory_11300_Title = {
    Text = "基本資料"
  },
  AwakerStory_11300_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11301_Content = {
    Text = "彼女は少女時代を軍隊で過ごした。\n軍隊で育ったすべての子供たちと同じように、彼女は軍の栄光を深く信じ、それを自分の命と見なしていた。彼女の世界は単純だった。指揮官が認めたものは正しく、指揮官が禁止したものは間違っている。\n「剣を敵に向けろ。我々はこの土地に真の自由をもたらす。侵略軍を斬り倒せ。彼らに同情するな。今の犠牲は未来の安定と繁栄のためだ」\n彼女はこのようなスローガンのもとで訓練を受け、このようなスローガンのもと戦場に立った。命がけの救援ののち、彼女は傷ついた足と戦争英雄の称号を得た。それ以来、彼女は勲章をつけて後方に退き、新兵の教官となったが、この傷ついた足がどのような世界を彼女に示すのか全く知らなかった。\n義足が侮辱され、アルバは退役した。街に出た彼女は、指揮官の輝かしい演説がどれほどの嘘であるかを初めて知った——解放は侵略の口実に過ぎず、異国の人々は苦しんでいた。\nこれは彼女の理想郷ではなく、血と涙のない輝かしい未来ではなかった。\n彼女はかつての同僚に償いの刃を向け、真の正義のために戦うことを誓った。"
  },
  AwakerStory_11301_Title = {
    Text = "物語・三"
  },
  AwakerStory_11301_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11302_Content = {
    Text = "「ダフォダイルの交換商店へようこそ。ここでは物々交換と首の買取を行っています。価格は公正で、誰でも安心してご利用いただけます」\n灰色の霧の中、女性は古びた木製のパイプを軽く叩き、揺れる帽子の下から曖昧な笑みを浮かべた。"
  },
  AwakerStory_11302_Title = {
    Text = "基本資料"
  },
  AwakerStory_11302_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11303_Content = {
    Text = "みんなすぐにある事実を受け入れました。ジェンキンのいるところにはブラウンがいて、ブラウンのいるところにはジェンキンがいる。そしてブラウンが単独で行動したら、疑うな、背後には必ずジェンキンの影がある。\n「あたしが何を盗んだって？あたしにはアリバイがあるんだから！」\n少女はブラウンが「取った」ものを持ちながらそう言いました。"
  },
  AwakerStory_11303_Title = {
    Text = "基本資料"
  },
  AwakerStory_11303_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11304_Content = {
    Text = "A.F.180年、北半球の大干ばつの影響で、カラス川が干上がった。\n地元住民が川底の泥から怪物の骨格を掘り出し、カラス川が地元文化で「混水」を意味することから、その骨格は「混沌の骨」と名付けられた。\n海洋生物学者によると、これは全身が銀色の物質で覆われた、全長約32フィートのオオツバメクジラの骨格であるという。\n翌年、この骨格はイシスのオークションで1億3千万スタールで落札された。取引所は買い手の正体を明かすことを拒んだが、噂によると、この骨格はロンディニウム郊外の私立大学に運ばれたという。"
  },
  AwakerStory_11304_Title = {
    Text = "物語・一"
  },
  AwakerStory_11304_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11305_Content = {
    Text = "傲慢で他者を顧みない振る舞いは、虚勢を張るための鎧に過ぎなかった。その華やかなドレスの下には、誰も知らない反逆の心が隠されている。\n神聖なる物語が織り上げた、美しくも閉ざされた牢獄の中で、マーフィーは、人間と神の偽善を誰よりも知っていた。信徒たちが彼女を見るその眼差しには、畏れと哀れみしかなく、「育ての親」の愛情は、ただの供物への世話に過ぎない。使命の終わりは栄光ではなく、自らの死である——その結末をとうに知っていた彼女が、教義が描く遠い楽園に酔うはずもない。\n神を造る計画、古き王の復活、多くの非現実的な期待が彼女に託されている——しかし誰も彼女自身が不確実な未来のために死を受け入れるかどうかを気にしていない。\nカナリアは永遠に檻の中に閉じ込められることを望まない。だからこそ、棘だらけの垣根へと翼を広げて飛び立ったのだ。命を賭して運命の鎖を断ち切った彼女は、この先、自らの意思で飛ぶべき空を選ぶ。\n「わたくしはマーフィー…………指図なんてさせないわ！何をすべきか、何をすべきでないか、そんなことくらい自分でわかっているんだから」"
  },
  AwakerStory_11305_Title = {
    Text = "物語・四"
  },
  AwakerStory_11305_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11305_UnlockDesc_1 = {
    Text = "メインストーリー通常第5章「嵐の眼」クリア"
  },
  AwakerStory_11306_Content = {
    Text = "孤独の中で滅びを迎えた海の精霊は、陸上で奇跡的に生き延びた。\n生まれつき楽天的であろうと、苦痛を避けるために忘却を選んだのであろうと、率直な純真さは無限の魅力を放ち、人々を彼女の陣営に引き込む——それは彼女が「仲間のチーム」を拡大するための小さな策略かもしれない。"
  },
  AwakerStory_11306_Title = {
    Text = "基本資料"
  },
  AwakerStory_11306_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11307_Content = {
    Text = "混沌の中で生まれた生命体として、彼女は純粋な混沌の力であり、束縛されない自由な魂であり、未定義の秩序でもある。\n挑戦と戦いが必要であり、抑えきれない破壊欲求を解放することで、彼女は創造主からの唯一の遺言を果たすことができる。\n——惑星の終わりまで見守るために、彼女はずっと壮絶な戦いを望んでいた。"
  },
  AwakerStory_11307_Title = {
    Text = "物語・四"
  },
  AwakerStory_11307_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11308_Content = {
    Text = "私は願いを持つ資格があるのか？\nもしあるなら、妹の一部になれますか？\n彼女を完全にし、私たちを完全にする。\nそうすれば、私は遠慮なく「愛」を表現でき、彼女も心置きなく「愛」を抱きしめられる。\n親愛なるティンクト……これは先に生まれた子として、あなたにしてあげるべきことよね。"
  },
  AwakerStory_11308_Title = {
    Text = "物語・四"
  },
  AwakerStory_11308_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11309_Content = {
    Text = "「容赦ない評価」、「低得点の試験」、「不合格の研究報告」\nドールの数十年にわたる教職生活で、彼女の手から卒業証書を受け取った学生は数えるほどしかいない。ほとんどの学生は彼女の厳しすぎる態度に追いつめられ、他の教授の元に転向した。長い間に、ドール教授の悪名は学生の間で広まった。\nしかし、彼女がこの基準で「門徒」を選んでいると信じる学生もいる。最も意志が強い者だけが、真理の扉を開く鍵を握り、彼女と共に世界の真実のヴェールを剥がす資格があると。\nこのような信念に支えられ、ドールのもとで卒業する可能性が極めて低いにもかかわらず、ドールに教えを受けたいという申請書は絶え間なくオフィスに飛びこんでくる。\n時折、申請書を臨時に審査するように呼ばれたラモンナは、学生たちがこれほど信じているなら、それも悪くないと思うことがある。\nラモンナにとって、彼女はただ覚醒体としての基準で人間の学生を要求しているだけに過ぎない。"
  },
  AwakerStory_11309_Title = {
    Text = "物語・二"
  },
  AwakerStory_11309_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11310_Content = {
    Text = "ダフォダイルのミサゴ大学での行動は神出鬼没で、彼女は次元を自由に行き来する禁忌の知識を持っており、地下の昏き海のシルバーコアの枢軸に縛られることはない。\n彼女はいつも出所不明の神秘的な機器や材料を販売し、時には他の覚醒体がミサゴ大学の支配から一時的に逃れる手助けをすることもある。\nその後、交渉を経て、彼女はキャンパスの一角、医務室の隣の古い部屋に「解憂百貨店」の支店を開設した。\nもちろん、販売されるすべての商品はミサゴ大学の登録と審査を受けなければならない。"
  },
  AwakerStory_11310_Title = {
    Text = "物語・二"
  },
  AwakerStory_11310_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11311_Content = {
    Text = "記録者：エーリッヒ・フォン・ヴェルナー\n時間：19@1年11月7日\n座標：68°14′S, 67°10′W\n\n航路上に異常に漂流する大量のマッコウクジラの死体により、我々はこの呪われた氷原の島に上陸せざるを得なかった。南岸の峡湾の氷瀑の下で、探検隊は全長約50フィートの頭足類の遺骸を発見した。その死体は深いインディゴブルーで、体表には燐光を放つ青い同心円環が密集しており、環の縁からは薄い粘液が分泌されていた。採取して精製したところ、粘液から不安を覚えるほど大量の青い結晶が析出した。\nこの遺骸の腕足の吸盤の直径は2フィートを超え、吸盤の内壁には未知の文字に似た紋様が刻まれていた。主神経索は半透明のゲル状で、マイナス30度の環境下でも微弱な拍動を保っていた（添付図D-7参照）。同行した生物学者のハリス博士が神経索の組織サンプルを採取しようとしたが、メスが触れた瞬間、遺骸全体が突然粉砕した。肉眼で見えるインディゴブルーの塵が実験室全体に漂った。\n\n帰航途中、ハリス博士は持続的な譫妄状態に陥った。彼は繰り返し船室の壁に螺旋と多面体を組み合わせた幾何学図形を描き、「南極の氷床の下で産卵している」と叫び続けた。翌朝、巡回中の船員がバラスト水槽で溺死しているのを発見した。検死の結果、肺胞内にインディゴブルーの微生物が充満していることが判明した（タコの死骸の塵と同源）。船長はサンプルに接触したすべての衣類を焼却するよう命じた。\n氷層の下に潜む悪夢に、誰も再び触れないことを願う。\n\n——《南極科学調査日誌・第37号附録》"
  },
  AwakerStory_11311_Title = {
    Text = "物語・一"
  },
  AwakerStory_11311_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11312_Content = {
    Text = "我々は英雄ユウハシュをどうして忘れられようか？彼は最も優れた男だった。戦士は夕日の砂に跪き、温かい血が彼の全身を潤した。ハゲワシが高空を旋回し、彼のために挽歌を歌った。\n涙であなたを敬う者はいない、泣いてあなたを葬る者はいない、ただ生前にあなたはローマで名を馳せたから。"
  },
  AwakerStory_11312_Title = {
    Text = "基本資料"
  },
  AwakerStory_11312_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11313_Content = {
    Text = "A. F.@2年@1月\n親愛なるキャヴェンディッシュ卿へ。\n\n突然のお願いをお許しください。フレイ執事に頼んで紙とペンを持ってきてもらい、最後の理性と体面を保ちながらこの手紙を書いています。私が病気にかかって以来、母やポピー、そしてあなたに会えず、この思いは私を狂わせるほどです。\n地下室に閉じ込められてからもう…………353日？わからない、もしかしたら326日かもしれない。\nここはとても寒く、腐った匂いがします。私の傷口からは黒い粘液が流れ、鼠に噛まれてひどい状態です。でも大丈夫、痛みは人を覚醒させるから。\n「邪悪な吸血鬼」、「家族の恥」…………私を隔離するのは賢明な判断です。私の魂はすでに悪魔に支配されており、この手紙を書いているとき、私は死んだ浮浪者の血を吸い尽くしたばかりです。フレイ執事によれば、これはあなたが街から連れてくるよう命じたそうです。味は少し変わっていましたが、あなたが私を気にかけてくれていることがわかり、とても嬉しかったです。\nそれから…………毛布を一枚いただけませんか？今は体を覆う服がなく、ロンディニウムの冬はとても寒いです。\n今でも、幼い頃にウェイティング邸で一緒に休暇を過ごした日々が懐かしいです。\n\nあなたの誠実な妹\nレーア\n——「ケンジントン吸血鬼事件・事件概要：証拠品C-601」より抜粋"
  },
  AwakerStory_11313_Title = {
    Text = "物語・三"
  },
  AwakerStory_11313_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11314_Content = {
    Text = "A.F.31@1年12月中旬、警察は@2ガーデン第二劇場の管理者から通報を受けた。通報者によると、劇場では1週間のうちに4回の小規模な火災が発生し、「バレエの幽霊」という噂が、劇場を借りている舞踏団の間で広まっていた。\nバレエ《白鳥の挽歌》の初公演を無事に行うため、警察は西区消防署と合同調査を行った。\n公演前日、ミサゴ大学が調査を引き継いだ。調査員は、複数の火元に霊知の痕跡が残っていることに気づく。最終的に、@3調査員は第二劇場の地下遺跡で覚醒体を発見した。\nその覚醒体は理性を持ち、「リッツ」と名乗った。話し合いの末、覚醒体リッツは放火の罪を認めた。《白鳥の挽歌》の初公演終了後、@3調査員は覚醒体リッツをミサゴ大学に連れ帰り、正式に編入した。\n\n歴史記録によると、A.F.29@1年、@2ガーデン第二劇場で火災が発生した当時、劇場ではバレエが上演されていた。火災で亡くなったのは、観客席の貴族たちと、「エリザベス・サラー」という若きバレエのプリンシパルだった。"
  },
  AwakerStory_11314_Title = {
    Text = "物語・一"
  },
  AwakerStory_11314_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11315_Content = {
    Text = "一歩、また一歩と、私はゆっくりと水中に歩みを進めた。療養所の看護師は、私がこれほど遠くまで行くことを許してくれたことはなかった。療養費をすぐに払えなくなる患者の脱走が、彼女にあまり責めを負わせないことを願う。\n夕日の余韻が海に映し出されている。波が顔に当たり、優しくスカートを持ち上げる。海水の温度は、母の抱擁のように温かい。\n体がこれほど軽やかに感じたことはない。私の胸の中には枯れた火山があり、今ではそこに海風が吹いているだけだ。\n「帰ろう」\n私は海が両親の声で私を呼んでいるのを聞いた。彼らは私の病気を治すためにお金を稼ぐために海の向こう側に行った。もし私がこんな不幸な体で生まれなければ、彼らもこんなに苦労しなかっただろう。もし私がある月夜に、静かに海の中に消えることができたなら…………私は何度もそう思ったが、両親の悲しむ顔を思い浮かべると、やめざるを得なかった。\nしかしある日、月夜に、両親の乗った船が静かに海に消えた。\n「帰ろう」\n私は全身の力を振り絞って足を速めた。海は常にすべての苦しむ魂を静かに受け入れ、私にとって両親がいる場所こそが永遠の安住の地だ。\n四方八方から夜が訪れるとき、私は生まれて初めて自由に呼吸することができた。"
  },
  AwakerStory_11315_Title = {
    Text = "物語・三"
  },
  AwakerStory_11315_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11316_Content = {
    Text = "超人的知恵は身体に過度な負担をかけ、彼は毎日15時間以上昏睡し、目覚めている時も常に疲れている。\n夢の中で、彼は時に神々の怒りを感じ、時に交錯する時空を夢見、時には深く入り込み神と対面することさえある……\n彼は神に啓示や予言を求めたことはないが、どんなに逃げても予言は必ず成就する。\n彼は何も供物を求めたことはなく、崇拝されることも畏れられることも他人が勝手にしたことであり、彼は全く興味がない。\n再生も彼の永遠の夢を邪魔したに過ぎない。\n呼びかける必要も、祈る必要もない。"
  },
  AwakerStory_11316_Title = {
    Text = "物語・四"
  },
  AwakerStory_11316_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11317_Content = {
    Text = "……\n実験日：A.F.@1年@2月\n実験目的：融蝕患者が組織器官を移植した後の変異反応の観察記録\n実験手順：@3@4\n実験体の死んだ兄を移植実験に用い、直系親族間の拒絶反応を観察する。この哀れな虫は警察の逮捕を逃れようとして、何発も撃たれて死んだ@3実験は非常に成功し、傷口は赤くなり、触手が増殖した……血液はまるでルビーのように噴き出した。\n@3@3\n実験者は驚くべき忍耐力を示し、モルヒネの注射を拒否した。\n実験後、血を渇望する欲求が増し、性格は……何とも言えない、とにかく私が得意とするタイプではない。\n——ハーバート《融蝕実験記録・第4組@1号》より抜粋"
  },
  AwakerStory_11317_Title = {
    Text = "物語・一"
  },
  AwakerStory_11317_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11318_Content = {
    Text = "近づかないで、触れないで、直視しないで、憐れまないで、世の中には暗闇に独りでいるのが適している生き物がいるのかもしれない。\n彼女の意図ではないが、もし彼女の弱々しい姿、臆病な声、幼い服装に惹かれて彼女の目を見つめると、永遠の静止と静寂に陥るだろう。"
  },
  AwakerStory_11318_Title = {
    Text = "基本資料"
  },
  AwakerStory_11318_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11319_Content = {
    Text = "舞踏団に入って45日目、私はプリンシパルとして舞台に立った。\n熱いライトがスカートに当たり、細かいダイヤモンドが眩い美しさを放つ。光のせいで目が眩むが、割れんばかりの拍手から、私の踊りが宝石よりも輝いていることがわかる。\n回転を続ける中で、世界のすべての塵は純粋な踊りによって洗い流される。踊りの美しさ、芸術の美しさを世界に届けること、それがダンサーとしての私の願いであり、使命なのだ——\n\nでも、舞台の暗い隅に隠れている人たちは何？\n\nあの自由奔放なリゼットが、どうしてあの悪名高い旦那とこそこそ話しているの？\nいつも他のダンサーを見下している天才アンジェリカが、どうしてあの女たらしの前でスカートを摘んでいるの？\n\nなんてみっともない…………なんて穢らわしいの！神様、私のミューズよ、どうすれば暗闇から舞台を守れるのか、どれほどの光があればこの穢れを払えるのか、教えて——"
  },
  AwakerStory_11319_Title = {
    Text = "物語・三"
  },
  AwakerStory_11319_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11320_Content = {
    Text = "幼少期から、カーシアは非常に高い模倣の才能を示していた。\nどんなに精妙なダンスでも、一度見れば再現でき、どんなに複雑な魔術でも、一度教えられれば熟練していた。声、表情、さらには笑顔や気質まで、カーシアは完璧に再現でき、時には本物と見分けがつかないほどだった。もし彼女が異なる出自や職業を持っていたなら、その才能で異なる人生を手に入れられたかもしれない。\n残念ながら、彼女は無名のサーカス団で育った子供だった。サーカスの人々は彼女の才能を金儲けに利用し、サーカス外の人々はただ楽しみを買うだけで、同情を払うことはなかった。\n誰もカーシアの幸せを気にしなかったが、幸運なことに、カーシアも気にしていなかった。彼女は笑う観客、争う団員、写真を見て涙を流す女占い師を見て、ただ剥離した好奇心を感じた。なぜ彼らは舞台の下でそのような表情をするのか？なぜ誰も見ていないときに演技を続けるのか？なぜそれを「感情の表れ」と呼ぶのか？\n何が幸せなのか？何が悲しみなのか？彼女の喉を切り裂いた「支援者」が言った、死に瀕した絶望と恐怖とはどんな感じなのか？\n人間としての彼女はその答えを見つけられなかったが、魔法の子供として、他人から「感情」を集める生物として、彼女はついにかつてない体験を得ることができるかもしれない。\nこうして、彼女は魔法カーニバルを創設し、それを世界中に持ち込んだ。\n人々は楽しみを買いに来て、代償としてすべての欲望を払った。\n「さあ、さあ、私のカーニバルへ！少しの幸せ、少しの悲しみを差し出せば、今世紀で最も素晴らしいパフォーマンスが見られます！」"
  },
  AwakerStory_11320_Title = {
    Text = "物語・三"
  },
  AwakerStory_11320_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11321_Content = {
    Text = "最初は、赤ワインの代わりに葡萄のソーダ水を一杯飲むだけだった。\n誰も気づかないような場所で、ソレールはか弱いふりをして、数人の学生と共に飲んでいた。\n\n次に、小さなお茶会が行われた。\n学生食堂で、ソレールは学生が差し出したマカロンを何度も断り、少しの未練と真心を見せた。\n\n最後に、華麗なサロンが開催され、薔薇が咲き誇った。\n休憩室は花と宝石で飾られ、華やかな薔薇と若い学生が杯を交わし、賓主共に楽しんだ。\n\n新任の守秘者はこれを目撃し、彼女の次のステップが「ミサゴ大学の学長になる」ことではないようにと密かに祈った。"
  },
  AwakerStory_11321_Title = {
    Text = "物語・二"
  },
  AwakerStory_11321_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11322_Content = {
    Text = "灰色の粘り気のある根源の海は空虚で、次元を越える旅行者が語る概念も抽象的な説明と想像に留まっている。\n彼女は自分の目で人間の「憧れの地」を確認したいと思い、人間界の壮大な景色を目の当たりにし、悲喜こもごもの味わいを体験したいと願っていた。\nしかし、それ以上に彼女は特定の人を求めていた、信頼を託せる人を。\n公正な取引は平等を意味し、切り離しを意味し、金品の交換を意味し、余分に支払うことも少しも奪うこともない。しかし、彼女は異なるものを望んでいた、無償の信頼を望んでいた、隔たりを消し、試みを突破し、氷を溶かすために。\n彼女は得て失ったが、最終的には失って得ることになる。"
  },
  AwakerStory_11322_Title = {
    Text = "物語・四"
  },
  AwakerStory_11322_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11323_Content = {
    Text = "融蝕に侵された倫理なき芸術家は、眠れぬ夜に波の音を聞き、迷い込んだ夢の中でこう語った。\n一族が戦火をもたらしたとき、彼女はルルイエに雄大な城壁を築いた。\n天父とその眷属が眠りについたとき、彼女は叙事詩を不朽の聖像に彫りあげた。\n感覚は鈍くなり、体は硬直し、彫刻刀を握ることすらままならない。\n珊瑚のような白い靄はすでに腕まで広がっていたが、彼女は震える両手を見つめ、ふと笑った。命の火はやがて消え、肉体は永遠となる。\n彼女は望み通り海底に沈められた。珊瑚は砕け、黒い融蝕液が海に溶けていく。彼女はついに、長い間失われていたルルイエの古城を見つけ、完全に一体となった。"
  },
  AwakerStory_11323_Title = {
    Text = "物語・四"
  },
  AwakerStory_11323_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11324_Content = {
    Text = "「淫らにふけり、欲望に溺れるものは、永遠の火刑を受け、戒めとせよ…………」\n\n連続して23日間。\nひとりの修道士が彼女の城の門の前に立ち続け、退屈な聖句を唱え続けた。\n\nワンダは命じて、彼を縛って、城の中に引きずり入れた。\n\n修道士は言った。\n「苦しみに心を悩ますことはない。主の御霊があるところに、自由もまたある」\n\n彼女は彼の衣を剥ぎ取った。\n修道士は言った。\n「衣に心を悩ますことはない。野に咲く百合は糸を紡ぐことも、首を垂れることもない」\n\n彼女は彼の手足を切り落とした。\n修道士は言った。\n「血に心を悩ますことはない。血肉ある者は、すべて死にゆくものだ」\n\nワンダは笑った。\n「あんたを血まみれにするだけじゃなく、あたしの奴隷にしてやるよ。生まれ変わっても永遠にね」\n\n「なぜ？」\n修道士は顔を上げた。\n「あなたは同胞を憐れむべきではないかね。私があなたを憐れむように」\n\nワンダは修道士を見つめた。\n彼の目は空のように青かった。\n\n彼女は彼の目をえぐり取った。\n\n修道士は拷問に耐えきれず、ついに死んだ。\n地元の教区は彼女の富と権力を恐れ、誰も彼女を非難しなかった。\n\n死ぬ前に修道士は言った。\n「@2が近い、あなたは…………」\n\n月日が経ち、ワンダはその修道士の顔も名もすでに忘れていた。\nただ、あの青い瞳だけを覚えていた。\n\n@2に呑まれようとしていた夜、ワンダは再び、あの言葉を思い出した。\n\n「@2が近い、あなたは…………」\n\n彼女は朦朧とした意識の中で、修道士の言葉の続きを必死に探ろうとした。\n\nしかし、何ひとつ思い出すことはできなかった。"
  },
  AwakerStory_11324_Title = {
    Text = "物語・四"
  },
  AwakerStory_11324_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11325_Content = {
    Text = "「あなたは栄えある使命を背負う者。主が再びこの世に降臨するための希望なのです」\n 「良い子で、従順でありなさい……そうすれば、主が再び目覚めたとき、誰もが不滅の永遠の王国で生きることができるでしょう」\n\n 誕生すら公にされなかった秘された少女。\n彼女は何らかの理由により、海の祭司の宝物となった。\n誰にも顧みられなかった哀れな赤子は、いつしか神秘の文明と運命を共にする聖女へと変貌した。\n\nその苦行の聖母は、自らの手で彼女を育て上げた。\n幼い頃から供物と崇拝が絶えず寄せられ、彼女が望むものはすべて誰かが両手で差し出してくれた。\n\nもし融蝕現象が起こらず「神」の器が弱体化していなかったなら、彼女はやがて祭司の地位を継ぎ、定められた儀礼の中で信徒たちの上に立つだけの存在であっただろう。\n\nだが、彼女が手に入れたすべてのものは、ある日、彼女に重い代償を求めた。\n——彼女が望んだことのない運命は、すでに抗うことのできない結末を彼女に用意していたのだ。\n\n神の母となり、予言の子を産むこと。\n——聖女の栄光ある犠牲とは、すなわち己の肉体と命を、喜びとともに差し出すことに他ならない。\n\n第二の心臓がその胸の内で鼓動を始めた日、彼女の魂は奔流となり、時の彼方へと消え去る運命にあった。"
  },
  AwakerStory_11325_Title = {
    Text = "物語・三"
  },
  AwakerStory_11325_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11325_UnlockDesc_1 = {
    Text = "メインストーリー通常第5章「嵐の眼」クリア"
  },
  AwakerStory_11326_Content = {
    Text = "洪積暦282年6月、ミスティア協定審査会からの調査申請に基づき、我々は調査員を新レオ地区に派遣した。\n一年前の隕石落下事件以来、その地域の異常な死亡率は高止まりしている。\nさらに、調査員は落下現場でいくつかの変異植物を発見した。機器で測定したところ、これらの植物には隕石由来と思われる高い放射線が含まれていた。\nしかし、隕石クレーター内には地外鉱物は存在しなかった。村民の証言によれば、隕石落下の三日後、一団の白衣の科学者が隕石を切り取り持ち去った。\n（備考：民間科学組織の疑いあり、身元不明）\n審査会と地元政府の調整により、住民は全員退去し、この地は公式に生活禁区と宣言された。\nミサゴ大学物理実験室の計算によれば、この地域の生活禁止は少なくとも八十年間維持する必要がある。"
  },
  AwakerStory_11326_Title = {
    Text = "物語・一"
  },
  AwakerStory_11326_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11327_Content = {
    Text = "対戦相手を選ぶことにおいて、ロータンには独自の基準がある。\nアカデミックな戦士は大抵、読書で頭を悪くし、机上の空論ばかり考えていて、うんざりする。\n軍隊の精鋭はまた、煩雑な規則や道徳礼教に縛られ、つまらない。\n天賦の才を持ち、生まれながらに戦闘本能を持つ奇才だけが、彼女の目に留まる。\n惑星と同じ寿命を持つ巨獣は、戦いへの欲望を抑え、ほとんど敬虔なまでに認めた相手が頂点に達するのを待っていた——彼はどれほど才能のある少年だったのだろう。彼は深海からの力を号令し、その強靭な霊は異界の神々とさえ繋がることができた。いずれ彼は、垂涎の的となる強者に成長するだろう。\nしかし、長い時間が彼女の判断力を鈍らせたのか、今回は混沌の霊が見誤った。様々なことがあり、ロータンはもう誰にも話したくない。\n我々が知っているのは、それ以来、彼女は「向上心のない」「進歩を求めない」人々を鼻で笑うようになったということだけだ。"
  },
  AwakerStory_11327_Title = {
    Text = "物語・三"
  },
  AwakerStory_11327_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11328_Content = {
    Text = "シルバーコア番号：B-005\n出土時間：A.F.1@1年@3月\n出土場所：フランドル低地の田舎、ある無名の古代ローマの墓の廃墟\n詳細記述：シルバーコアの持ち主はルートヴィヒ・プリンという名で、ある招魂事件により地元の宗教裁判所によって火刑に処された。プリンは第九次聖なる東征の戦場でこのシルバーコアを手に入れ、その後ブラバント近くに向かい、「異星からの僕」、「見えない仲間」と共に、「偉大なる名状しがたき者」を召喚するための血まみれの儀式を行ったと主張した。\n記録者：ワード・フィリップス\n——《覚醒体シルバーコア取得報告：B-005》"
  },
  AwakerStory_11328_Title = {
    Text = "物語・一"
  },
  AwakerStory_11328_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11329_Content = {
    Text = "孤独の中で、たとえ一人であっても軍隊のように強くあれ。\n\n24の頭はいつでも少し騒がしい。\n彼女たちは暗闇の中で囁き、くすくす笑い、絶えず24の心を引き裂き、彼女を飲み込みたいと願っている。\n\n街角の下水道から漂う悪臭、工区に舞う綿、古くなった黒パン……\n過去はすでに消え去り、東区の平凡な女工を覚えている人はいない。\n\n彼女はようやく疲れた肉体から抜け出したが、踏み出した先もまた、新たな泥沼だった。"
  },
  AwakerStory_11329_Title = {
    Text = "基本資料"
  },
  AwakerStory_11329_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11330_Content = {
    Text = "この姉妹のうち、一人は生まれるべきではない存在だった。\n観測不可能な琴座の荒星で、ファイントとティンクトは悪口の中で半生を過ごした。\nしかし、誰がその認められない存在なのか？\n姉のファイントは強大だが制御不能で、奪った生命力は川のように流れ去り、残った露を舐めてかろうじて生き延びていた。\n妹のティンクトは美しいが自立が難しく、浮草のように頑固だが根を下ろす場所がなく、姉の周りを回るしかなかった。\nおそらく、彼女たちはお互いに自分が存在すべきでないと思っていたが、ファイントは早くも決断を下した——自らの命を絶つと脅して、彼女は妹を無理やり旅立たせた。\n「行け、ティンクト。私に縛られないで」\n「星間で歌い、最も注目される色になれ」"
  },
  AwakerStory_11330_Title = {
    Text = "物語・三"
  },
  AwakerStory_11330_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11331_Content = {
    Text = "ほとんどの時間、静かに隅の一角を占め、本物の灯台のように、航路を外れた時に皆を正しい道に引き戻し、指針を与える。\n他の深海からの来訪者と同じ部屋にいる時だけ、灯火は彼女の狂気と偏執の影を照らし出す。\n静かで知的な外見の下で、ファロスは意外にも遠洋航海に精通している。誘拐や船員の生贄の疑いがまだ晴れていないため、現在も守秘者の監視下にあるが、ファロスは大学当局の航海関連資料の修訂に多く貢献している。\n——大学当局の協力船舶の船員のフィードバックによると、ファロスの修訂意見は効果的だが、しばしば意図的か無意識にモングル三角海域に航路を向けることがある。\n大学当局はこのことを知ると、ファロスが海洋関連資料に触れることを禁止した。"
  },
  AwakerStory_11331_Title = {
    Text = "物語・二"
  },
  AwakerStory_11331_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11332_Content = {
    Text = "カリグラの御用錬金術師マルクス・アンティスは、多くの生きた人間を犠牲にして「ゴーレム」を錬成した。\n錬成儀式の不完全さのため、毎日大量の人血を飲まねばならない。カリグラの政敵を殺し、彼をローマ皇帝に即位させた。\n暴君カリグラは即位から4年も経たずに暗殺された。彼も怒りと恐怖に駆られた暴徒によって破壊された祭壇の地下に閉じ込められ、千年近くもの間、飢えと渇きに耐えなければならなかった。\n長い年月の中で、彼は鼠の血を吸って生き延び、血脈の奥深くから受け継がれた渇望が彼を狂わせた。\n足りない、全然足りない…………\n@2時期、あるリヴァントの魔術師が彼を見つけ、脱出を助けると約束した。ただし、戦場でレムワヒ人を殺すことが条件だった。\nこんな良い話があるのか？\n彼は簡単に任務を完了したが、小さなハプニングがあった。あまりに興奮して、うっかり戦場の全員を殺し、彼らの血を飲み干してしまったのだ――魔術師と彼自身の仲間の血も含めて。"
  },
  AwakerStory_11332_Title = {
    Text = "物語・三"
  },
  AwakerStory_11332_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11333_Content = {
    Text = "召喚材料G752a号シルバーコア、ロンディニウムの新門監獄遺跡の腐臭漂う泥の中から出土。@2調査員が汚れた牢房の通路で誤って砕けた頭蓋骨を踏んで滑り、それを偶然発見した。\n召喚結果は予想を外れ、黒い融蝕液から現れたのは凶悪な死刑囚や屈強な処刑人ではなく、小柄で狡猾な笑顔の少女だった。"
  },
  AwakerStory_11333_Title = {
    Text = "物語・一"
  },
  AwakerStory_11333_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11334_Content = {
    Text = "@2という名は歴史の中で幾度も書かれている。\n祭司、母、王妃、女王、魔女……この名前にはあまりに多くの異なる肩書が冠されており、歴史家たちは今でも、どの身分が我々が覚醒体として知る彼女を表す代表的な肩書きなのか断定できていない。\n\nタイス本人は過去を共有することを惜しまない——\nそれはすべて彼女であり、完全には彼女ではない。\n\n「高貴な出自を持つ彼女」\nタイスは神殿で最も輝く少女であり、大祭司の子として、白鳥のように優雅で、月光のように温かい。\n\n「樹の前で跪き、祈る彼女」\nタイスは「樹」の最も鮮やかな葉であり、信仰心が彼女に「樹」の恩恵をもたらした。\n\n「全身の血を抜かれた彼女」\n災厄が降りかかり、巨大な建造物が崩れ落ちるとき、古く愚かな文明は最も優れた彼女を選んだ。\n\n「脈管に樹液が流れる彼女」\n万人に崇拝される「樹」は、自らの選択の意志を持っている。\n枝は体内に根を下ろし、信者にほぼ永遠の寿命を与えた。\n\n「しかし、文明を滅ぼしたのは彼女ではない」\nタイスが望むのは、決して世界の滅亡ではなかった。\n\n「ではタイスさん、あなたが望むのは何ですか？」\n「それは——約束したでしょう？私たちの間に実が結ばれたとき、答えがわかるわ」"
  },
  AwakerStory_11334_Title = {
    Text = "物語・三"
  },
  AwakerStory_11334_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11335_Content = {
    Text = "アルバは自分の正義を疑ったことがないわけではないが、その曖昧な日々が彼女に透徹した悟りをもたらした。\n幻想は存在する。\n最初の出発点は決して変わらず、彼女が戦う正義は、侵略者となった組織でも、スローガンを叫ぶ個人でもなく、自分の信念の中に堂々と存在している。\n\nすべての命、すべての純真、すべての夢、抱負、美しい願いは、砲火の前で簡単に灰となる。\n戦争で失われたものは、決して戻ってこない。それは地獄の悪鬼のように、すべての美しさを食い尽くす。\nだからこそ、私欲のために戦争を引き起こした者たちも、灰となる味を味わわなければならない。真の英雄が現れ、大義を胸に、すべての人の明るい未来のために無私に戦うだろう。\nこれが正義の価値だ。\n……\n\n間違っているなら、正せばいい。\nその犠牲を価値あるものにし、この切断された足と幻肢の痛みを価値あるものにしなければならない。\n不幸に破壊されたものがあれば、新しい義肢で取り戻せばいい。\n小さく脆弱なものは、その輝きを永遠に失うことはない。\nすべては本当に血と涙のないユートピアのために。"
  },
  AwakerStory_11335_Title = {
    Text = "物語・四"
  },
  AwakerStory_11335_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11336_Content = {
    Text = "注意が必要だ、彼女の冷静で知的な言葉には人を惑わす魅力がある。異形の頭の下に別の顔があるかどうかを気にする必要はなく、彼女がこの人間のような体に長年の不満を抱いていることを知るだけでいい。\n彼女の灯火は蛾を誘い、迷える者を死に追いやったこともあるが、今ではその中に迷える者の混乱が見え隠れしている。"
  },
  AwakerStory_11336_Title = {
    Text = "基本資料"
  },
  AwakerStory_11336_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11337_Content = {
    Text = "世界を襲った洪水は文明の積み重ねをさらっていった。\nしかし同時に、歴史に積もった塵を洗い流した。\n\n災厄の後、人々はモスルの旧跡から忘れ去られた歴史の一端を垣間見た。\n「樹」は二つの川の合流点に立ち、赤い樹液を流し、文明を潤した。\n「樹」は永遠に滅びず、万古にわたり青々と茂る。\n\n古代史学界は最終的に、「樹」は実体を持たないと認定し、それは古代文明の隠喩であり、精神的象徴であるとした。\n\nそして、誰も見たことのない場所で、種子は世界のあらゆる場所に根を下ろしていく。"
  },
  AwakerStory_11337_Title = {
    Text = "物語・一"
  },
  AwakerStory_11337_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11338_Content = {
    Text = "「ご主人様、鞭打ってください」\n彼女の乾いたはずの目には欲望の炎が燃え、溶けた蝋が涙のように滑り落ちた。\n飢え、苦痛、呪い、汚れ、彼女が求めたすべての屈辱、彼女が与えたすべての享楽が、ついにこの瞬間に彼女自身に降りかかる。"
  },
  AwakerStory_11338_Title = {
    Text = "物語・四"
  },
  AwakerStory_11338_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11339_Content = {
    Text = "彼女は星々の間の歌姫であり、輝く星屑。\n彼女は金の鳥籠の中の囚われた鳥であり、捨てられた蓄音機。\n荒れた星が崩壊する宇宙で消滅する時、彼女は生の希望を強いられ、無主の深宇宙で故郷を恋しがる放浪者、永遠に歌う探求者となった。\n「姉さま……私たちの中で、自由に歩けるのは私だけど、ずっと支えてくれたのはあなたなのです」"
  },
  AwakerStory_11339_Title = {
    Text = "基本資料"
  },
  AwakerStory_11339_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11340_Content = {
    Text = "この意志が投影する身体は、早逝した少女の姿で留まっている。腐敗した衣の裾、蒼白な肌、過去の陰影を漂わせる瞳が、病と苦難に縛られた過去を無言で語っている。"
  },
  AwakerStory_11340_Title = {
    Text = "基本資料"
  },
  AwakerStory_11340_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11341_Content = {
    Text = "@2事件後、カエクスは我々と和解し、覚醒体系の編外メンバーとなった。彼が知っている@1の知識は断片的だが、喜んでそれを示し共有する。\n彼はトゥルー、ミリアム、ゴリアテの前では謙虚だが、他の種族——特に人間には陰鬱で敵対的な目を向ける。記録を読んだ研究者たちは彼の偏執を理解するが、一部の気性の荒い覚醒体はそれを許容できない。この緊張した雰囲気は通常、シルヴィアが出てきて解消する必要があり、カエクスとシルヴィアの間には徐々に信頼関係が築かれた。\nシルヴィアの指導のもと、カエクスは「高等種族の寛容心」に覚醒し、他人の挑発を避けるようになった。\n「彼はよく人間の母親を温かく思い出す。母親は子供が世界を認識する基準と言われており、本質的に彼の人間への敵意は後天的に形成されたものだ。だから、ただ少しの指導と関心が欠けていただけなのだ」とシルヴィアは心理カウンセリングの記録に書いた。"
  },
  AwakerStory_11341_Title = {
    Text = "物語・二"
  },
  AwakerStory_11341_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11342_Content = {
    Text = "覚醒体資料管理者は何度も彼女のファイルを学生管理部に送ったが、彼女自身が何度もそれを送り返し、書類の山に埋もれてしまった。\n「ここに置いておけばいい、いずれ持ってくる日が来るから」\n彼女の口調はいつも通り穏やかだが、目は揺れていた。\nこの穏やかさの下に、どんな大きな感情が隠されているのだろうか？"
  },
  AwakerStory_11342_Title = {
    Text = "基本資料"
  },
  AwakerStory_11342_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11343_Content = {
    Text = "「調査任務が初めてなら、オジールと一緒に行くといいよ！」\n新人調査員の不安に対し、経験豊富な先輩たちはいつもこうアドバイスする。オジールが教師や学生にどれほど人気があるかがわかるだろう。\n彼の古風な性格が、ときおり小さな騒動を引き起こすこともあるが、調査員とオジールは互いに支え合い、最も調和のとれたリズムを築くことができる。近年では、新人調査員の初任務にオジールを同行させることが、校内の共通認識となっている。「オジールは女性調査員にマントを用意する」「オジールは太ももを見ると赤面する」といった噂も学生の間で広まっている。\n「死の騎士」という呼び名は、信頼と温かさに包まれ、次第に忘れ去られていった。ただ、少年の心には小さな棘が残っている。"
  },
  AwakerStory_11343_Title = {
    Text = "物語・二"
  },
  AwakerStory_11343_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11344_Content = {
    Text = "十二年前のある朝、ロンディニウム東区。ワークハウスの門前にスカーフでしっかり包まれた女の赤ん坊が現れた。これは危険がいっぱいの東区では珍しくないことだったが、若いサラを怒らせたのは、寒い冬に残酷な捨て子が赤ん坊の口と鼻までスカーフで覆っていたことだった。その赤ん坊が泣きもせず騒ぎもしなかったため、サラはその澄んだ目が瞬きしたのを見なければ、彼女が死んでいると思ったかもしれない。\nサラがまた一人の良い子の「姉」になると思った矢先、当時の院長はその子を1スタールの価格で東区市場の仕立て屋に送った。\n「その子を養えない。仕立て屋の娘になれば、多少苦労するだろうが、少なくとも手に職をつけられる」\n生まれてまだ二ヶ月の子に、何の「手に職」だというのか？\nサラは空っぽの胃を感じながら、院長の決定に反論しなかった。"
  },
  AwakerStory_11344_Title = {
    Text = "物語・三"
  },
  AwakerStory_11344_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11345_Content = {
    Text = "A. F. 2@1年、シディアートサロン展。\n「彼女を家に連れて帰る！」襲撃者は彫刻家オーギュストの遺作「無名の珊瑚の女」をハンマーで打ちながら叫んだ。彼はすぐに見物人に制止された。驚くべきことに、その錯乱した様子の老人こそ、長らく姿を消していたオーギュスト本人であることが判明した。\nこの出来事を機に、「無名の珊瑚の女」をめぐる憶測や噂が一気に広まった。\n人々は言った——その彫刻のモデルは、オーギュストの弟子のサンガーという女性で、オーギュストの最も優れた作品はすべてサンガーの手によるものであり、彼は恥ずべき盗作者だと。\n人々は言った——サンガーは名門の出身で、父は著名な作家で、外交官の弟がいる。彼女は彫刻を学ぶために家族と絶縁し、一人でパリに向かい、死ぬまで貧困にあえいでいたと。\n人々は言った——サンガーは奇病に侵され、黒い粘液が体内を流れており、彫刻をするたびに身体の一部が珊瑚に変わっていった。「無名の珊瑚の女」とは、彼女が珊瑚化していった姿そのもので、そもそも彫刻ではないのだと。\n人々はさらに言った…………\n師弟、知己、狂気。人々が去った後、展示室には言葉で形作られた珊瑚の女だけが残った。月光に照らされながら、彼女はそっと瞬きし、待っていた――帰る、その時を。"
  },
  AwakerStory_11345_Title = {
    Text = "物語・三"
  },
  AwakerStory_11345_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11346_Content = {
    Text = "その恐ろしい疫病が迫ったとき、ワンダは城の大門を溶接して封鎖するよう命じ、外界とのあらゆる繋がりを断ち切った。\n——そして彼女は、享楽と狂騒に満ちた隔絶された生活を始めた。\n\nここには冗談を言う道化師がいる。\n即興で詩を吟じる詩人もいる。\n演奏する楽師もいる。\n美食と酒すらもある。\n\nすべての楽しみと平和は城内にあり、城外は@2に覆われた闇の世界であった。\n\nやがて、城壁の外が完全な死の地と化したとき、ワンダは数百人の従者のために、きわめて豪奢な仮面舞踏会を催した。\n\nそれは三昼夜にわたる、退廃と狂気の宴であった。\n三日目の真夜中、鐘が鳴り響いた瞬間、客の中には完全に発狂する者、そして黒い粘液と化して崩れ落ちる者が現れた。\n\nワンダの顔は陶器のようにひび割れ、仮面の隙間から黒い@2が流れ出た。\n\n恐怖に震えながら彼女の傍に縋る従者たちを、ワンダはただ静かに見つめていた。\nそして鞭を一閃し、@2で狂い果てた者たちを処分させ、残った者たちには飲酒と演奏を続けさせ、止めさせなかった。\n\n奇怪で幻想的な舞踏会は四日目の夜明けに終わり、豪華な大広間は黒い@2の液体と真紅の血で満たされていた。\n\nこの城で何が起こったのか、誰も知る者はいない。"
  },
  AwakerStory_11346_Title = {
    Text = "物語・三"
  },
  AwakerStory_11346_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11347_Content = {
    Text = "《石の災厄事件記録Ⅲ》によれば、守秘者はロンディニウムのワークハウスからこのシルバーコアを持ち帰った。シルバーコアと一緒に、小さなパッチだらけの布製のクマのぬいぐるみも持ち帰った。\nこのシルバーコアは約2.1グラムで、細く滑らかで涙の形をしている。シルバーコアに直接触れた実験者は硬直状態に陥り、他の人に呼び起こされるまでシルバーコアに触れた姿勢を保つ。誤って触れないように、研究者のドールはこのシルバーコアを密閉されたガラス球に保存し、布製のクマのぬいぐるみの目を交換した。\n「毎日泣いているように見える」"
  },
  AwakerStory_11347_Title = {
    Text = "物語・一"
  },
  AwakerStory_11347_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11347_UnlockDesc_1 = {
    Text = "メインストーリー通常第1章「東区の秘め事」クリア"
  },
  AwakerStory_11348_Content = {
    Text = "鉄錆の匂いが空気中に広がる。\nそれは……「食べ物」の匂い。\n少女はゆっくりと目を開けた。長期間、大量の鎮静剤を注射されていたため、彼女の脳は混沌としていた。目の前には喉を噛み切られたビーグル犬が横たわっていた。名前は……バンビ？ポピー？\n少女が思い出に浸ろうとしたその時、腹部に激痛が走る——彼女は「食べ物」に襲われた。\n今、縛られた浮浪者は震える手で大声で叫んでいるようだった。\n「吸血鬼！化け物……化け物！！」\nしかし、少女は気にせず、腹の血をぼんやりと撫でていた。\n大量の温かい血が、滑らかなシルクのように、傷口から溢れ出し、広がっていく。\n彼女はまだ痛みを感じ、血を流すことができる。\n少女は声を出さずに涙を流した。彼女は血まみれの細い手を伸ばし、「獲物」の頬を優しく撫でた。\n「次は、もっと強くお願いできる？」"
  },
  AwakerStory_11348_Title = {
    Text = "物語・四"
  },
  AwakerStory_11348_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11349_Content = {
    Text = "多くの子供の中から選ばれ、王座に推された時、トゥルーはまだその青金石の玉座よりも小さかった。\nしかし、彼の無頓着さや長い眠りに対して誰も口を挟むことはできなかった——すべての人が知っていたのは、これが王が神託を聞いている証拠だということだった。\n賢明な幼王が下す決断は必ず問題を解決し、予言したことは必ず実現する。\nトゥルーはこのような生活を受け入れた。「神」の夢に入り、理解不能な存在と会い、神託で国を治め、再び眠りに落ちる…………\nこの文明の運営は神の意志によって決定されている。流れに乗り、運に従い、自分はこの唯一無二の「伝言者」としての役割を果たせば十分だった。\nしかし、トゥルーには唯一口に出せなかった予言があった。国は洪水によって滅び、文明は海底に葬られる。\nすべてを知っているからこそ、破滅が避けられないことを知っていた——しかし、少なくとも最後の時まで、彼らを恐怖と不安の中で生きさせたくはなかった。\nこれは彼が国王として、「神の代行者」としてではなく、下した決断だった。"
  },
  AwakerStory_11349_Title = {
    Text = "物語・三"
  },
  AwakerStory_11349_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11350_Content = {
    Text = "覚醒した後、誕妄・マーフィーはよく逃亡に関する夢を見るようになった。その夢の最後、彼女は「母」の短剣を手に、白く輝く月明かりの下で自らの胸を貫いた。その後夢は突然終わり、目を開けた瞬間、ちょうどベッドの前にある象牙の彫像と目が合った。\n\n誕妄・マーフィーのミサゴ内での行動は、彼女の「養育者」の若い頃の姿を思わせる。彼女は終日喪服をまとい、気軽に人と笑い話をすることもなく、話題がたまたまスイーツへの好みに流れたときだけ、その無垢な聖母の仮面に一筋の亀裂が走る。\n（記録員の注：次回彼女がケーキを味わいたいと思ったときは、その場で申し出てほしい。全員のアフタヌーンティーが終わった後に、部屋まで届けるよう要求するメモを残すのではなく。）\n\n彼女は蹈海者からの覚醒体とは距離を置く習慣がある。別の世界の自分とは異なり、彼女は関係者との接触を意図的に避けることはないが、顔に凍りついた冷たい表情と敵意を含んだ皮肉が、いつの間にか面倒を避けたい者たちを遠ざけてしまう。"
  },
  AwakerStory_11350_Title = {
    Text = "物語・二"
  },
  AwakerStory_11350_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11351_Content = {
    Text = "25歳のとき、ライカーは密室殺人事件の捜査中に奇妙な容疑者に出会った。\n絶対的な証拠を掴んだ後、警察署で手錠をかけられていた容疑者が、手錠はそのままで、謎の失踪を遂げた。当然、これは当直警官の責任であり、ライカーは報酬を受け取った。\nライカーはその報酬を持って海外に渡り、休暇を過ごし、露店で逃亡中の容疑者に出会った。容疑者は賭場を開いており、ライカーを見ても慌てず、彼を賭けに誘い、ライカーが勝てば大人しく捕まると約束した。\n\nライカーは一度も勝てなかった。\n\n彼はパイプを失い、ネクタイを失い、帽子を失い、コートを失った。\n全裸になったとき、容疑者はすべての服を返し、これらの賭けは小さすぎると言った。ライカーは躊躇なく容疑者が何を賭けたいのかを尋ね、相手が腕を賭けることを提案すると、快く応じた。\n\n何度か賭けを追加した後、相手はリボルバーを取り出した。生死のロシアンルーレットを前に、ライカーは躊躇なく銃を手に取り、自分のこめかみに向けた。\n一発の銃声が響き、ライカーは倒れた。容疑者は彼の死霊を呼び戻し、その無知を嘲笑おうとした。しかしライカーの最初の言葉は「次は何を賭ける？」だった。\n\n彼の傲慢さはついに悪魔の興味を引いた。「N@2@3」という真名を持つ容疑者は、この賭けを続けることに決めた。\n\n「N」は三つのシルクハットを取り出し、体を取り戻すための「最良の選択」をさせた。\nライカーは帽子を選び、「N」は空っぽのシルクハットを開け、選択を変えるか尋ねた。ライカーは首を振った。\n\n–確率を知らないのか？\n–自分の運を信じているだけだ。\n\n「N」は三つ目のシルクハットを開けたが、中は同じく空っぽだった。最後にライカーの帽子を開けると、中には奇妙な黒い霧があった。黒い霧はライカーに襲いかかり、奇妙な獣の四肢に変わった。「N」は化身の体で、彼がすでに賭けていた体を置き換えた。\n\n–獣のような嗅覚を持つ人間には、この化身がぴったりだろう？だからこれが「最良の選択」だ！"
  },
  AwakerStory_11351_Title = {
    Text = "物語・三"
  },
  AwakerStory_11351_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11352_Content = {
    Text = "ここは約束の地、ここは芸術の理想郷、ここは至高の楽園——踊りはダンサーの帰る場所であり、永遠に純粋であるべきなの。\n私が燃えている限り、あの穢れは私たちの聖堂を汚せない……これが私の使命であり、希望なの……どうか燃えさせて、みんなのために、あの穢れを焼き尽くすから。"
  },
  AwakerStory_11352_Title = {
    Text = "物語・四"
  },
  AwakerStory_11352_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11353_Content = {
    Text = "シー……慌てないで、あれは湿った地下室で鼠が腐る音。最も暗い深淵の底から、猩々の欲望が生まれる。囚われた魂は血を渇望し、盲人が光を求め、淫乱者が愛欲に溺れるように、血を求める。彼女を喜ばせる方法は簡単だ。思う存分、彼女を罵り、辱めてあげて。"
  },
  AwakerStory_11353_Title = {
    Text = "基本資料"
  },
  AwakerStory_11353_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11354_Content = {
    Text = "これまで、私たちが知る最古の人類文明は二河流域に起源を持ち、多くの確固たる考古学的資料がそれを証明している。\nしかし、人類は既知のものに満足しない。広大な暗黒の海に直面すると、人々は未知の海に向かって帆を上げることをやめない。\nおそらく私たちは何度も警告や示唆を受けてきた。神智学者たちはこうした仮説を提唱している。宇宙は畏敬すべき循環であり、今の私たちの世界と人類自身はその一時的な一環に過ぎない。\n多くの事物が無言で循環の中で消え去り、証拠を残さない——これは幸いなことである。ある力はあまりにも古く極端であり、残存する遺跡でさえ、私たちの時代に計り知れない影響を与えることができる。\n——例えば今回、「警戒号」の船員が南洋の海底で偶然発見したものは、少なくとも人類の史前文明の認識を数万年前にまで広げた。\nこれにより、国家、君主、特殊な信仰を持つ文明が存在し、世界的な大洪水で滅び、長く海底に眠っていたことがわかった。\nもしミスティア協定審査会が封鎖作業で協力していなければ、人類の歴史は書き換えられていたかもしれない——しかし今の世界は、転覆に直面する準備ができていない。"
  },
  AwakerStory_11354_Title = {
    Text = "物語・一"
  },
  AwakerStory_11354_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11355_Content = {
    Text = "カーシアは帽子の中に手を入れるが、何もない。扉の中に手を入れるが、何もない。胸の中に手を入れるが、何もない。集めた喜怒哀楽、驚き、恐怖、憎しみ、開演前のざわめき、転換期の歓声、名場面での口笛、終演時の拍手、退場時の冷たさ、すべてがこの空っぽの胸から抜け落ちていった。カーシアは鏡に向かって観客の表情を真似る。目尻のシワ、筋肉の動き、唇の角度、どれもそっくりなのに、そこに真意は感じられない。もし感じることができたなら、模倣を超えることができたなら、彼らの一員になれたなら……あるいは、誰かがそばにいてくれたなら……そうすれば、この胸の「空」を埋めることができるのに。"
  },
  AwakerStory_11355_Title = {
    Text = "物語・四"
  },
  AwakerStory_11355_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11356_Content = {
    Text = "旅行情報：\n好奇心そそる歴史探訪！カンブリア城・豪華7日間ツアー\n\n旅行日程：\nA.F.3@2年\n6月18日～6月25日\nガイド：\nトーマス・@2@1\n\n旅行概要：\nさあ、300年前に最も恐れられた幽霊城——カンブリア城の神秘のヴェールを一緒に剥がしましょう！\n\n古い書籍や、無声映画の「妖艶な女領主と25人の従者」の艶めかしい伝説だけでは、もう物足りなくはありませんか？\nどれもこれもお決まりで新鮮味がありません！\n\nミサゴ大学のとある匿名専門家によると、最近、この地域でまた新たな発見がありました！\n@2@1は一面の茨棘で覆われていたのです……\n\nいますぐ@2@1@1まで電話を！\nこの旅はきっと、一生忘れられない、冷や汗ものの体験となるでしょう！\n\n——《ウースター旅行団体失踪事件・事件概要：証拠S-145》より抜粋"
  },
  AwakerStory_11356_Title = {
    Text = "物語・一"
  },
  AwakerStory_11356_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11357_Content = {
    Text = "融蝕研究の最前線に立つ者として、ドールは常に背後の消滅の足音が追いかけてくることを知っていた。ましてや、融蝕されることについては彼女はすでに熟知していた。\n真実を追求し続け、失敗し続ける中で、ドールは現在の人間の肉体が自然に盲目的である可能性があることを徐々に認識した。現実に属する人はどんなに努力しても彼岸の景色を見ることはできない。\nでは、黒い粘液が身体を消解する際に、同時に魂を真実の彼岸へと導くのだろうか？\n彼女は古代の石板に刻まれた箴言と静かに向き合い、融蝕が脳缶を侵食するのを許した。どんな道の終わりが待っていようとも、彼女はもう戻れない。\n幸運であり不幸でもあることに、彼女は自身の存在を賭けて、ついに世界の内側に入る機会を得た。そして一瞬で、真実、虚無、破壊が同時に彼女を飲み込んだ。\n一瞬のまばたきで、彼女は宇宙のすべてを目撃し、融蝕の本質、世界の真実、彼女が一生求めてきたものがここにすべてあった。\nすべての科学の信仰と理性の堅持は泡と化し、鉄のように堅固だった精神の壁が突然崩壊した。\nドールという名の天才はすでに消え、今ここに立っているのは、虚無に占領されたただの生骸だ。"
  },
  AwakerStory_11357_Title = {
    Text = "物語・三"
  },
  AwakerStory_11357_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11358_Content = {
    Text = "「A. F. 3@2年、密大海洋生態グループが南部海域で種の観察を行った際、形態が奇妙な珊瑚礁を発見…………」\n「このサンプルは特異な性質を持ち、地球上の既知の元素とは異なる。水中では柔らかく、陸に上がるとすぐに乾燥して硬化する。生物学系と天文学系の共同研究によれば、未知の地外物質である可能性が高い…………」\n\n「A. F. 3@1年、覚醒体コードネームサンガー。\nこの覚醒体は覚醒してから彫刻行為を続けている。その奇妙な曲面と線で知られる芸術スタイルは、どの流派にも分類できない。観覧者に精神的な衝撃を与える以外、融蝕研究にはほとんど役立たない」"
  },
  AwakerStory_11358_Title = {
    Text = "物語・一"
  },
  AwakerStory_11358_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11359_Content = {
    Text = "彼は死から生還し、変貌を遂げた。彼は巨刃の鋭さを抑え、使徒の仮面を被った。\n神の御業が訪れるとき、彼は本能的に畏敬の念を抱いたが、決して神を恐れず、真の信仰を理解することもなかった。\n巨人は人の下にあるべきではなく、戦士は頭を垂れて臣下になることはない。\n古来より、彼の戦争は終わらず、征服の欲望と与えられた力が彼の血に深く刻まれている。いつか彼が死ぬかもしれないし、いつか彼がすべてを支配するかもしれない。"
  },
  AwakerStory_11359_Title = {
    Text = "物語・四"
  },
  AwakerStory_11359_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11360_Content = {
    Text = "お前もこんな夢を見たことがあるんじゃないか？\n突然、多額の遺産を相続したり、突然、大きな力を手に入れたり……かつて僕たちを蔑み、傷つけてきた者たちを、すべて踏みつけにできるほどの力を得るような夢。\nそして夢から覚めた瞬間、終わりのない現実を前にして、さらに深い絶望へと落ちていくんだ。\nでも、僕の夢は現実だった。\n僕の運命にはそれが訪れたんだ。\n\nわかるか？\n弱者なのは、お前たちのほうだ。\n\n肉体の脆弱さと魂の弱さが高貴な血統を支えられないだって？\nいや、そんなことはない。\nなぜならアウンという姓こそ、私たち@2の誇りであり象徴だからだ。\n血と姓を授かった僕は、もはや誰かに侮辱される怪物じゃない。\n高貴な血を受け継ぐ@1なんだ。\n\nだから……お願いだ……\nそんな、息が詰まるような目で、僕を見ないでくれ……"
  },
  AwakerStory_11360_Title = {
    Text = "物語・四"
  },
  AwakerStory_11360_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11361_Content = {
    Text = "ハンナ：アルバさん、キミがミサゴ大学に来てから結構経つよね。学生たちの間でもスゴイ人気だし、たーっくさんの女の子たちがボクにラブレターを渡してくるんだよ。読みあげようか？\nアルバ：それは本当に…………ええと、皆さんに感謝する…………しかし俺は、ええと、今日は一日の流れを話すために来たのでは？\nハンナ：訓練官にこんな可愛い一面があるなんてね！インタビューが掲載されたら、嫉妬した女の子たちに囲まれないように校外に隠れないと！さて、本題に戻ろう。魅力的な訓練官の一日を読者に教えてもらえる？\nアルバ：恐らく皆さんをがっかりさせるだろうが、俺の一日はごく普通だ。毎朝4時に起きて運動し、この足を動きに慣れさせるところから始まる。\n6時には食堂へ。覚醒体として食事は必要ないが、これは…………習慣のようなものだ。\n午前8時から12時まで、調査員たちに戦闘技術を指導。たまに守秘者に追加訓練を行うこともある。午後の訓練時間はカリキュラムに応じて調整され、ときには1時から、ときには3時から始まる。\n毎週、ナウティラのところに行って義肢の調整を手伝ってもらっている。彼女は物忘れが激しいが、仕事は非常に上手い。彼女が検査を終えるたびに痛みがかなり軽減されるんだ。\nハンナ：普段はどんなことを楽しんでるの？\nアルバ：楽しみか…………それは俺にとってまだ馴染みのない概念だな。でも最近、オレッタたちと一緒に海で遊んでいる。純粋な子供たちと一緒にいると、とてもリラックスできるんだ。泳ぎは体力づくりにもなるし、新兵だった頃を思いだす。俺の教官が——\nハンナ：さて、今日のコラムはここまでです！アルバさんの過去を知りたい方は、次号の『いつものミサゴシェア』をお楽しみに！\n——抜粋自『ミサゴ日報』特別インタビューコラム、『いつものミサゴシェア』"
  },
  AwakerStory_11361_Title = {
    Text = "物語・二"
  },
  AwakerStory_11361_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11362_Content = {
    Text = "すべての真実が明らかになるまで、誰もドールが一連の衝撃的な事件の真犯人だとは疑わなかった。\n結局、彼女はミサゴと融蝕の最前線で常に柱のような存在であり、すべての人の心の中で揺るぎない支えだった。\n無数の人間の夜空の星が融蝕によって消え去る中、この揺るぎない人間の灯火もついに残酷に消え、影の中で暗闇と同源の推進者となった。\n竜巻、洪水、大地震…………効率の悪い殺人は明らかに天才の計画には合わず、彼女はかつて誇りにしていたシルバーコアテクノロジーを「世界を動かす」致命的な武器に改造し、ミサゴの見えない場所で次々と破壊の贈り物を送った。\n最終的に彼女が捕らえられたとき、人形の体は腐蝕した脳によって精密に制御されることができず、かつて静かだった顔には歪んだ奇妙な表情が浮かび、対面するだけで狂気の深淵に落ちるかのようだった。\nすべての人が彼女の時折の曖昧なつぶやきを無視することを選んだが、それが本当に世界の真実を明かしていた可能性があったとしても。\nただ彼女の経験が再び証明したのは、人間は結局意味を必要として生きる生物であるということだ。"
  },
  AwakerStory_11362_Title = {
    Text = "物語・一"
  },
  AwakerStory_11362_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11363_Content = {
    Text = "ダフォダイルは高額で自分をミサゴ大学のシルバーコア研究室に売り渡した。\nその前に、研究室の責任者ドールはダフォダイルだけが行える一方通行の通信に対して何度も不満を表明していた。\nしかし、その「一方通行の通信」がどれほど危険な取引によって成り立っているかを知っているのは、ダフォダイルとある故人のミサゴ大学の高官だけだった。"
  },
  AwakerStory_11363_Title = {
    Text = "物語・一"
  },
  AwakerStory_11363_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11364_Content = {
    Text = "高慢で、わがままで、自己中心的……彼女と接触した多くの人々は、彼女の性格にこのような評価を残すだろう。彼女は以前の生活環境で、常に周囲から大切にされていたようで、それが彼女のわがままな性格を育んだのかもしれない。\n「ねえ！何を見ているの？三回呼んだら返事をしなさいって言ったでしょ！」\n——記録を読むときも十分注意が必要だ。"
  },
  AwakerStory_11364_Title = {
    Text = "基本資料"
  },
  AwakerStory_11364_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11365_Content = {
    Text = "港町の街角に小さな交換商店があり、店主は神秘的な事件に対処する「有能な人物」だった。\n洪水の後、まだダフォダイルと呼ばれていなかった彼女はサンペドロの近くに現れる。ほどなくして、この港町で「首の神秘的な失踪」の被害者が出始めた。\n店主は調査の末、彼女を見つけ、全力で彼女を制圧した後、彼女と交換を行った。店主は、自分の命が終わった後に首を持っていくことを許可する代わりに、それまで店主の助手として働き、自由に狩りをしないことを約束した。\nこうして千年の放浪を経た彼女は、店主と共に行動し、共に生活を始めた。\n彼女は数多くの首の中でその持ち主の生前の記憶を再体験し、喜びや憎しみを感じたが、この荒唐無稽な楽しみは長すぎる命を消耗し、漂流から生まれる孤独を隠すだけだった。\n店主との共に過ごす中で、彼女は初めて人間と本当の友情を築いた。彼女は無限の首という偽りの慰めではなく、人間との真の交流こそが長い孤独と空虚を解決することを発見した。\nしかし、この短い幸せは十年も続かず、調査を続けていた店主は突然亡くなった。\n彼女は店主の首を切り取り、彼女の外見と商店、そして名前を受け継ぎ、「ダフォダイル」となった。\nそれ以来、ダフォダイルは小さな交換商店を巡る旅に出た。彼女は助けを求める人々から首を交換として受け取り、嗜好品として集め続けた。\nしかし、彼女はもう首を自由に狩ることはなかった。\nもう二度と。"
  },
  AwakerStory_11365_Title = {
    Text = "物語・三"
  },
  AwakerStory_11365_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11366_Content = {
    Text = "巣に戻る、故郷に帰る、家に帰る、どの人間の言葉で彼女の願望を表現しても構わない。たとえ覚醒体の姿で現世に現れても、彼女は心を引き裂く国を忘れることができない。\n海底火山の呼吸はもはや耳元で低く鳴らず、深海の幻夢もすでにぼやけた映像であるが、永遠の王国への帰還の執念は日に日に狂熱を増している。\n彼女の一時的な従順に注意しなければならない、王の御座の下に戻るために、彼女は何でも犠牲にする覚悟がある。"
  },
  AwakerStory_11366_Title = {
    Text = "物語・四"
  },
  AwakerStory_11366_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11367_Content = {
    Text = "ドールはミサゴ大学、さらには学界全体にとって欠かせない人物だ。\n大学が管理する覚醒体の中で、ドールはノース指数が最も安定しているわけでも、戦闘能力が最も高いわけでもないが、彼女は最も冷静で理性的な存在である。\nかつて人間だった覚醒体の中には、「死んで生き返る」初期に迷い、恐怖、狂躁などの感情を伴うことが多い。しかし、ドールはそのような「陣痛期」の影響を受けていないようだ。\n覚醒された翌日には再び実験室に戻り、一年以内に外域の知識と人類の知恵を集大成した技術マニュアルを編纂した。\n現在のドールは、半分の時間を「シルバーコアテクノロジー」の革新に、半分の時間を「愚かな学生の後始末」に費やしている。\n——ちなみに、高次元の存在の影響を受けて、ドールはその《技術マニュアル》を未知の言語で書いており、翻訳作業はドールの余暇時間に秩序立てて進行中だ。"
  },
  AwakerStory_11367_Title = {
    Text = "物語・一"
  },
  AwakerStory_11367_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11368_Content = {
    Text = "「神の娘であり、同時に神を宿す者。」\nこれが彼女が権威を確認する方法であり、衆目を集める栄誉を保つことでのみ、彼女は危うい均衡を維持できる。偽善であって何が悪い？虚妄であって何が問題か？誰もが「今この瞬間」を生きているのではないか？\nマーフィーは醜い聖胎を包んだ産着を抱きながら、神の意志を代行し、次々と嘘をついた。\n「祂はすでに降臨された。」\n「神の国は必ず浮上する。」\n「次の星辰が正位につく時をお待ちください。」\n偽善的な他者が幻想を作り上げるままにするくらいなら、この牢獄を自分の手で自分が満足する形に飾り立てた方がましだ。彼女が渇望する「母」「仲間」「僕」がそばにいる限り、表面だけの卑屈な従順であれ、口先だけの神秘めかしであれ、彼女は喜んで受け入れ、甘んじて享受する。\n「私はマーフィー、神明を産んだ王女よ。レムリアについて、蹈海者の悲願について…………詮索しなくていい、私に考えがある。」"
  },
  AwakerStory_11368_Title = {
    Text = "物語・四"
  },
  AwakerStory_11368_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11368_UnlockDesc_1 = {
    Text = "クリアスターダストの章普通第4章「楽園」"
  },
  AwakerStory_11369_Content = {
    Text = "A.F.3@2年4月2日、アシュドッド地区の神殿遺跡が破壊された。\n大学を出た唯一の人間として、私は観光客でありながら、地区長官に遺跡の建築学的評価への参加を依頼された。ふふ、私の「大学」が実はそういうものではないことは、絶対に知られてはいけない。\n3日の午後、私は神殿の中心に入った。古代セム族はこの神殿を祭祀の場としており、ここにはすでに失われた異教信仰が盛んに行われていた。\nしかし私の前に現れたのは、誰もが見間違えることのない彫刻だった。私ははっきりと知っている。あの彫刻のひだは、本来なら斜めの麻布の模様であるべきだ。\n像の両手は折れ、胴体と首は離れ、下肢は敷居に砕かれ、全身がナメクジに這われたように粘液まみれだった。私は奇妙な引っかき傷と、巨大な水かきのある足跡に気づいた。\n異教信仰はまだこの地域に伝わっているかもしれないが、正式な調査を行う必要はない。私はアシュドッド地区での滞在を延長するつもりだ。\n——フィン@1・@2ソン《ペリシテ五都市遺跡巡礼》より"
  },
  AwakerStory_11369_Title = {
    Text = "物語・一"
  },
  AwakerStory_11369_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11370_Content = {
    Text = "学生たちの間では、図書館の地下、墓地、レーアから離れることが共通の認識となっていた。\n青白く弱々しい少女は、人を怒らせることに熱心で、相手の怒りを楽しむように味わい、エデンの園の蛇のように、絶妙なタイミングで秘められた餌を投げかける。「私を傷つけて…………さあ…………」\nほとんどの場合、彼女は白い目や疑問、呪いを受ける。しかし一度だけ、彼女はついに望みを叶えた——ユウハシュは躊躇うことなく彼女を殴り、彼女の歯を一本抜いた。彼は他人にまったく興味を持たない男で、彼にとってはすべてが当然のことだった。\n戦士が颯爽と去っていく姿を見て、レーアは満足そうに笑った。柔らかな朝の光が彼女に降り注ぎ、また晴れた一日が始まる。\n彼女にはまだたくさんの歯がある。全部抜いて…………誰でもいいから、全部抜いて…………"
  },
  AwakerStory_11370_Title = {
    Text = "物語・二"
  },
  AwakerStory_11370_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11371_Content = {
    Text = "「…………コンスタン連邦南部のボンドスには「祝福の司教」の伝説が伝わっている。洪積暦以前、「祝福の司教」は中央教廷の出身で、敬虔で善良であり、地元で唯一の孤児院を一から建て、疫病が猛威を振るう中、行き場のない多くの患者や難民を受け入れた。\n疫病は凶暴で、人々は皆苦しんでいた。代行者は昼夜を問わず祈り続け、ついに父なる神の恩寵を受けて生命の石板を手に入れ、自らの血肉を捧げ、この世に奇跡を起こした。彼は死者を蘇らせ、重病者を回復させた。しかし、この慈悲深い代行者は悪魔に陥れられ、最終的に火刑で死んだ。\n偶然にも、伝説の「祝福の司教」が活躍した同じ時期に、元@2中部の@1（現コンスタン連邦南部ボンドス近郊）に、特別な「血の異端者」が存在していた。「大陸審判所異端審判実録」の記録によると、この異端者は悪魔の印が刻まれた石板を手に持ち、血肉を供物として、月が遮られる夜に邪悪な儀式を行い自らを養ったという。この異端者は洪積暦より107年前に審判所に捕らえられ、異端者は翻然と悟り、唯一の父なる神に虔誠に懺悔し、火刑に処された。\n同じ時代、同じ地域で、同様に石板と祭祀を用いて秘術を行使する――否定できないことに、「祝福の司教」と「血の異端者」の間には多くの共通点がある。審判所が非常に主観的で、異端者と見なした人物に対して汚名を着せる可能性が高いことを考慮すると、筆者は伝説の「祝福の司教」が実在し、さらには審判所の記録にある「血の異端者」その人である可能性すら疑わざるを得ない…………」\n――「我々の神々：コンスタン連邦南部の宗教と民間信仰」より抜粋\n"
  },
  AwakerStory_11371_Title = {
    Text = "物語・三"
  },
  AwakerStory_11371_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11372_Content = {
    Text = "「母親」の存在を渇望し、「主人」の命令に従う少女。\n世界は彼女の名前を忘れ、巨大な黒い泥の目玉の中で百合のように咲く脆い白い影を「Lily」と名付けた。"
  },
  AwakerStory_11372_Title = {
    Text = "基本資料"
  },
  AwakerStory_11372_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_11373_Content = {
    Text = "リッツは手のかからない覚醒体で、「協力的」とは言えないまでも、学校のすべての事務に協力的な態度を示している。\n唯一気になるのは、リッツは毎日ダンス教室にいるにもかかわらず、彼女の本当のダンスを見た者は誰もいないということだ。\n優れたバレエダンサーとして、リッツの名前は関連する新聞に掲載されたこともある。残念ながら、融蝕現象の影響で、覚醒学部情報科はリッツがA.F.29@1年に第二劇場の舞台に立ったことしか確認できていない。\n学内新聞の記者ハンナ・ピーズリーは、ダンスへの愛で覚醒体リッツの心を開こうと、学内でダンス愛好家を集めることを提案した。\nこの提案はまだ、覚醒体管理局に承認されていない。"
  },
  AwakerStory_11373_Title = {
    Text = "物語・二"
  },
  AwakerStory_11373_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11374_Content = {
    Text = "ソレールは自分が美しいことを知っており、心の中でその美しさを天の恵みと呼んでいた。\n\n涙を浮かべて祈れば、人々は彼女に同情を寄せ、少し哀れなふりをすれば、情を寄せる友人たちは無条件で彼女をかばった。\n\nしかし、美しさは本当の権力の前では無価値だった。\n貴族に彼女を捧げて出世を図ろうとする両親に対し、ソレールの涙は初めて失敗の味を知った。\n\n誰か彼女を助けてくれる人はいないのか？\n愚かで時代遅れの運命から彼女を逃れさせてくれる人はいないのか？\n何か、どこか……この美しさを本当の武器にできるものはないのか？\n\nソレールが顔を覆って泣いているとき、運命の深淵を揺るがす使者が彼女の前に現れた。"
  },
  AwakerStory_11374_Title = {
    Text = "物語・三"
  },
  AwakerStory_11374_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_11375_Content = {
    Text = "どうして彼のせいじゃないなんて言えるのだろう？彼はまだまだ足りないことだらけだ。\nそんな極端な自責の念を抱き、オジールは他の覚醒体の倍の頻度で任務をこなし、誰もが称賛する「美徳」で「死」を葬った。\n過剰な仕事と若い調査員の感謝の言葉は、魂に刻まれた悲しみを本当に洗い流すことができるかのようだった。\n病巣は心の影に押しこまれ、腐った悪臭を放ち、密かに騎士を深い泥沼へと引きずりこんでいた。\n「すみません？こんにちは？」\nある日、オジールの前に、一筋の陽光のような、あるいはそよ風のような人が現れた。\n「先輩が言ってたんだけど、オジールは私とラモンナと一緒に、初めての調査任務に行ってくれるんだよね？」\n彼は二度と姫を守ることはできなかったが、神は彼に「守秘者」を守る機会を与えてくれた。\n「オジールと申します。あなた様と交わした契りにより、本日より忠実な騎士として、あらゆる敵からあなた様をお守りいたします。この誓い、生涯決して忘れはしません」"
  },
  AwakerStory_11375_Title = {
    Text = "物語・四"
  },
  AwakerStory_11375_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_11376_Content = {
    Text = "「平凡な公園に飽きた？つまらない動物展に飽きた？\nそれならカーシアのマジックカーニバルへどうぞ！\n動物好きの子供たちには、テノールを歌うライオン、バレエを踊るフラミンゴ、曲芸をする象、そして世界唯一のロバ調教師がいます！\n恋人同士の絆を深めたい方は、カーシアたちのユニークな回転生馬を試して、貴重なロマンチックな体験を手に入れましょう！\n日常生活に刺激が足りない勇者たちは、カーニバルの主人がデザインした鏡の迷宮に挑戦できます。\n41人の悪客を連れ出せば、豪華な賞品がもらえますよ！\nこれらの世界唯一のエンターテインメント施設に加えて、マジックの巨匠カーシアがあなたに不思議な狂歓の世界を見せてくれます。\n人体切断、大変身、極限脱出など、もっと多くのマジックをお届けします！\n幸運な観客はステージに上がってパフォーマンスに参加し、カーシアの見事な切断技術を体験するチャンスもあります。\nあなたの認識を覆し、日常生活をさらに味気なくさせることを保証します！\nさらに素晴らしいのは、これらすべてが無料で提供されることです、無料です！\nあなたの喜びがカーシアの最良の報酬です！\nミサゴ大学の皆さん、今週末、食堂の裏の空き地で、カーシアとお会いしましょう！\n\n注：カーニバルに一度入ったら完全に体験しなければならず、途中で退出はできません。\n耐性が低い方や精神、心臓が弱い方はご注意ください。\n\nカーニバル後に食欲不振、四肢欠損、目の喪失、腹部の裂け目などの症状が現れた場合、本カーニバルは責任を負いません」\n——《マジックの巨匠カーシアのマジックカーニバル盛大開幕！》"
  },
  AwakerStory_11376_Title = {
    Text = "物語・二"
  },
  AwakerStory_11376_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_11377_Content = {
    Text = "その「サロン」はいつの間にか、ロンディニウムの上流社会で静かに流行し始めた。\n神秘的なサロンでは、巨匠に肖像を描いてもらう機会を得たり、首相と夕食を共にしたり、さらには女王からの約束を得る者もいた。\n主催者、開催場所、開催時間は謎に包まれており、誰もがサロンで自分が最も欲しいものを手に入れることができると知られている。\nしかし、どのような客が主人の目に留まり、招待状を得ることができるのかは誰も知らない。\n八方美人のデクスター卿でさえ、サロンの主人に門前払いを食らった。\n「申し訳ありませんが、主人は今、芸術界の名士を招待することを好んでいます」\n「貴族？次の招待をお待ちください」"
  },
  AwakerStory_11377_Title = {
    Text = "物語・一"
  },
  AwakerStory_11377_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_11378_Content = {
    Text = "高慢な夫人は彼女の手を取り、世界中の愛を与えると言った。\n彼女は夫人の優しさと旦那の寛容さを信じ、微笑みや抱擁を信じたが、自分が彼らにとってはペットであり、脅威となればいつでも捨てられる存在だとは知らなかった。\n彼らは彼女を檻に投げ込み、彼女の信頼を粉々に砕いた。\n看守の鞭打ちも、同族の拷問も、身内の裏切りほど痛くはなかった。\n憎い、憎い、嘘で彼女の真心を奪った彼らが憎い、彼女の人生を苦痛な茶番にした彼らが憎い。\nこれが他人を信じた結果なら、彼女は永遠に自分だけを頼りにする。\n彼女の信頼は自分だけに与えられる。"
  },
  AwakerStory_11378_Title = {
    Text = "物語・四"
  },
  AwakerStory_11378_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_123300_Content = {
    Text = "いつの日か、彼女は自分の世界に戻るだろう。\n\nしかし、その前に彼女はこの世界の結末を見たいと思っている——\n\n「守秘者」と呼ばれる者は、この狂気と恐怖に満ちた世界に飲み込まれるのか、それとも輝きを放ち、この揺らぐ世界に真の救済と光をもたらすのか？\n\nそれは謎であり、挑戦であり、賭けでもある。\n\nそして彼女は、その答えを知りたいと思っている。"
  },
  AwakerStory_123300_Title = {
    Text = "物語·四"
  },
  AwakerStory_123300_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_123301_Content = {
    Text = "A. F. 3@2年@1月17日、審査会から@4地区で繁星黎明会が人身御供の儀式を行っているとの通知を受け、私は直ちに当該地区へ調査に向かった。\n到着した時にはすでに夕方で、当該地区は原因不明の濃霧に包まれ、ほとんど視界が利かない状態だった。\n霧を払う装置は携帯していなかったが、事態の深刻さを考慮し、私は霧の中へ突入した。もし時間を巻き戻せるなら、二度とこんな無謀な行動はしないだろう。なぜなら、なぜなら霧の中には恐ろしい@2が…………\nあの形容しがたい歪んだものが、人間離れした速度で襲いかかってきた時、私は何の反応もできなかった。体は硬直し、身動きが取れなかった。\nだが結局、私は死ななかった。あの少女、あの謎めいた、霧の中から現れた少女が私を救ったのだ。\n彼女が叫んだのはおそらく「竜巻」？よく聞き取れなかったが、霧の中から斧が飛んできて、あの恐ろしいものの頭を叩き割るのが見えた。そして少女は斧を引き抜き、肩に担いだ。\n「霧の中は危険だよ。死にたくなかったら、ここから離れて。」\nそう言った時、彼女の表情は微笑みだった。若い少女の甘い笑顔だった。だが私はなぜか、その笑顔が霧の中の怪物よりも背筋が凍るものに感じた。\n一人の人間、あるいは人間の姿をしたものが、怪物が跋扈する濃霧の中を歩き回りながら無傷でいられ、しかもこんな「甘い」笑顔を保っている…………\n恐怖に駆られ、私はようやく立ち上がり、悲鳴を上げながら彼女から距離を取った。\nすぐに濃霧が視界を覆い、再び何も見えない状態に陥った。だが彼女の笑い声、あの無邪気な、青春の少女の笑い声が、ずっと霧の中に響いていた。\n――「档案：@4地区繁星黎明会調査」"
  },
  AwakerStory_123301_Title = {
    Text = "物語·一"
  },
  AwakerStory_123301_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_123302_Content = {
    Text = "ほとんどの学生にとって、モシャは間違いなく友達になるのに最適な人だ。彼女はいつも微笑みを浮かべ、楽しそうに話題に乗り、簡単に相手の要求を拒絶することはないので、いつも誰かに買い物やおしゃべり、食事に誘われる。\nしかし、彼女の本当の姿を知っているのはほんの少数だ。そういう人たちの前では、彼女はもはや友好的に振る舞う必要もなく、ルールや秩序に対する軽蔑を隠す必要もない。\n「友達って何？ただ退屈を紛らわせるためだけよ。そうしなければ、問題児扱いされ、ハレト学長に呼び出されて質問されることになる——本当に面倒くさい。」"
  },
  AwakerStory_123302_Title = {
    Text = "物語·二"
  },
  AwakerStory_123302_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_123303_Content = {
    Text = "彼女の人生はいつも意外に満ちているようだった。まず猛威を振るう未知の霧に遭遇し、次に訳も分からず異世界に召喚された。\n召喚の儀式が完了し、初めて異世界の地を踏んだ時、茉夏は見慣れた濃霧を目にした。そして濃霧の中には、人々の悲鳴があった。\nそれは人身御供が邪教徒の捕獲から逃げている声だった。\n人身御供？邪教徒？なんて…………ワクワクする新鮮な言葉だろう。\nこれは新しい世界が弱肉強食のジャングルゲームで動いていることを意味する。そして都合のいいことに、彼女は一度も弱者だったことがない。\n彼女は平然と霧の中で邪教徒を狩り、嬉しさのあまり鼻歌まで歌い始めた。\n「一人また一人…………誰も知らない濃霧の中で、思う存分発散する♪」\n「あなたの頭蓋を叩き割って、脳の奥まで入り込んで、追いかけっこで暇を潰しましょう♪」\nこの気ままな鼻歌の中で、茉夏は心の空洞が渇いていることに気づいた――\nこの狂った世界は彼女の心の空洞を埋めることはできないが、魂が抱える破壊と狂気への飢えを和らげることはできた。"
  },
  AwakerStory_123303_Title = {
    Text = "物語·三"
  },
  AwakerStory_123303_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_123304_Content = {
    Text = "厳密に言えば、彼女は崩壊寸前の狂気の世界には属していないが、彼女はここを楽しんでいる。\nこの世界が燃え尽きる壮大な景色を楽しみ、絶望の中で苦しむ人間たちの崩壊を楽しんでいる。\n信仰は死に、社会は停滞し、道徳は崩壊し、自然も退屈な「普通の人」として偽装する必要はなくなった——\n彼女はついに心の獣を堂々と解放し、真の自分をさらけ出し、真の自分になることができる。"
  },
  AwakerStory_123304_Title = {
    Text = "基本資料"
  },
  AwakerStory_123304_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_126929_Content = {
    Text = "徐がいつキャンパスに現れたのか、本当に知っている者はほとんどいない。まるで彼女が極東で宮廷や王の幕営、そして様々な結社を自然と歩き回っていたように。\n誰もが彼女に対して生まれつきの親しみを感じ、まるで長年の友人、あるいは心の中の最愛の人のように思えた。たとえ共に何かを経験したことがなくとも。\nごく少数の覚醒体だけが徐に対して異常なほどの警戒を示す。あるいは、ごく少数の実力ある覚醒体だけが、徐の霧のように漂い広がり、相手の記憶に浸透する異常な能力を察知できるのだ。\nミサゴ校務処はこれに制限を加える必要があるか真剣に検討し、専用の対抗装置の開発まで議論されたが、徐はある取引と一つの約束によって、この懸念を解消した。\n「妾の意図は、この子たちには向いておりませぬ。」"
  },
  AwakerStory_126929_Title = {
    Text = "物語·二"
  },
  AwakerStory_126929_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_126930_Content = {
    Text = "A.F.@16@1年、航行の痕跡がどの探査手段にも現れず、いかなる手続きの承認も受けていない貨物船が、静かにレンディニエン貨物港に停泊しました。\nこの貨物船は、遠東地域の磐龍古国@2港から来たことが確認されました。\n貨物船が入港した夜、その港で働くスタッフや近隣住民は、夢の中で黒髪黒目、象牙色の肌を持つ東洋の女性を見たと述べました。目撃者たちは、その女性の容姿を語る際、「魅力的」「見覚えがある」といった言葉を使い、また、多くの男性目撃者は話している最中に硬直する現象が見られました。\nミサゴの調査員はすぐに貨物船の捜索を行いましたが、奇妙なことに、どこにでもある盗み笑いの声や明確な霊的反応を除いて、シルバーコアの痕跡は発見されませんでした。\nデクスター勲爵は翌日、貨物船の貨物室に入り、「何度も捜索された」陶器製の花瓶の中に、薄い霧が流れる表面を持つシルバーコアを発見しました。\nA.F.314年までに、そのシルバーコアはどの手段でも覚醒させることができないことが確認されました。\n現任の守秘者@3がミサゴに入るまで、そのシルバーコアは自ら覚醒の儀式を完了し、「徐」と名乗る覚醒体として覚醒し、@3とのリンクを求めました。\n——『ミサゴ大学シルバーコア保存記録』より"
  },
  AwakerStory_126930_Title = {
    Text = "物語·一"
  },
  AwakerStory_126930_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_126931_Content = {
    Text = "あなたは世界があまりにも静かすぎて、何かを壊して音を聞きたいと思った瞬間はありませんか？\n愛欲は彼女が投げ捨てた銀の瓶であり、その銀の瓶に驚かされた獲物…………愛する者を屠り、愛される者に屠られ、心が衰弱するまで、ただの肉体だけが残る。\nそして、搾り取られた肉体は、さらに高い権力を彼女に捧げ、目に映るすべてを生臭く美味しい混乱で染め上げる。\n決して止まらない混乱。"
  },
  AwakerStory_126931_Title = {
    Text = "物語·四"
  },
  AwakerStory_126931_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_126932_Content = {
    Text = "…………祭るべきでないものを祭るは、すなわち淫祀と謂い、民を惑わし財を費やし、たびたび禁じるも止まず。\n沿海の諸民は皆、雑神を祭る旧習あり、淫祠野廟を好んで修す。費やすこと多く、耕織は荒れ果てるも、郷里はその害を覚えず。為政者は幾度も廟を壊すも、官兵が撤すれば、日を置かず復燃す。\nさらに外邦の流民あり、郷里に定住し、外邦の教派の教標を逆さに懸け、@3の字形に似たるものを取り、「井」の約と謂い、己が用に転ず。\n廟中に祭る主祀及び陪祀は、皆生涯を調べ得る者にして、多くは非業の死を遂げた婦人なり。初めの信徒もまた多くは農婦、役者、野娼の類なり。\n妻は夫を連れ入り、母は子を連れ入り、娼は客を連れ入る。壮大となれば、党を植え私を営み、たびたび数村が一人を担ぎ上げる奇観あり。あるいは仕途に入り、あるいは私兵を養い、相争い相闘う。\n@4@4@3@2\n以下の字跡はすべて判読不能となっており、別に数行の非常に整った@3文字があり、言語学系の翻訳により、訳文は以下の通り：\n「恥知らずの老いぼれめ、偏った見解で、まったくつまらぬ。妾が退屈しのぎにコオロギを飼って闘わせるのにも、いちいち口を挟むとは。」\n「余計なお世話よ。」\n――「野狐斎雑誌抄本節選」より抜粋"
  },
  AwakerStory_126932_Title = {
    Text = "物語·三"
  },
  AwakerStory_126932_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_126933_Content = {
    Text = "優雅で魅惑的、致命的な魅力を持つ東方の「神」。伝説によれば、彼女が扇を動かすと、あなたは扇の下に最愛の人の顔を見ることができる。\nしかし、伝説はただの伝説であり、彼女があなたに視線を向けないことを祈るべきだ。彼女が無孔無隙の夜の霧のようにあなたの記憶に染み込むと、狂乱の熱狂を除いて…………あなたの頭の中には他に何も残らないだろう。"
  },
  AwakerStory_126933_Title = {
    Text = "基本資料"
  },
  AwakerStory_126933_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_129596_Content = {
    Text = "モスの覚醒体の状況はやや特殊であり、非拘束状態では、能力の発動は覚醒体自身の意志に基づかない。その周囲には不定期に渦流Mに類似した特殊エネルギー場が発生し、エネルギー場内部の物体を粉砕する。\nモスが内部に水分（血液等の体液を含む）を含む人や物体に接触した場合、その箇所のエネルギー場の発生が加速される。この現象はモス本人の制御を受けず、加えて覚醒初期は長期間狂乱状態にあったため、危険度は極めて高い。\nこのため、覚醒体系は物理系・化学系等の複数の系と学院横断的な協力を行い、数度の試行の末、その破壊力に耐えうる合成金属「モス鋼」の開発に成功し、これを口枷と拘束器として製作し、モスに装着させた。\nモス覚醒体の精神は、コードウェル研究員が実施した第11回「O–1841覚醒体接触実験」の後、安定に向かい始めた。この実験において、モスは渦流M–メルスクスの影響を自身に転移させ、周囲への危害を大幅に低減した。\nただし注意すべき点として、モスは自身のみでは長時間この状態を維持できず、「モス鋼」拘束器の助けを借りることで初めて、渦流Mの影響を長期的かつ安定的に自身の内部に維持し、同時にその能力を戦闘に導くことが可能となる。\n正気を取り戻した後、モスは明るい本質を見せ、またノディラ覚醒体に対して原因不明の親しみを示した。これは両者の精神の根源における経験に関係があるようだ。\n――《モス覚醒体報告》より抜粋"
  },
  AwakerStory_129596_Title = {
    Text = "物語·二"
  },
  AwakerStory_129596_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_129597_Content = {
    Text = "彼女は文を正しく組織する方法を知っていても、自分がどこで生まれたかをあなたに伝えることはできない。実際、どの家であっても、彼女は今、雪のように白い砂浜、密林、そして果てしない海を思い出すことしかできない。\nしかし、もし彼女に家がどこにあるのか尋ねれば、彼女はぎこちない言葉と熱心な身体言語でこう答えるだろう：家は海の上にあり、潮流に乗ってあちこちを漂っている。\n長い間誰もそばにいない人は、孤独とは何かを判断できないが、その船の上で彼女は親しみを感じ、友情を得た：彼女はオウムガイという名の仲間と美味しい焼き魚や美しい貝殻を分かち合い、陸地、旅、冒険についての夢を分かち合い、最後には黒い波と渦に帰る死を分かち合った。"
  },
  AwakerStory_129597_Title = {
    Text = "物語·三"
  },
  AwakerStory_129597_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_129598_Content = {
    Text = "北大西洋渦流M–メルスクスが初めて出現したのはA. F. 1■■であり、その後数百年の間に規模は徐々に拡大した。A. F. 29■の時点で、M–メルスクスは直径約260–300フィート（80–90メートル）、水流幅約5マイル（8キロメートル）の大渦へと発展していた。\n水流がもたらす強大な吸引力とその影響（付近海域の魚類や漁船が被害を受けた）に加え、M–メルスクスの下にはさらに大きな脅威――融蝕裂隙が存在していた。学院メンバーによる長期間の観察と研究の結果、M–メルスクスの形成はその下の融蝕裂隙と直接的な関係があると確定され、A. F. 313に正式にその除去が実施された。\n裂隙の中で、学院は大量の生物と船舶の残骸を発見し、番号O–1841の銀芯を取得した。\n――『M–メルスクス事件記録』より抜粋"
  },
  AwakerStory_129598_Title = {
    Text = "物語·一"
  },
  AwakerStory_129598_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_129599_Content = {
    Text = "言葉が通じない？問題ではない。身振り手振りでコミュニケーションを取ることができる。制御できない能力？この学校では日常茶飯事で、数日の実験で解決できる。\n明るい笑顔とほぼ野生的な性格で、モスクはすぐに他の覚醒体たちの歓迎を得た。彼女は自分の能力を忘れて大きな破壊を引き起こすことがよくある(神よ、3回も再建された噴水を守ってくれ)、でもそれがどうしたというのか？彼女は故意ではない。\n多分。"
  },
  AwakerStory_129599_Title = {
    Text = "基本資料"
  },
  AwakerStory_129599_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_129600_Content = {
    Text = "すべてが急流に呑まれる前、果てしない大海と微かに塩辛い潮風の中、あの船の上で、血の繋がらない家族と友人たちが彼女に孤独の意味を教えてくれた。そして二度とそこに落ちたくないと思わせてくれた。\nだが彼女の一番の友人のため、彼女の小さな家族のために、彼女は再びあの漆黒の死の静寂へ戻ることを厭わなかった。\nすべてが闇に覆われた後、彼女は別の姿で新たな生を得た。こうした生活には不便も多い――彼女は自分の力が周囲のものに甚大な破壊をもたらすことをしばしば忘れてしまう――だが、もっと多くの友人を得られる可能性は、彼女を限りなく幸せにした。\nもちろん、一番の友人がかつての二人の物語を思い出してくれたら、もっと良いのだけれど。\n「もっと良いよりもっと良い、もっともっともーっと良い！」"
  },
  AwakerStory_129600_Title = {
    Text = "物語·四"
  },
  AwakerStory_129600_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_134315_Content = {
    Text = "網に囚われし織り手、運命劇場の劇作家にして永遠の観客。\n糸が指の間から垂れ落ち、幕布、脚本、そして牢獄へと絡み合う――その一本一本はアラクネ自らの手で紡がれ、やがて彼女自身を幾重にも縛り上げる。\n観客席は永遠に無人のまま、ただ彼女だけが客席から舞台上の自作自演を見つめ続ける。繰り返し、繰り返し、終幕は永遠に訪れない。\n彼女の存在は、劇場の亡霊であり、運命の具現でもある。"
  },
  AwakerStory_134315_Title = {
    Text = "基本資料"
  },
  AwakerStory_134315_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_134316_Content = {
    Text = "アラクネは最初、自分に運命が見えることを知らなかった。\n世界は彼女にとっても他の人と同じように、曖昧で、騒がしく、偶然に満ちていた。\n二歳の年、彼女は人生で最初の言葉を口にした。\n「ママ」でも「パパ」でもなく、玄関のポーチに立ち、一族を何代にもわたって世話してきた老執事に向かって静かにこう言った――「おやすみなさい」。\nその夜、執事は心臓発作で急逝した。彼女は彼が遺した懐中時計を握りしめ、使用人部屋の前で泣きながら眠りに落ちた。あの頃はまだ死も運命も分からなかったが、運命が先に漏らす苦い味をすでに知ってしまっていた。\n五歳、晩餐会の客人たちが顔を紅潮させて歓声を上げる中、彼女は母の真似をして爪先立ちになり、ぎこちないワルツを踊った。\n足元の赤い靴は血のように鮮やかで、何かの予兆のようでもあった。回転した時に転んだが、その瞳に一瞬よぎった光景に誰も気づかなかった――まるで転ぶことが定められていたかのように。\n七歳の誕生日、父は「モイライ」という名の紡ぎ車を贈ってくれた。運命の三女神の名だ。\n彼女は林の中を駆け回り、澄んだ笑い声を響かせていたが、つまずいた時にカチッという音が聞こえた。紡ぎ車が折れたのだ。\n落ち葉の中にしゃがみ込み、指でひび割れをなぞると、ふと気づいた――まるで無数の糸が断面から溢れ出し、指先に絡みつき、見えない彼方へと続いているかのようだった。\nその後、初めてオペラ座に足を踏み入れ、初めて親友と出会い、初めて愛犬を自らの手で埋葬した…………\nすべての「初めて」に、無音の終幕が目の前にちらついた。彼女は悟り始めた――いわゆる始まりとは、すべて運命の結末がすでに定められたものなのだと。\nそれ以来、視線は二度と表層に留まることができなくなった。人の顔は薄紗と化し、一目でその下を奔る運命の流れが見透かせた。誰が夏の終わりに病死するか、誰が結婚式の前夜に首を吊るか、誰の子供が十年後に自らの手で親を埋葬するか…………驚きは消え、期待は枯れた。いわゆる「未来」とは、彼女が先に開封してしまった訃報に過ぎなかった。\n彼女は周囲の人々に迫りくる厄災を警告しようとしたが、言葉が口を出る刹那、いつも予言の成就を促してしまった。\n恐怖に怯え退く彼らの眼差しを前にして、その瞬間ようやく悟った――\n「見えることは、変えられることとは違う」。\n運命の網はとうに織り上がっており、彼女の「予知」は網目の隙間から偶然漏れ出た一筋の光に過ぎない――結末を照らし出しはするが、経緯を覆す力はない。\nこうして彼女は「モイライ」という名の紡ぎ車を手に取った。\n折れた紡ぎ車はとうに修復されていたが、ひび割れは残っていた。彼女は来る日も来る日も紡ぎ続け、運命にまつわる天賦の才は不思議とこの紡ぎ車と一体になった。\nそれ以来、すべての人の運命が彼女の指の間を流れ、交わり、時空を跨ぐ巨大な網へと織り上げられた。知らぬ間に、彼女自身もこの永遠の網に囚われていた。彼女は無数の笑いと涙を見届け、尽きることのない支点、尽きることのない可能性が、定められた滅びを纏いながら幾度も幾度も繰り返されるのを目にした…………\nそれでもアラクネは止まらない。織るためではなく、維持するために――もし彼女が止まれば、運命の網は崩壊し、幾千万の人生もろとも虚無に帰すかもしれないから。だが彼女には見えていた。運命の網が織り上がった時、「彼」の目覚めもまた、避けられない滅びをもたらすことを…………\n織り手であり、縛られし者。観客であり、囚人。劇作家であり、劇中の人物。\n他者の運命を見通せることは、果たして幸いなのか、災いなのか。\nアラクネはもう、問うことをやめていた。"
  },
  AwakerStory_134316_Title = {
    Text = "物語·三"
  },
  AwakerStory_134316_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_134317_Content = {
    Text = "幕がまだ完全に上がりきらぬうちに、光はすでに潮のように降り注いでいた。\nミサゴの観客たちは息を呑み、運命の主人公の登場を待っていた。\n舞台は小さく、オイディプスの足取りすら収まりきらないほどだった。だが制服を着た少年が手を掲げ、その声が簡素な舞台を貫いたとき、彼が発した最初の台詞はまるで神託の降臨のようだった――「私こそがあの不幸な者、父を殺し母を娶る定めを負った者だ。」\n…………\n「私はいったいどの神律に背いたというのか…………この不幸な私がなぜ神々に縋らねばならぬ？なぜ神の加護を求めねばならぬ？この敬虔な行いが不敬の名を得たというのに？」アンティゴネーという名の少女が、神律の不公正を問い質す。\n…………\nハムレットはデンマークの城で歩きながら思索する。「生きるべきか、死ぬべきか、それが問題だ。暴虐な運命の矢弾を黙って耐え忍ぶのが崇高か、それとも怒涛の苦難に敢然と立ち向かい、闘いによってそれを一掃するのが崇高か？」\n…………\n裁きの席で、ジョン・プロクターはゆっくりと顔を上げ、その答えを宣言した――「絞首台に上り死を恐れぬ者たちの前で、私は糞土にも劣る。そんな私がどうして名誉を汚して生きていけようか？」\n…………\nあの運命にまつわる言葉たちが、今日この一幕の劇となった。\nアラクネは袖幕に立ち、指が無意識に掌に食い込んでいた。\n劇中人物への共感から流れた涙、カーテンコールで雷鳴のように響き渡った拍手…………\n客席の観客たちのさまざまな表情を目に収め、彼女はふと気づいた――長い間ただ無為に鼓動していたあの心臓が、ようやくリズムを見つけたのだと。\nこの瞬間、彼女の声、彼女の存在は、いつしかこの壮大な運命の奔流に嵌め込まれていた――もはや運命を眺めるだけの目ではなく、今まさに書き記されつつある新たな脚本。観客の運命、演者の運命、そして劇作家の運命が、上演中の一つの劇によって結ばれた…………\n心の勝利とは、かくも静かで、かくも耳を聾するものだった。"
  },
  AwakerStory_134317_Title = {
    Text = "物語·二"
  },
  AwakerStory_134317_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_134318_Content = {
    Text = "運命の網の織り手として、幾千万の生死の経緯を維持し、掌に過去と未来を流す存在でありながら、アラクネにはほとんど浅薄とも言える趣味があった。\n彼女は演劇を愛していた。物語の起伏や台詞の美しさに魅了されたわけではない――それらはとうに熟知していた。脚本の創作者として、筋書きのあらゆる転換も、役者のあらゆる台詞も、すべて掌握していた。\nそれでも彼女は何度も劇場に足を運んだ。\n彼女が真に渇望していたのは、劇場に足を踏み入れた瞬間に得られる「臨場感」だった。\n幕が上がり、客席が闇に沈み、舞台だけが唯一の真実の世界となる。その瞬間、時間はもはや一方向に流れる河ではなく、限られた空間の中での演繹となる――過去、現在、未来がここで重なり合い、すべてが紙の上の脚本ではなく、「今この瞬間」に起きている生命の震えとなる。\nそして彼女は、ようやく運命の外側に立ち、糸を見つめるだけで触れることのできない傍観者ではなくなれた。\n劇場の中で、彼女は束の間記憶を封じ、舞台に立ち、震えながら遺言を紡ぐ少女になることができた。あるいは役者の自由な演技に身を委ねる観客として、予言者の重荷を下ろし、役者の一つの表情、一つの微笑みに息を呑み、涙し、震えることができた。予言者としてではなく、一人の生きた人間として、無知なる者の姿で、登場人物と呼吸を共にし、一つの台詞に胸を引き裂かれる。たとえ結末が変えられないと知っていても、たとえ悲劇が必ず訪れると分かっていても。この幻想こそが、永遠の観客という宿命から彼女を束の間解き放ってくれた。\n運命の外に隔てられるのではなく、その中に入ることを許される――たとえ一瞬でも、たとえ幻影であっても。\nこのささやかな陶酔こそが、運命がアラクネに与えた最も贅沢な恩寵だった。"
  },
  AwakerStory_134318_Title = {
    Text = "物語·四"
  },
  AwakerStory_134318_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_134319_Content = {
    Text = "私は3@2年の晩秋、旧市街の「運命劇場」にてメゾソプラノの職位の面接を受けに赴いた。\n到着したのは午後四時十七分、空は曇天で雨はなかった。劇場の正門は施錠されておらず、観客席には誰もおらず、面接官の姿もまったく見当たらなかった。\nしかし舞台の中央では人形劇が上演されていた――操り手はおらず、楽の音もなく、ただ数体の蒼白い人型の傀儡が無音のまま舞い踊っていた。その動きは恐ろしく精緻で、関節が回転するたびに微かなカチカチという音が響き、背筋が凍るようだった。そしてあの糸…………天井から垂れ下がるあの糸は、まるで生命を宿しているかのように微かに震え、時に張り詰め、時に弛み、何か目に見えぬリズムに呼応しているかのようだった。\n私が振り返って立ち去ろうとしたその時、貴賓席五番ボックスから女の声が聞こえた。\n「ようこそ、クリスティーヌ。」\nその声は若くもなく老いてもおらず、百年の埃を被った絹の帷の奥から滲み出る残響のようで、不気味で恐ろしかった。\n全身が凍りついた。まだ自己紹介もしていないのに、なぜ彼女は私の名前を知っているのか？　しかもこの人形たちは…………\n私は出口に向かって駆け出した。だがドアノブに手が届こうとしたその刹那、闇の中から無数の蜘蛛が湧き出した――その目は幽かな光を放ち、銀白の蜘蛛糸を吐き出して私の逃げ道を塞ごうとした。さらに恐ろしいことに、その蜘蛛たちは人の言葉を発し、あの台詞を繰り返し続けていた。「歌いなさい、我が天使よ、私のために歌いなさい…………」と。\n私は必死に糸を引きちぎり、走り、叫び、そしてついに本当に逃げ出すことができた。\n…………\nそれ以来、私は貴賓席五番ボックスからの視線を恐れ、歌劇場にそのボックス席の封鎖を求めた。\nしかし…………今でもスポットライトの下で歌うたびに、頭上から糸が私の眉をそっと引いているような感覚がある。\nまさか私もまた、糸に操られる人形になってしまったのだろうか？　それ以上考える勇気は、私にはない。\n\n――『歌手クリスティーヌ回想録』より抜粋"
  },
  AwakerStory_134319_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_134319_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_139857_Content = {
    Text = "すべてが血肉に侵蝕され、日常が錯乱と倒錯に飲み込まれ、嘶く雑音の中、タンポポは荒野にひらりと舞い降りた。\n手を差し伸べてあげて。彼女の手を取って。\n愛は表象を突き破り、あなたと、あなたが愛する人を、もう一度繋ぎ止める。"
  },
  AwakerStory_139857_Title = {
    Text = "基本資料"
  },
  AwakerStory_139857_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_139858_Content = {
    Text = "それは、これから起こる出来事と同じように。\nそれは、心に刻まれ、忘れられない出来事と同じように。\n\nどんな姿に変わろうとも。\nどんな世界へ変わろうとも。\nあまりにも違って、あまりにもよく似た二人は、同じ答えを導き出す。\n「わたしたちには、会いたい人がいる」\n「どんなことをしてでも、その人を見つけ出す。その人と共に在ることのできる世界を見つける」\n「もしその道のりがあまりにも遠いのなら、見つけ出すその日まで、探し続けながら、長い一生を過ごせばいい」\nそれが理由なのだろうか。\n血肉の叫びの中で、輝くシルバーコアは、守秘者の掌へとそっと置かれた。"
  },
  AwakerStory_139858_Title = {
    Text = "物語・一"
  },
  AwakerStory_139858_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_139859_Content = {
    Text = "「沙耶」とはいったいなんなのか？その手がかりは忘却の彼方に存在する。\n\n『――沙耶と名付けられた、あの生物、彼女が現れた理由は、偶然ではなく、彼女に生物としてプログラミングされた本能の結果であろう。その意図するところとは、あらゆる生物の究極の目的意識、繁殖、である。彼女とその眷属は、異次元の壁を越えて種を撒き散らす生物なのだ――』\n\n『――察するに、沙耶という個体は、彼女たちの種族の中でもイレギュラーな存在だったのではないか。人類は知性によって本能を破綻させた種族だという。そんな種としての病巣を、沙耶もまた継承してしまったのではないか。人類の精神性を吸収するにあたり、我々の本能と矛盾する論法の数々は、沙耶の繁殖本能までも破壊してしまったのかもしれない――』\n\n『――いつの日か、愛という名の祝福が彼女の頭上にもたらされるだろう。恋のときめきが彼女の胸を焼き焦がし、彼女は堂々と世界を巡り、ふたたび輝きと光彩を取り戻すことだろう――』\n\nはたして、善悪で判断すべきなのだろうか。\nそれとも、その愛の純粋さで判断すべきなのだろうか。\n\nおそらく、そのどちらにも答えはないのだろう。\n遥か昔の、まだ何も起こっていないこの宇宙へと辿り着いた「沙耶」は、\n記憶の中の答えを頼りに、忘却の彼方を目指して進んでいく。\nタンポポが咲くその時を待ちながら。"
  },
  AwakerStory_139859_Title = {
    Text = "物語・三"
  },
  AwakerStory_139859_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_139860_Content = {
    Text = "覚醒体となった「沙耶」はすぐに人気者になった。\n並外れた学習能力と、飽くなき知識欲。\nミサゴ大学において、そんな資質を備えた覚醒体は、稀有な存在だった。\n\n意外なことに、沙耶はラモンナに対して特に強い関心を示した。\nそれはラモンナと守秘者との絆のためか、あるいはラモンナとデクスターのあいだにある特別な親子関係のためだったかもしれない。\n\n沙耶の善悪や道徳観が人間とはかなり異なるものであったことから、大学は一時、ラモンナに特別な警備措置を取るよう提案した。\nしかし当の本人は、その提案を拒否したという。\n\n彼女たちが何を語り合っていたのかは誰にもわからない。\nミサゴ大学のある穏やかな午後。\n芝生を渡るやさしい風だけが、誰にも知られることのない彼女たちの長い語らいにそっと加わっていた。"
  },
  AwakerStory_139860_Title = {
    Text = "物語・二"
  },
  AwakerStory_139860_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_139861_Content = {
    Text = "人類からかけ離れたその種族は、人間を学ぶ過程で、本能に反する部分までもが、人間に近付いた。\nもし愛がなければ、創られるはずの世界には意味がない。\nもし愛があるならば、2人が存在する世界だけが意味を持つ。\nそれは恐ろしいほどに残酷で、それはまぶしいほどに純粋だ。"
  },
  AwakerStory_139861_Title = {
    Text = "物語・四"
  },
  AwakerStory_139861_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_142869_Content = {
    Text = "ポントスはレイサの死因を追い求めるのに長い時間を費やした。彼女はあまりにも多くの困難な戦いを経験し、あまりにも多くの卓越した勝利を収めてきた。薬物かもしれない、あるいは知られざるマジックショーかもしれない——必ずや理由があるはずだ、レイサを一匹の弱々しい海の怪物の手に死なせた理由が。\nそれからずっと、ずっと後になって、エポヤンスに加わらなかった彼のある人間の同行者に、最初の白髪が生えた。\n次第についていけなくなる体力、次第に鈍くなる反応、そして言葉にこそしないものの、表情ににじみ出る穏やかで静かな生活への渇望——すべてがあまりにも見覚えのあるものだった。\nポントスはふと悟った、ずっと姿を現さなかったその敵の名を——「老い」。\nレイサが隠居した理由、レイサが敗れた理由、彼の生涯の可能性をことごとく消し去り、憎しみだけを残した理由——それはただ、どこにでもあり、しかし抗いようのないものに過ぎなかった。\nだが、それはもはや何の問題もなかった。彼の破壊はあまりにも早く訪れ、得た力はあまりにも彼を満足させた。\nいかなる存在に忠誠を誓おうとも、いかなる代償を払おうとも、それはエポヤンスでは二度と起こらない。"
  },
  AwakerStory_142869_Title = {
    Text = "物語·三"
  },
  AwakerStory_142869_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_142870_Content = {
    Text = "「あなたは老いが起こることを許さないのか、それともあなたが制御できないいかなることも許さないのか？」\n彼は答えなかった。答える必要もなかった。\n深淵は災厄よりも早く彼を選んだ。なぜなら、彼が口にしなかった執念が深淵とあまりにも合致していたから。\n従うこと、寄り添うこと、変わらないこと——深淵から逃れられないように、深淵がすべてを窒息させながらもすべてを留め置くように。"
  },
  AwakerStory_142870_Title = {
    Text = "物語·四"
  },
  AwakerStory_142870_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_142871_Content = {
    Text = "ミサゴの大半の教職員と学生は、外勤の際にポントスの助けを求めることを非常に喜んでおり、ポントスもまた惜しみなく手を差し伸べてきた。\n寛大で、朗らかで、落ち着いて頼りになる——校内の一部のメンバーと明らかに深刻な摩擦があるにもかかわらず、この覚醒体が与える第一印象は驚くほど良いものだった。\nしかし、ポントス本人はすでにミサゴと協定を結び、エポヤンスの住民規模をこれ以上拡大しないと約束していたものの、「終了道特殊」の外勤行動を数度経験した後も、大量の移住申請が校務処に提出され続けた。\nシルヴィアが申請者たちに集団心理カウンセリングを行う傍ら、校務処は以下の二つの外勤規則を速やかに追加した。\n1、極めて緊急の状況でない限り、ポントスへの援助要請を厳禁とする。\n2、極めて特殊な状況でない限り、エポヤンスへの立ち入りを厳禁とする。"
  },
  AwakerStory_142871_Title = {
    Text = "物語·二"
  },
  AwakerStory_142871_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_142872_Content = {
    Text = "本来なら夜空を翔けるはずだった英雄叙事詩は突然幕を閉じ、彼は深淵へと墜ちることを選び、自らをより偉大にして計り知れない存在への犠牲とした。\nそれ以来、彼は分離も、平凡も、どうにもならない衰退も、二度と直面せずに済むようになった。\n彼は自らの肉親、友人、敵人を、すべて彼と一つに融合したエポヤンスの中に永遠に留めた。"
  },
  AwakerStory_142872_Title = {
    Text = "基本資料"
  },
  AwakerStory_142872_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_142873_Content = {
    Text = "A. F. 2@17年8月、ナラ@1湾を中心に、半径@3マイル以内で複数の異常霊的事件が発生した。\n@1件の通報電話が、死亡登録済みの複数の人間個体が@3旧址付近に出没しているのを目撃したと主張しており、これらの個体はその後の調査で、@2港町で1@19年に発生した爆発事件により死亡したことが確認された。当該爆発の理由は現在も未解明であり、関係者全員に程度の差はあるものの記録喪失の症状が見られる。\n「彼女を見た、誓って…………彼女は私が別れた時と同じくらい若いままだったが、そんなことはあり得ない。」\n「彼女が私と告別したのはもう@2年前のことなのに、彼女はあの頃と変わらず美しく、ただ彼らと共に崖の端に立ち、遠くから私に微笑みかけていた。」\n「…………私たちが大切にされる時、私たちは常に再び選択する機会を持つ、EBWYN@2OS、Ebwy@1noss…………」\n録音素材の末尾は海水のサージに似た不明な雑音によって汚染されており、当該目撃者は20時間後に家で器官衰弱により死亡した。死亡時の年齢は76歳であった。\n当該素材がミサゴ大学に届いた翌日、既に退職した覚醒体系研究員であり、当該目撃者チェンバーズ・コールドウェルの遠縁の親族でもあるアイリン・コールドウェルが、チェンバーズが持参したO-@1シルバーコアを受け取った。\nアイリン・コールドウェルの回想によれば、チェンバーズの体格と容貌は、若い頃と何ら変わりがなかったという。\n彼は姿を消す前に、一言だけ残した。\n「祂をミサゴへ連れて行ってください。祂はそこで最後のエポヤンスの帰人を待つのです。」\n――『ミサゴ大学シルバーコア保存記録』より抜粋"
  },
  AwakerStory_142873_Title = {
    Text = "物語·一"
  },
  AwakerStory_142873_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_146395_Content = {
    Text = "どの次元のロータンも言葉を好まないようだが、蝕滅・ロータンはとりわけそうだ。彼女の前では、言語は余分なものであり、力そのものが最も完璧な修辞となる。\n君王のように泰然とした優雅な外殻の下、瀕死の恒星のような異色の瞳の中に、彼女の最もリアルな渇望が燃えている――彼女は星海の深淵から湧き上がる太古の力であり、混沌が怒りの中に鍛えた白骨の刃だ。万物は彼女の眼には二種類しかない：戦う価値のあるものと、剣を振るうに値しないもの。\n星天の鯨の骨から鋳造されたあの双剣は常に飢えている、まるで彼女の力の頂点への渇望が決して満たされないように。"
  },
  AwakerStory_146395_Title = {
    Text = "基本資料"
  },
  AwakerStory_146395_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_146396_Content = {
    Text = "彼女の最初の記憶は怒りだけだった。\n顔もなく、形の境界もなく、ただ無限に、沸き立ち渦巻く暴力の本能だけがあった。彼女は星海の深淵に凝集した混沌であり、億万年をかけて醸成された災厄だった。彼女は引き裂き、燃やし、捕食した。いかなる目的もなく、ただそれが彼女の唯一知ることだったから。\nそこへ、白い紗の「神明」が現れた。恒星が内核から二つに割かれるように、彼女は自分の力が潮が引くように退いていくのを感じ、血肉と骨格が精神から根こそぎ引き抜かれ、荒れ狂う怒りの炎が魂から生きたまま剥ぎ取られた。\n\n神明は彼女の怒りを鎮めることができず、彼女の霊と肉を分離することを選んだ。\n混沌の獣はもはや存在せず、彼女の躯体はリヴァイアサンと化し、彼女の全ての力を携えて虚空へと沈んだ。そして彼女は、精神だけが残った残骸として、空虚な意識の中で目覚めた。\n怒りは消えず、より持続的で、より恐ろしいものへと変わった：渇望。力への果てしない渇望が、彼女を再び立ち上がらせた。\n彼女は歩き始め、戦い始めた。荒涼とした星海をさまよい、行く手を阻む強者すべてに挑んだ。一つ一つの勝利は空洞の躯に砂粒を一握り詰め込むようなものだったが、彼女はその砂粒の中から形を磨き出し、意志を磨き出し、「蝕滅・ロータン」の輪郭を磨き出していった。\n\nそして、彼女はあの鯨の歌声を聞いた。\n己の身体を世界全体と化した星天の鯨、無数の生命を束縛し奴隷とした巨大な存在、彼女がその身に見たのは欲望と恐怖ではなく、親しみだった。彼女の記憶が戻り始め、それが自分の力であることを知った。最初から最後まで、それは彼女のものだったのだと。\nそして、彼女はその前に立った。\nそして、彼女はその者に向けて剣を抜いた。\n\n巨鯨の権能は決壊した洪水のように彼女の身体へと流れ込み、彼女をほぼ引き裂かんばかりだったが、最初から最後まで彼女は立ち続け、星海の中に一頭の巨鯨の骸骨が加わった。\n奴隷にされていた星々は自由を取り戻した。欲望によって死んだ魂たちは頭を上げて仰ぎ見、彼女を救世者、ガーディアンと呼び、王冠を彼女の前へと捧げた。\n蝕滅・ロータンはその賛辞に応えなかった。ただ巨鯨の骸の上に立ち、体内で渦巻く新生の力を感じながら、魂の深奥で消えることなく続いていた呼びかけが、かつてないほど鮮明になっていくのを聞いていた。\nそれは星天の鯨の声であり、彼女自身の血肉が彼女を呼びかけていた。\n\n彼女の手がリヴァイアサンの頭蓋骨に触れ、無数の時代にわたって分離していた精神と肉体が再び交わった。骨の甲が彼女の身体を覆い、力が彼女の体に満ちた。\n混沌の獣は再生したが、彼女はもはや最初のただ暴怒するだけの災厄ではなかった。長い流浪、無数の戦い、かつて彼女が打ち倒し、また彼女を打ち倒した相手たちが、この純粋な混沌を意志を持つ刃へと鍛え上げていた。\n彼女は目を閉じ、体内で渦巻く完全な力を享受した。しかし彼女はまた、これが終点ではないことも明確に知っていた。\n\n星天の鯨の権能、リヴァイアサンの力、捕食してきた星々……すべては背後の階段だ。彼女は骨剣を手に取り、振り返って次の未知の星海へと歩み出した。\n彼女は渇望していた、次の彼女を沸き立たせる戦いを。"
  },
  AwakerStory_146396_Title = {
    Text = "物語·三"
  },
  AwakerStory_146396_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_146397_Content = {
    Text = "蝕滅・ロータンは背後の屍を振り返らない。\n打ち倒した相手、踏み砕いた荒野、捕食した星々……彼女はそれらを一つ一つ跨ぎ越え、次の目的地を探し続ける。\n\n力の果てに辿り着いた後、何をするのかと問う者がいた。\n彼女は答えなかった。なぜならその問いは全く意味をなさないからだ、炎が燃え尽きた後どこへ行くのかと問うようなものだ。炎に「その後」はなく、燃焼すること自体がその存在のすべてだ。\n\n彼女は歩き、戦い、何度も何度も剣を振り上げる。それは決して、証明のためでも、守護のためでも、復讐のためでも、権力欲のためでも、その他のつまらないもののためでもない。\nただ、剣と剣が衝突するその瞬間、力と力が交錯するその刹那に、彼女は自分が生きていることを最も鮮明に感じられるから。\n\n力を追い求める道に終わりはない。そして彼女はそのことを喜んでいる。"
  },
  AwakerStory_146397_Title = {
    Text = "物語·四"
  },
  AwakerStory_146397_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_146398_Content = {
    Text = "ミサゴに到着した後、蝕滅・ロータンの静けさは二日間続いた。三日目の夕暮れ、彼女は骨剣を携えて公共訓練場に現れた。\n\nミサゴの覚醒体たちには誇りを持つ理由があり、訓練場に現れる者はとりわけそうだった。しかしこの無礼な予期せぬ来訪者に対して、彼らは常に高度な警戒を保っていた。火山島での簡単な接触の後、蝕滅・ロータンにまつわる伝説はすでに覚醒体たちの間に広まっており、彼らは自分たちがどのような相手に直面するかを知っていた。\nしかし実際には、彼らの警戒は十分ではなかった。\n\n最初に挑戦した覚醒体が一剣で訓練場の境界の外へ弾き飛ばされ、二十メートル先の石壁に叩きつけられた時、訓練場全体が前例のない興奮に包まれた。二人目、三人目……@3年のその平凡な夕暮れに、九名の覚醒体が相次いで蝕滅・ロータンに挑戦した。\n\n現場にいた校刊記者ハンナの描写によれば、蝕滅・ロータンはその間一言も発せず、沈黙にして不屈の灯台のように、覚醒体たちの海潮のような猛攻の中に屹立していた。あの二本の骨剣は夕焼けの中で灯りのように輝き、優雅な弧を描きながら一人一人の相手の攻勢を精確に終わらせていった。\n\nその日、蝕滅・ロータンの鎧は80％以上が損壊し、肩と腹部に二か所の極めて深刻な創傷を負い、骨剣には大きな欠けが生じ、ほぼ折れかけていた。そのすべてを代償として、彼女は訓練場に最後まで立っていた唯一の人物となった。\n\n彼女は壁に剣で刻まれた深い傷跡、地面に巨大な衝撃が残した深い穴、そして複雑な表情で彼女を見つめる覚醒体たちを眺め、この世界に来て初めての笑みを浮かべた。\n\n「お会いできて光栄です。私のことは蝕滅・ロータンと呼んでください。」"
  },
  AwakerStory_146398_Title = {
    Text = "物語·二"
  },
  AwakerStory_146398_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_146399_Content = {
    Text = "『ミサゴ大学天文観測所異常報告』\n\n洪積暦@3年より、北半球の複数の天文台が銀河系辺縁領域における異常なスペクトル減衰現象を相次いで報告した。初期データによれば、少なくとも三つの登録済み恒星が極めて短時間のうちに観測可能範囲から消失し、そのスペクトル残留は既知のいかなる天体衰亡モデルとも一致しなかった。超新星爆発の放射特性もブラックホール降着の重力レンズ効果も見られず、恒星はまるで何かに一口で捕食されたかのように、跡形もなく消えていた。\n\n洪積暦@3年3月、審査会の天体異象グループが四番目の恒星消失座標において極低周波のれいち波動を捉えた。同年8月、五度目の消失イベント発生後、天文観測所はついに改良されたシルバーコア長距離探知アレイを用いて短時間の視覚信号を捕捉した：白骨で構成され、鯨に近似した巨大な生物で、腹部には尖刺状の突起が密集し、口腔内部は物質界と相容れない高温スペクトルを呈していた。その巨大な口が開いた瞬間、恒星の光は深淵へ流れ込む小川のように、音もなく消えていった。\n映像はわずか0.7秒しか持続せず、探知アレイの過負荷により中断された。事後検査では、アレイの三分の一のシルバーコア素材に不可逆的な構造崩壊が生じていたことが判明した。\n\n洪積暦@3年冬、天文台はれいち脈動信号が突然方向を変え、その目的地が筆者のいる場所であることを観測した。\n審査会は最高警戒状態に入ったが、予想された災厄は訪れなかった。信号は近地球軌道に接近した際に無害な状態へと収束し、最終的に北西海域の無人火山島にポジションが特定された。最初の調査隊が上陸した際、彼らは火口の玄武岩壁に深く刻み込まれた、未知の骨質素材で構成された骨剣と、剣の傍らで胡座をかき、まるで長い間待っていたかのような人型個体を発見した。\n\nその個体は女性の外見を持ち、全身に骨質の甲片と異族の鎧の紋様を纏い、双瞳は異色だった。調査隊が近づくと、彼女は目を開け、その口調には敵意は一切なく、ただ傲慢とも言える静けさがあった。\n「あなたたちの中に、私が手を出す価値のある者はいますか？」\n調査隊は顔を見合わせ、誰も答えなかった。しばらくの沈黙の後、彼女は再び目を閉じた。\n「では、一人連れてきなさい。待っています。」\n\nその後、審査会とミサゴ大学は共同でその島を特級監視区に指定し、複数の覚醒体を派遣して調査を支援させた。数ヶ月に及ぶ遠隔観測と慎重な接触を経て、その個体は最終的に「十分に強大な相手を得る」という条件のもとで審査会の管理に協力することに同意し、覚醒体名簿に登録された。\n恒星消失イベントはその個体が収容されて以降、完全に停止した。しかし検査データによれば、捕食された恒星のエネルギーは、何らかの形で個体の体内に蓄積されているようだ――長期間の観測期間中、彼女のノースインデックスは持続的に上昇し続け、いかなる減衰傾向も示していない。"
  },
  AwakerStory_146399_Title = {
    Text = "物語·一"
  },
  AwakerStory_146399_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_147418_Content = {
    Text = "金波特城の西部山岳にある農場は、今や荒れ果て、誰も住んでいない。\n@2年6月15日、ここに隕石が落下した。数週間後、隕石落下地域の生態系が変異し、植物が異常に成長し、奇妙な果実を結んだ。動物も変異し、住民一家が精神異常をきたし、奇妙な死を遂げた。\nミサゴ調査員が現地で徹底的な捜索を行い、最終的に井戸の底で奇妙な色を放つシルバーコアを発見した。当時の調査員によれば、そのシルバーコアの色は「純粋で、四方に流れる色で、既知の光のスペクトルのどの色とも異なる」\n\n——《ミサゴ大学シルバーコア保管記録》より抜粋"
  },
  AwakerStory_147418_Title = {
    Text = "物語·一"
  },
  AwakerStory_147418_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_147419_Content = {
    Text = "1.D03と直接目を合わせないこと。さもないと彼女は秒速20ヤードの速さで駆け寄り、姉を探すよう頼んでくる。\n2.彼女は常に熱を発し続け、私は彼女の手の中の水仙が短時間で枯れるのを目撃した。ああ、環境保護主義者の悪夢だ！\n3.夜になると本当に光る！キラキラ！助けて、私の目が@3D03がいるミサゴには街灯がいらない。\n4.食堂でD03の腕に直接触れたが、誓って故意ではない！不思議な感触……例えるなら、麦芽糖シロップ、羊のチーズ、アップルプディングに触れたような……お腹が空いた。\n5.暗影合唱団の連中がD03をサークルに招待したが、すぐに追い出したと聞いた。これは普通のことだ、人間の声帯がどんなにひどくても限界がある、同級生たちの驚きを理解できる。\n\n——ハンナ《覚醒体観察ノート・D03》より抜粋"
  },
  AwakerStory_147419_Title = {
    Text = "物語·二"
  },
  AwakerStory_147419_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_147420_Content = {
    Text = "彼女は歌声で無数の荒星人を感動させた。\n眠れぬ夜に、子供たちは歌声を聞いて夢の川に沈む。\n細雨の中で、旅人は歌声を聞いてため息をつく。\n愛する人を失った風の中で、恋人は歌声を聞いて最後の涙を流す。\nしかし今、彼女の聴衆は風となって去り、未完の物語だけが残された……"
  },
  AwakerStory_147420_Title = {
    Text = "基本資料"
  },
  AwakerStory_147420_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_147421_Content = {
    Text = "「歌え！歌声は優しい風\n雲を抜け、星空を越え\n世界はもう私と無関係」\n——アルバム《星々の彩》序曲より抜粋\n\nかつて荒星の有名な歌姫だった。\n災厄が訪れた際、彼女は手持ちの船のチケットをマネージャーに譲った。「姉と離れられないから」と。\nそして彼女は権力者たちを乗せた船が悠然と去るのを見送った。彼女に開かれていた華やかな扉は今や完全に閉ざされた。残されたのは砂漠、姉、そして無数の同胞だけ。\n彼らは静かに死のカウントダウンを聞いていた。\n\n十年、二十年、百年……ティンクトは歌声で皆を慰めた。\n喉から血が溢れても、彼女は姉と同胞が次々と死んでいく現実を変えることができなかった。\n\n歌姫ティンクトは白い砂漠を一人で歩き、時折姉がまだ生きていると夢見る。\n彼女たちはかつてのようにお互いを抱きしめ、頭上の星空が一片一片と落ちていくのを見つめ、対岸の戦艦の残骸が静かに燃える。\n彼女は歌うことをあきらめなかった。声がかすれて壊れた風箱のようになり、周囲のすべての生き物を飲み込んでしまうまで。\n歌姫はただ無感動に、日々歌い続けた。\n歌声がある限り、「世界は私とは無関係」。"
  },
  AwakerStory_147421_Title = {
    Text = "物語·三"
  },
  AwakerStory_147421_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_147422_Content = {
    Text = "「人が過去を振り返るばかりになると、彼はすでに老いているということだ」\nこの言葉に照らし合わせると、ティンクトは宇宙で何万年も流転する恒星のように老いているはずだ。\n彼女の意識には現在も未来もなく、ただ無意味に延長され、繰り返される過去だけがある。\n\n彼女は金色の花火が津波のように上がり、宇宙の星河で翼を広げるのを見たことがある。\n彼女は数万の異なる顔が暗闇に隠れ、彼女の旋律に合わせて情熱的に踊るのを見たことがある。\n彼女は諸天が彼女を呼び、彼女を囲み、永遠の輝きを示すのを見たことがある。\nしかし、彼女の目はこの苦難の大地だけを見つめている。"
  },
  AwakerStory_147422_Title = {
    Text = "物語·四"
  },
  AwakerStory_147422_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_148397_Content = {
    Text = "このシルバーコアはミサゴのシークレットキーパー%player%が@2峰崩壊事件後に回収したものである。その元の次元はすでに観測不能となっているため、シルバーコア析出後の影響および実際の覚醒方法は現時点では不明である。 \n以下の内容は、シークレットキーパー%player%が常に携帯していた紙製の手記に記されたものである： \nシルバーコアの質感を肉眼で観測したところ、極めて純粋であり、目に見える不純物は一切存在しない。外力が介入しない場合、全体の構造は規則的な形状へと向かい、何らかの意志が懸命にそれを堅固で安定して見せようとしているかのようで、ファイアオパールのような明るい輝きを放っている。しかしこのシルバーコアのノースインデックスは限界値に近く、実際の内部構造は極めて脆弱で疎らである。観測距離が1/@1インチ未満になると、このシルバーコアの自己防衛行動が発動し、観測者は突然大量の氷晶に似た流動粒子を目にすることになる。これらは以前、極めて特殊な方法で外界の光を屈折させ、シルバーコアの核心が覗き見られないよう保護していたと推測される。 言い換えれば、あまり専門的な表現ではないが、私はこれを「欺瞞」に満ちたシルバーコアだと考えている。 \nシルバーコアの自己防衛機構が発動した後、観測者の体は一時的な硬直状態に陥り、瞳孔は徐々に色を失い、最終的に完全に蒼白となる。シルバーコアはその間に調整を行い、観測される前の安定した状態へと戻る。 複数回の試験を経て、この自己防衛機構は実際の損傷をもたらさないことが確認されたが、それに伴う低体温症状には依然として一定の危険性がある。注：甘いものを速やかに摂取すること、特にリンゴ系のスイーツには明らかな緩和効果があるが、その理由は……現時点では不明、だろうか？ 朗報として、これらすべてが起きた後も、この自己中心的で、心の内に幾重もの防壁を張り巡らせた小さな詐欺師は、明らかに私たちに対して本当の悪意は持っていない。 \n――『ミサゴ大学シルバーコア保存記録』より抜粋"
  },
  AwakerStory_148397_Title = {
    Text = "物語·一"
  },
  AwakerStory_148397_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_148398_Content = {
    Text = "以下の内容はカラブの口述をもとに、ミサゴ覚醒体系背景調査組が整理・記録したものである：\nカラブが幼い頃は十字軍東征の熱気が高まっていた時代であり、身寄りのない彼女は東へ向かい、アンティオキア公国の叔父一家を頼ることを決意した。東方の新天地は自由と夢の象徴であり、無一文の者でも活路を見出せると聞いていた。ロサおばさんはプランテーションまで経営し、なかなか豊かに暮らしていた。カラブは幼い頃からロサおばさんととても仲が良く、アンティオキアへ向かう旅費を貯めようと心に決めた。 \nカラブは都市のスラム街を転々とし、後ろ盾のない彼女は盗みや詐欺で生き延びるしかなく、もともと純粋だった一面はすり減っていった。やがて彼女は魔術師アイヴァーグと出会い、彼はカラブに、自分と組めば信者からの供物を二人で三七分けにすると約束した。そうすれば東方への旅費を貯められるし、大好きなお菓子もたくさん買えると。二人はこうして詐欺師コンビを結成し、カラブは小さな仙女の教母として田舎に急ごしらえで建てられた神殿に住まい、アイヴァーグは彼女の大祭司として信者を集めた。 \nカラブの地元での名声が高まるにつれ、彼女は現在の取り分に満足できなくなり、協力関係から抜けると脅してアイヴァーグに供物の分配を七三に逆転させた。ようやく優位に立ったカラブは偽の教母として悠々と暮らしていたが、やがてアイヴァーグが彼女の供物を横領し、こっそり三人の妻を娶り四人の息子まで儲けていたことを知った。裏切りに直面しても、カラブは怒らなかった。彼女はアイヴァーグに情深く語りかけ、東方へ行くことはもとより儚い夢に過ぎないとよく分かっている、お金は自分には必要ない、アイヴァーグに残してあげよう、ただアイヴァーグの家族と夕食を共にして、これからの詐欺事業について一緒に話し合いたいだけだと告げた。 \nカラブがようやく分別をわきまえたことに驚き喜んだアイヴァーグは、彼女を宴に招いた。夕食が終わりに近づいた頃、カラブは突然豹変し、彼女の一声で近くの村人たち――彼女の忠実な信者たち――が突然押し入り、農具や調理器具を手にして魔術師一家八人を半殺しにし、家の中の値打ちものをすべて持ち去った。「私を騙そうなんて、まだまだ甘い」――満足げに立ち去るカラブは、自分の額に小さな黒い三角形が現れていることにまだ気づいていなかった……"
  },
  AwakerStory_148398_Title = {
    Text = "物語·三"
  },
  AwakerStory_148398_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_148399_Content = {
    Text = "皆さんご存知の通り、学校の別名とは何でしょうか？\n象牙の塔！ \n聞けば聞くほど「仙女」という名にぴったりではないか。なにしろ、お金があって、暇があって、心に貴重な信頼を抱く潜在的な信者がたくさんいる、完璧な楽園など、他のどこに求めればいいというのか？ \nカラブの教団は目覚ましいほどの速さで、短期間のうちにかなりの数の信者を獲得した。中核を担うのはほぼ全員が幼い覚醒体であり、彼らはほとんど敬虔なまでにこの「仙女の教母」を信じ、喜んで定期的に一定量のお菓子や点心を納めていた。意外なことに、あるいは予想通りのことに、カラブは確かに時折祝福を授けることがあった。その多くはレオ王国の伝統的な祝日に起こり、たとえば3@1年のフロストデーにはあり得ないはずの降雪が起き、新年の夜には今も語り草となっているお菓子の雨が降った。 \n教務処はこの、原則として存在してはならない「校内布教行為」を阻止すべきかどうか、一度も議論したことがないようだった。\n「祂たちに遊ばせてあげなさい。この子たちがかつて何を経験してきたか、私たちは皆知っている。同じ子供にしかできないことというものが、やはりあるのよ。」 \n「もちろん、度を超えてはいけないけれど。」\n名前を伏せておきたいという校内関係者が、にこにこしながら上記のような発言をした。信頼性の低い情報によれば、彼女と紅茶を共にする前のあの一件が、カラブがこれまでに唯一、本当に校則に触れようとした出来事だったという。"
  },
  AwakerStory_148399_Title = {
    Text = "物語·二"
  },
  AwakerStory_148399_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_148400_Content = {
    Text = "彼女は最も聞き分けのいい子供のようで、あなたの最も秘めた心の内を常に見抜き、思わず信頼して打ち明けずにはいられなくさせ、そして絶妙なタイミングで、あなたが切望してやまない「祝福」を与えてくれる。しかし、どうか忘れないでほしい――彼女の愛らしい体つきと哀れを誘う瞳に情けをかけてはならない。さもなければ、あの純白の体がかつて飲み込んだ、貪欲な怨霊たちの一員となってしまうだろう。"
  },
  AwakerStory_148400_Title = {
    Text = "基本資料"
  },
  AwakerStory_148400_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_148401_Content = {
    Text = "嘘をついたことはあるだろうか？最初の嘘が口をついて出る時、それはいつも、もつれる舌と唇、喉から飛び出しそうな鼓動、そして掌の汗を伴うものだ。穏やかな日差しさえも、目眩を起こすほどの眩光へと変わってしまう。 しかし嘘が一万回繰り返されれば、恐怖は消える。口から出る言葉は滑らかになり、思考はますます明晰になり、微笑みも自然なものとして固まっていく。 仙女を演じ、教母を演じ、権力者の縁者を演じ、彼女は自ら作り上げた幾千もの素性をとうに使いこなし、嘘の陰に自分自身を隠すことに慣れ、ついには自らも嘘の一部と化した。 しかし最初のあの野ウサギは、今も記憶の中の夕日に照らされた小さなプランテーションに潜んでいる。 氷が解け雪が融ける夜に、そっと顔を覗かせながら。"
  },
  AwakerStory_148401_Title = {
    Text = "物語·四"
  },
  AwakerStory_148401_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_148994_Content = {
    Text = "姿かたちは変わらずとも、人々は一目で、自分たちがよく知るあの小さな騎士との違いを見て取ることができた。\nかつて澄んでいた双眸はもはや輝きを失い、白い衣は汚れに染まり、それ以上に彼は常に意図的に全ての人と距離を置いていた。\nしかし恐れることはない。あの恐ろしい黒い泥の下には、あなたが知っているあの心臓が、忠義と正義のために鼓動し続けている。\nかつて一度は忘れかけたが、彼は最終的にあの騎士の誓いを拾い上げた。\n彼は抗い続けるだろう――自らの内なるもう一つの声と、彼が大切にするものを傷つける全ての存在と。"
  },
  AwakerStory_148994_Title = {
    Text = "基本資料"
  },
  AwakerStory_148994_UnlockDesc = {
    Text = "覚醒体のレベルが1に達した"
  },
  AwakerStory_149051_Content = {
    Text = "ミサゴでかつて、学校全体を騒然とさせた怪奇事件が起きた。以下は校内記者ハンナがまとめたインタビュー記録である：\n「夜も更けて静まり返った頃、図書館でがさがさと物音がして……怖くて見に行けなかった。翌朝になって気づいたら、中の本が全部\nきちんと整理されていて、自分で片付けるよりずっと綺麗になっていたんです！」 ――校図書館管理員\n「最近キャンパスがずいぶん綺麗になったと思わない？まさか夜中にゴミを片付けてくれる幽霊でもいるの？」\n――ある実習授業の教師\n「任務に出ている時、いつも後ろに誰かついてくる気がして……激しく戦う音が聞こえることもあって、振り返ると、溶蝕モンスターの残骸が一面に広がっているだけなんです。」――ある新人調査員\n肝の据わった学生数人が自発的に調査チームを結成し、一晩の睡眠を犠牲にして答えを得た。\nすべての発端となった人物は自らの「罪行」を認め、騒ぎを引き起こしたことについて誠実に謝罪した。しかし続いて寄せられた感謝の言葉に対しては、どこか居心地が悪そうな様子だった。本人の言葉を借りれば、「ただじっとしていられないだけです。」\nこれに対し、校内心理教師シルヴィアは次のような見解を示した：「根本的に心の優しい子として、彼は過去のことに対してあまりにも強い罪悪感を抱いている。それが長い時間をかけて、深く根付いた自己不全感になってしまっている――他者からの率直すぎる好意は、むしろ彼をより辛くさせてしまうのよ。」\nこの出来事はあっさりと幕を閉じたが、「透明な幽霊」の伝説はそこから広まっていった。教師も生徒も暗黙の了解で彼の正体を明かそうとせず、ただ次第に、誰もが知るようになった――この「幽霊」はただみんなの役に立ちたいだけなのだと。\n皆なんとなく分かっているようだった。見られることを望まないこの少年にとって、最大の感謝とは、この秘密を彼一人だけのものとして守り続けることなのだと。"
  },
  AwakerStory_149051_Title = {
    Text = "物語·二"
  },
  AwakerStory_149051_UnlockDesc = {
    Text = "同調率レベル5達成で解放"
  },
  AwakerStory_149052_Content = {
    Text = "親愛なる読者の皆様、これは後記であり、同時に私の懺悔書でもあります。\nこの旧式の古典騎士小説を完成させるために、私は大金を投じてあの謎めいた兜を競り落としました。歴史に記録された、いかなる国にも属さないと言われるものです。ご覧の通り、そのおかげで私のインスピレーションは尽きることなく、まるで本当に広大な古戦場を目の当たりにしているかのようで、鎧を纏った騎士たちが刃を交えていました。私はこれらの奇妙な幻覚に頼り、心の中で最も完璧な作品を完成させることができました。\nしかし私は思いもしませんでした。この骨董品が私にインスピレーションを与えると同時に、恐ろしい悪魔を密かに宿していたとは。\n読者の皆様、想像してみてください。一つの声がある、混沌として、持続的で、昼夜を問わず止まらない。さらに四肢が制御を失い始め、意識も頻繁に途切れる様子を――いや、途切れるのではない、むしろ意志が肉体から離れていくようで、自分が何をしているか分かっているのに、ただ傍観するしかない……しかしあれは確かに私の体なのに。\n昨夜、この小説を書き終えたばかりの時、私は再び祂の声を聞きました。\nその後、くそ、あの光景を思い出したくもない――\n私は取り返しのつかない罪を犯してしまいました。新聞がこの本よりも早く皆様にお伝えするでしょう……\n祂が、また、また始まって――\n（字が歪んでいる）\nいやいやいやいやいやいやいやいや、私はもう――\n……\n\n（字が再び明瞭になる）\n驚いたことに、祂が止まった。何かが祂を押さえつけたかのように。それが何なのか私には分からないが、その抗いに感謝しなければならない。\nあるいは神が私に最後の機会を与えてくださったのかもしれない。私が完全に悪魔に堕ちないように。\n\n私の銃には既に弾が込められている。\n神よ、私を赦したまえ。\n\n\n――作家クラーク・ジロスの絶筆作『影なき騎士』後記より抜粋"
  },
  AwakerStory_149052_Title = {
    Text = "物語·一"
  },
  AwakerStory_149052_UnlockDesc = {
    Text = "同調率レベル3達成で解放"
  },
  AwakerStory_149064_Content = {
    Text = "罪悪を象徴する深黒の泥は今も彼の体内で渦巻き、再びこの肉体を支配しようと企んでいる。彼はその脆い糸をひたすら握り続けなければ、敗れてしまうだろう。\nそして彼が自らのために新たに見出した――守るに値するもの――それが、理性を繋ぎ止める唯一の錨となった。\n彼はもはや故郷へ戻ることはできないが、ミサゴが彼の新たな城となった。\n彼はもはや姫君を守ることはできないが、運命はまた新たな出会いを生み出すだろう。\n誰も見ていない場所で、少年は片膝をつき、冷たい胸に片手を当て、ここにはいない主君に向かって誓いを告げた。\n「あなたの命に従い、あなたとあなたの世界を永遠に守護します。たとえ命を燃やし尽くそうとも、魂を使い果たそうとも。」\n「……これが、私が再び背負った誓いです。」"
  },
  AwakerStory_149064_Title = {
    Text = "物語·四"
  },
  AwakerStory_149064_UnlockDesc = {
    Text = "同調率レベル9達成で解放"
  },
  AwakerStory_149065_Content = {
    Text = "彼もかつて、寝る前の童話に書かれているように、自らの旅路に踏み出したことがあった。\nしかし彼は正義を讃える騎士ではなく、世界にはもはや救いを待つ姫君も存在しなかった。\n彼が斬り殺したのも恐ろしい邪龍ではなく、悲鳴を上げて逃げ惑う、武器を持たない多くの民だった。\n「若き騎士は邪悪な魔術師を斬り、頑強な敵軍を打ち砕き、怪物の城砦を焼き払った……\n彼は勇敢で、強く、無敵だった。果てしない道の上に、ただ長く続く血の跡だけを残しながら。」\n幻夢と現実の区別がつかない吟遊詩人がいたとすれば、きっとこの経歴をそのように粉飾したことだろう。\nしかし物語の主人公は実のところ、ずっと醒めていた。あの双眸には、偽りのものは一度も映ったことがなかった。\n彼は知っていた。自分の槍先が老人の胸を貫いたことを、黒い泥がすでに降伏した敗兵を飲み込んだことを、あの精巧な、ある家族のものだった小屋が、彼が通り過ぎた後に灰燼と化したことを……ただそれらが、彼の守るものを奪った者たちと関わりがあったというだけで。\n彼は知っていた。自分は童話の中にいたことなど一度もなく、あのロマンチックな幻想はとうに故国とともに完全に死に絶えていたことを。あの瞬間に大人になれたのかもしれないし、まだ未熟な子供のままだったのかもしれない。\nそして彼がついに目を覚まし、見知らぬ他人たちのために命を捧げようとした時、彼は突然自らの涙の中に、決して存在してはならない幻影を見た。\n「オジール、あなたにはがっかりしました。あなたは名ばかりの、最も不甲斐ない騎士です。」\n「姫君」の面差しは薄布に覆われているかのようにぼんやりとしていたが、その声は異様なほど鮮明で、世界中のいかなる刃よりも鋭く、彼の心を抉った。\nこの残酷な幻覚は今日に至るまで彼を苛む悪夢であり続け、死をもってしても消えることはなかった。\n彼は永遠に、誓いを裏切った悔恨の中に生き続けるだろう。"
  },
  AwakerStory_149065_Title = {
    Text = "物語·三"
  },
  AwakerStory_149065_UnlockDesc = {
    Text = "同調率レベル7達成で解放"
  },
  AwakerStory_60980_Content = {
    Text = "初めてハムリンを目にする者は、決まって東洋の磁器を想起する——白く、華麗で、優雅な曲線を描き、波紋のように揺れる穏やかな光沢を帯びながら、氷のように冷たい。\n\nその端正で精緻な、一分の隙もない外見の奥には、極めて純粋な、あるいは極めて空虚な魂がある。彼の人生は始めから終わりまで、ただひとつの念だけで貫かれていた——ひとつの命令だけを入力された機械のように、他のすべての反応を失って。\n\nすべては彼にとって、音符の配列と組み合わせに過ぎない。\n演奏、演奏、永遠に止まることなく演奏する。"
  },
  AwakerStory_60980_Title = {
    Text = "基本資料"
  },
  AwakerStory_60980_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_60981_Content = {
    Text = "ハムリンは学生たちの前に常に現れるわけではない。彼がミサゴで開催される音楽会に出席し、レベルの低い学生たちの音楽の授業を指導することを望んでも、ほとんどの時間、彼は防音の教室や人里離れた森で一人で演奏、あるいは練習している。\n正式な場を除けば、彼はすべての演奏を練習と呼び、それらの練習は永遠に終わらないかのようで、完璧な演奏は決して現れないかのようだ。\n「まるで永遠に学徒の心を持ち続けるような勤勉で謙虚な巨匠だ」と、すでにその音楽に陶酔している人々はこう称賛する。\nしかし、ハムリンは謙虚さを知らず、彼はいつも社交辞令を考えるのが面倒で、むしろ彼の言葉は常に直接的で、厳しすぎる。\n音楽に関して彼は最も深刻な強迫症を患っており、そのため音楽の授業という心を癒しリラックスさせる授業は学生の間で最もストレスの多いランキングのトップに立ち、ハムリン自身も悪魔教師の「美名」を得た。\nこの冷淡な音楽家の注目を得たいなら、演奏中に半音を間違えるだけで、その顔はすぐに眉をひそめてこちらを向く。\n実際、彼は「苦しめた」人々に何の意見も持っていない。ただ、その狂熱的な追求と基準を他人に押し付けているだけで、それでも彼が自分に対するものより遥かに寛容なのだが。\n彼は頭上にニンジンをぶら下げた仔馬のように、永遠に到達できない基準を自らに掲げている。\nあの優雅な舞踏家のために立ち止まったことを除けば、彼は他の覚醒体と積極的に交流することはほとんどないが、他人の助けを求める声や話しかけには、いつも驚くほどの忍耐を見せる。\n彼を阻むのは冷淡さではなく、あまりにも単一な知識の蓄積かもしれない。"
  },
  AwakerStory_60981_Title = {
    Text = "物語・二"
  },
  AwakerStory_60981_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_60982_Content = {
    Text = "A. F. 31@1年@1月@2日、音楽コレクションを愛する著名な富豪が、執事によって夜中に自宅の書斎で突然死しているのが発見された。体には傷や毒の跡はなく、口元には満足とも言える不気味な笑みが残っていた。\n警察の調査により、現場は密室状態と認定され、多くの刑事や法医学者の検査を経て、最終的に死因は事故死とされた。\nしかし、壮年で健康で馬術を愛する富豪が、なぜこのような平凡で静かな夜に突然死したのか、すべての医師が合理的な理由を出せなかった。家族の不満と脅迫を受け、最終的に警察は審査会に調査を引き継いだ。\n事を穏便に済ませたかった審査会は、富豪の机に散らばった楽譜から霊知の痕跡を誤って検出してしまった。この奇妙な楽譜はミサゴに送られ、研究の結果、この不完全な楽譜は有名な『イ短調レクイエム』の失われた後半部分に由来することが判明した。しかし、楽譜の最後のページは依然として完全ではなく、現場には多くの筆跡が狂乱した新しい楽譜の草稿が発見され、富豪が最後のページを補完しようとしていたようだ。\n研究の中で、楽譜に没頭する行為はさまざまな程度で狂気を引き起こすことが判明し、この楽譜はすぐに封印され保管された。ミサゴの学者によると、この補完行為が富豪の狂気と死を引き起こし、非常規の方法で覚醒儀式を完了させた可能性があると推測された。\nその後、長い間、校方はこの未知の覚醒体の出現や傷害の手がかりを見つけられず、この事件はミサゴの調査員たちによって徐々に忘れ去られた。\n音楽分野の学者たちだけが、封印された半分の楽譜の残篇に執着し続け、その伝説的なレクイエムの作者の出現を待ち望んでいる。"
  },
  AwakerStory_60982_Title = {
    Text = "物語・一"
  },
  AwakerStory_60982_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_60983_Content = {
    Text = "才能というものは、運命があまりにも稀少な偏愛を示すためのもののようで、彼は長い青春期の間、周囲の誰にもそれを見たことがなかった。それはある種の漠然とした意象となり、父親が自分を鞭打って前進させるための符号となっていた。\nだからこそ彼は、常に続ける勤勉さこそが完璧への階段だと信じていた。そして彼が世界の舞台の頂点に立ったときも、それは依然として変わらぬ真理だった。\n突然肩を並べて歩み寄ってきたその人に出会うまでは。\nそれはなんと眩しい天才だったのか、いわゆる才能の贈り物はすでに一人に独占されていたのだ。\n心の底から湧き上がる羨望と少しの嫉妬の中で、彼は突然言葉にならない迷いと無力感を感じた。\n自分にはそんなものがなくても、完璧な終点に到達できるのだろうか？\n歩んできた階段が突然灰に変わったようで、頭上の扉は依然として遠い。\n彼はしばしばその人を取り巻く群衆の外を彷徨い、あたかも高潔を装って独りでいるようだった。\nしかし彼はその方向を見つめるたびに、心の中で挨拶を繰り返し練習していた。\n平凡な蚊蝿のような者たちは常にその人の周りにいて、悪意のある囁きを放っていた。\n彼は本当に不器用な人間で、長い間沈黙し、弁解することができなかった。\nだから音楽を使おう、音楽だけが最も完璧な言語であり、その人は必ず理解するだろう。\n運命が突然、与えたすべてを元利ともに取り戻すまでは。\n天才は早逝し、凡人は長命。\nかつて背後での中傷や陰謀に彼は微動だにしなかった。\n今、机いっぱいの未だ渡せていない満足できない楽譜を見て、自分を憎んで涙を流した。\n彼は突然理解した、完璧な天国に到達する前に、人間の手段を尽くさなければならないと。\n幸いにも、凡人に比べて彼は十分な頭脳を持っている。\n結局のところ、彼の目にはすべてが音符のように並べられた計算に過ぎないのだから。"
  },
  AwakerStory_60983_Title = {
    Text = "物語・三"
  },
  AwakerStory_60983_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_60984_Content = {
    Text = "彼の生活は単調で、孤独こそが常だった。\n\n無念も、迷いも、怨恨も、長い歳月の中でとうに消え果てた。今や彼は音楽と一体だ——それは愛と呼ぶことすら超えた本能で、抗う術も、逃れる道もない。\n\n彼の持つすべては、もう音楽だけになった。\n\nあの九百九十九段の階段を振り返らずに、上へ進み続けよう。\n\n結局のところ彼はすでに、究極の音楽——運命に定められたあの笛の音に触れたのだから。\n\nどうかこの潮のように絶え間ない音楽を受け入れ、あなたの魂と夢に染み渡らせてほしい。\n\n彼もまたとうに、魂を楽器として捧げている——ただあなたと、深く響き合うために。"
  },
  AwakerStory_60984_Title = {
    Text = "物語・四"
  },
  AwakerStory_60984_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_66033_Content = {
    Text = "タヴィがミサゴに現れたのは三度だけ。\n最初は「知恵」の火種を啓示したとき。彼女は夢の通路を開き、無知の中で探求するミサゴの創始者に稀有な知恵を授けた。彼女はミサゴの最初の「智庫」と、融蝕に関する知識と手がかりを提供した。\n二度目は「変数」の予言をもたらしたとき。昏き海が沸き立ち、「変革」する者の到来を迎えた。\n三度目は「終末」の信号を伝えたとき。彼女の痛みと悲鳴が大地に響き渡り、避けられない混沌と破滅の到来を阻止することはできなかった。"
  },
  AwakerStory_66033_Title = {
    Text = "物語・二"
  },
  AwakerStory_66033_UnlockDesc = {
    Text = "同調率レベル5で解放"
  },
  AwakerStory_66034_Content = {
    Text = "カダスは彼女が守ろうとした唯一の夢ではない。\n彼女は多くの星や銀河の誕生と滅亡を目撃し、過去と未来の歴史は知識として蓄積され、彼女の背後の窮地の門に収められた。彼女は悲しみに満ちた目でそれらの光景を見下ろし、夢の中の一瞬の閃光となり、無限の深淵の暗闇に消え去った。\n彼女はある土地を踏みしめたが、振り返った瞬間に、彼女が大切にしていたすべての存在が「至高の意志」の息吹によって崩壊した。\n何度も繰り返した後、彼女はついに厳しい現実を悟った。彼女の存在そのものが悪夢の伏線であり、彼女のあまりにも巨大な存在が「無上意志」の目を引きつけるのだ。彼女の干渉は、彼女が気にかける世界にさらなる災厄を招くだけだった。\nだから彼女は退き、沈黙した。\n無限の空間の漂う意識の断片の中で、「彼」からの変数の可能性を目にするまでは……"
  },
  AwakerStory_66034_Title = {
    Text = "物語・三"
  },
  AwakerStory_66034_UnlockDesc = {
    Text = "同調率レベル7で解放"
  },
  AwakerStory_66035_Content = {
    Text = "ある神秘的な夢の中で、私は初めて彼女の姿を見た。\n濃霧に包まれた無限の空間で、彼女は無数の広大な宇宙をつなぐ壮大で不朽の門を守っていた。その深い門の裂け目の後ろで、奇妙な幻光が瞬き、何か未解読の情報信号を伝えているようだった。ある信号を捉えた瞬間、私は自分の体を失ったように感じ、茫然と星々の間を漂い、周囲は信じられないほどの暗闇に包まれていた。私は恐れ、驚愕し、夢は激しく揺れ動き、重い扉がゆっくりと抗えずに開き、無数の球体が星のように扉の背後で輝き、その深遠で計り知れない光景に眩暈を感じた……そして門の守護者——タヴィはただ永遠に無言で私を見つめていた。\n——ワード・フィリップス《シルバーキー手記》"
  },
  AwakerStory_66035_Title = {
    Text = "物語・一"
  },
  AwakerStory_66035_UnlockDesc = {
    Text = "同調率レベル3で解放"
  },
  AwakerStory_66036_Content = {
    Text = "知識の神子の代理人、門番として、タヴィは自分の本質を探求する欲望を持っていた。\n彼女は見守る人々のように地上を歩き、文明の変遷と歴史の変遷を目撃し、見たものすべてを「全知」という宝庫に収めたいと願っていた。しかし、彼女の存在は職務を離れることを許されないため、心の奥底では、自分の意志を少しだけ託した少女を最も羨ましく思っているのかもしれない……"
  },
  AwakerStory_66036_Title = {
    Text = "物語・四"
  },
  AwakerStory_66036_UnlockDesc = {
    Text = "同調率レベル9で解放"
  },
  AwakerStory_66037_Content = {
    Text = "タヴィは現在の世界には存在しない。\n彼女の存在は「無上意志」の注視を招くため、存在できず、存在してはならない。知恵と沈黙、それが彼女が探求者たちに与えられるすべてだ。\n日々の待機の中で、彼女は人類の運命に自らの知恵、勇気、無言の祝福を捧げている。"
  },
  AwakerStory_66037_Title = {
    Text = "基本資料"
  },
  AwakerStory_66037_UnlockDesc = {
    Text = "覚醒体を召喚する"
  },
  AwakerStory_76412_Content = {
    Text = "私はロバートが拳銃自殺するとは信じていません。そう、私は信じていません。\n\n彼は勇敢な行動でメダルを受賞し、多くの難解な殺人事件を解決した、心志堅固なベテランエージェントです。最も重要なのは、彼はすぐに結婚する予定で、彼女も彼に愛情を持っているので、ここには必ず陰謀があります！誰かが彼を殺して自殺の現場を装ったのです！\n\n犯人が誰であれ、私は彼を見つけ出し、代償を払わせるつもりです。それは弟として、エージェントとして私がしなければならないことです。\n\n……\n\n現場には全く手がかりがなかったので、私は故郷に戻らざるを得ませんでした。そこはロバートが自殺する前に訪れた最後の場所です。多方面から情報を集めた結果、彼が深山に入ったことがわかりました。\n\n彼があそこに入った理由は、地元の伝統に関係していると推測しています：各家の最初の子供は成人式の際に両親に山脈に連れて行かれます。\n\n私たちが子供の頃、両親がここを離れたため、ロバートはこの伝統を実践したことがありませんでした。彼は家族を持つ責任感が伝統への従順を呼び覚ましたのだと思います。\n\nとにかく、私は深山に行く必要があります。これらの言葉を書き終えたら、すぐに出発します。\n\n……\n\n山脈には壮大な建物が掘り出されていますが、それがどの時代のものであるかはわかりません。私には見分けがつきません。ただ、ここでは残酷な儀式が絶え間なく行われていることだけは知っています。あの残された肢体や虫の幼虫……うぅ、もうこれ以上は書けません。\n\n……\n\nこれらの虫の幼虫……いや、違う、彼らは私の祖父母ではない、私の曾祖先ではない……私は怪物の血脈を引いているはずがありません。ああ——\n\n……\n\n……私は儀式を行っている怪物たちに見つかりました。彼らは私を怪物に変えようとしています！\n\n……\n\nこの日記を見つけたら、私を殺してください、すぐに……@2\n\n……\n\n偉大な@2を称賛します、シッ@2……盲目的な愚かさを称賛します@4……シッシッシ……@1シッ……\n\n——故人の関与したエージェント@3の日記の抜粋、削除あり"
  },
  AwakerStory_76412_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_76412_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_76413_Content = {
    Text = "「ありがとう、クレメンタイン、私はずっと楽になった気がします。あなたはこの世界で私を最も理解してくれる人です。」\n\nクレメンタインの心理相談室を出入りする際、守秘者はよくこのような声を耳にします。患者や覚醒体が入る前はどうであれ、出るときは軽やかな足取りで笑顔を浮かべています。\n\nある時、守秘者が通り過ぎた際、クレメンタインが誤って相談室に入ってきた野良猫に心理相談をしているのを見かけました。\n\n結果は明らかで、心理相談を受けた人々は皆クレメンタインを褒め称え、その影響力は急速に広がっていきましたが、それと同時に問題ももたらしました——\n\n「守秘者、こんにちは。」\n\nクレメンタインはあなたの通り道に微笑んで現れましたが、あなたは驚きませんでした。彼女の絶え間ない通信器の音が全てを物語っています。彼女を信頼する患者たちは、知らず知らずのうちに彼女の耳目となり、直接的または間接的に彼女の目的を達成する手助けをしています。\n\n「私は思うに、もしあなたがこの街の市長になりたいと思っても、相談を受けた患者たちは無条件であなたを助けるでしょう。」\n\n守秘者の冗談に対し、クレメンタインは気にせず微笑みました。\n\n「私はそれに興味がありません。」\n\nそう、クレメンタインはそれに興味がありません。彼女が興味を持たないことは幸運です。\n\nさもなければ、心理相談で吐露された暗い秘密は、この街を混乱させるには十分です。\n\n「今は、あなたの心の奥深くの秘密を探りたいだけです、守秘者。」\n"
  },
  AwakerStory_76413_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_76413_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_76414_Content = {
    Text = "最初は、些細な苦しみが彼女を満足させることができた。\n\nしかし、甘美な渇望により、彼女は心理的な導きの中でますます多くの悪意を加えていった。\n\nこの悪意はまるで川のように蓄積し、奔流となり、次々と心の島々を浸水させた。\n\nしかし、それでも足りない。遠くおよそ足りない。\n\nただ古代からの長い夢が復興することで、全世界が苦しみの大海に変わり、究極の喜びをもたらすのだ。\n\nだから、彼女は興奮し、祈り、待ち望む。\n\nすべてが混沌となったとき、彼女は頭を低く伏せ、この世で最も極致の哀しみを喜んで味わう。\n\nたとえこの苦しみの大海が彼女を溺死させるとしても。\n"
  },
  AwakerStory_76414_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_76414_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_76415_Content = {
    Text = "誰もが異なる人格の仮面を持っていて、彼女は最も人の心を麻痺させるものを選びました——\n\n彼女は優しく微笑み、微笑みながら話し、どの表情もどの言葉もとても心地よく、心理相談に来た患者たちに、心の底から生涯の理解者と導き手に出会ったと感じさせます。\nそれで十分です。\n\n運命的に滅びる蛾は結末を知る必要はなく、彼女の導きに従って進むだけでいいのです。\n\nその一見温かい救済の中で、烈火に焼かれ、もう振り返ることはできません。\n"
  },
  AwakerStory_76415_Title = {
    Text = "基本情報"
  },
  AwakerStory_76415_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_76416_Content = {
    Text = "実際、本物のクレメンタインは、失われた偉大な意志が寄生した瞬間にすでに死んでいた。\n\n血肉の残骸で満ちた祭壇から破茧したのは、偉大な本質を持ち、人間の生命を遥かに超えた新生者である。\n\n新しい生命、古い記憶。この惑星から育まれた身体は、宇宙の深淵から生まれた魂である。\n\nこのように矛盾に満ちた存在は、クレメンタインを混乱させたが、すぐに魂からの飢えが彼女を考えられなくさせた。\n\n人間の食べ物は非常に味気なく、痛みの記憶だけが少しは口に合う。そして、その記憶が苦痛と絶望に満ちるほど、味わいはますます甘美で美味しくなる。\n\nその瞬間、彼女は自分の生存方法をついに理解した。\n\n「私に語りかけて、苦しみでも、絶望でも、すべてを私に見せて。」\n\n彼女はデスクの後に座り、相談に来た患者を悪意を持って見つめ、顔には優しさが満ちていて、誰でも心の防御を解くことができる。\n\nそれは昆虫が狩りをする際の擬態と仮面である。\n"
  },
  AwakerStory_76416_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_76416_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_81334_Content = {
    Text = "カストルとの関わりは通常、二つの奇妙な極端を呈します。\n表面上見ると、あまりにも真面目で堅実な性格は、まるでレンドニエン銀行で20年間働いている中年の職員のようです：堅苦しく、風情を解さず、退屈な仕事にすべての活力を奪われているかのようです。彼が真剣な顔をする時、確かに怒らなくても威厳のある聖子の気質があります。\nしかし、少し深く接触すると、彼の一見古風な行動はすべて、あまりにも少ない常識と無比の鈍感さ、そして真っ直ぐさから来ていることがわかります。彼は誰かが言った冗談を完全に真に受けてしまうことさえあります。\n彼はしばしば分厚いノートを持ち、守秘者をつかまえて根掘り葉掘り尋ね、まるでまだ幼児のように言葉を覚えたばかりの子供のようです。そのあまりにも真摯で誠実な視線に直面すると、大多数の人々は彼の無知な質問に対して軽蔑の言葉を口にするのが難しいのです。\n様々な信仰に関する経典を除いて、カストルはどんな新しい知識にも貪欲に求め、特に現代社会や現代科学に関することについては、彼は実験研究に強い興味を持ち、熔毁・ドールに無情に無視された後、可哀想なウインクルを毎日逃げるように追い詰めます。\nもし学校の教室に座っていたら、彼は教師に好かれる勤勉な学生のタイプであり、学ぶことは苦痛だとは思わず、興味のある知識を自由に吸収できることを心からの幸せと感じています。\nただ、教師の喜びに比べて、ある種の自慢好きな覚醒体は、こうした論理的な無限の問いに直面すると、答えられないことで恥をかいて怒り出し、頭を抱えるカストルだけが学びの奥深さと困難さ、長い道のりを感じることになります。"
  },
  AwakerStory_81334_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_81334_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_81335_Content = {
    Text = "普通の家庭に生まれていれば、カストルは言葉に不器用だが、木のように親しみやすく、堅実な青年に成長したかもしれない。しかし今、彼は双子の中で唯一、完全な身体と魂を保っている者であり、石のように静かに待ち、少年時代に二人で共有した火種を心の中に埋め込み、決して諦めず、決して揺らぐことがなかった。\nその成熟した、嵐を巻き起こすことができる二つの翼は、潜伏して収束し、一羽の鳥が静かに檻の扉が開くのを待ち、再び空を飛ぶ瞬間を待っている。"
  },
  AwakerStory_81335_Title = {
    Text = "基本情報"
  },
  AwakerStory_81335_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_81336_Content = {
    Text = "私は、レンディニエンから非常に遠く離れた、貧弱さゆえにほとんど知られていない高原で任務を遂行しているとき、わずかに残った住民がいる山村で、驚くべき事例を発見しました。\nそのモンスターが現れた夜、空は何か奇妙な影に覆われ、霧が地面を流れ、雲の奥には淡い緑色が浮かび上がっていました。それは単なる自然現象ではなく、生きて呼吸している生命の投影でした。\n高い木々がそびえる荒れ果てた山脈の奥深くから、突然怒号や咆哮のような音波が響き渡りました。それはどの生物にも属さない叫び声で、人々の本能の最深部にある恐怖を呼び起こします。\n巨大な影が瞬時に飛び過ぎ、山全体がその遮るような影に揺れ動き、すべての木々の枝葉も一緒に震え、整然とした呟きのような音を立てました。\n「私は見ました！長くて密集した触手、緑の光を放つ目、それは絶対に天にいるあの恐ろしい影の源です。私を見つけ、しっかりと私を見つめています！私は本当にその瞬間に私の命が終わると思いましたが、もしかしたら彼はちょうど食事を終えたばかりで、私が窒息して意識を失う前に、彼は大慈悲をもって振り返って去って行きました。」\nこれは正式な目撃者への唯一のインタビューであり、今なお悪夢に深く陥っている村人は、これ以上の詳細を思い出すことを拒否しています。しかし、既存の兆候から観察すると、この巨大な暗緑色のモンスターは、ハリケーンが通過したかのように一部の山林を破壊し、わずかに血痕の残る野獣の骸骨を残しただけで、より大きな攻撃性を示していません。まるで普通に食事をしている野獣のようです。おそらく彼が村落に近づいた行動は、単なる好奇心からののぞき見に過ぎません。\nしかし、未知の恐怖に直面した際、我々は明らかに最悪のシナリオを考慮する必要があります。私は@3高原で半月間の調査を続けます。他に注意すべき危険な兆候があれば、随時任務報告に補足します。\n\n——《ミサゴ境外調査ノートA.F.3@2年総録》"
  },
  AwakerStory_81336_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_81336_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_81337_Content = {
    Text = "自由を追い求め、教会から逃れる代償とは何か？双子は恐ろしい刑罰を想像し、さらには自分の命を失うことまで考えたが、彼らが想定していなかったのは、最も苦痛を伴うのは肉体的な苦しみではなく、魂への剥ぎ取りの刑であることだった。\nカストールは、波リュクスが自分にとって非常に大切な、活き活きとして美しい翼を無理やり引き裂かれるのを目の当たりにし、唇は自分の歯によって噛み砕かれていた。彼は狂気と罪悪感の中で待ち望み、さらには同じ痛みが自分にも降りかかることを渇望していた。\nしかし、ジュリエットはただ手を振るだけで、重傷を負ったカストールはそのまま完全に連れ去られ、融触液で満たされた水槽に投げ込まれ、「罪悪療法」が施されることになった。\n黒い粘液が傷ついた身体を浸し、あらゆる傷口に浸透し、すべての羽毛を覆い、カストールはますます息苦しくなった。\n傷口が繰り返し腐食し、また治癒していく中で、カストールのぼんやりとした頭の中には抜き取られた翼が渦巻いていた。彼は狭い囚われの中で焦燥しながら座り続け、弟のためにすべての苦しみを引き受けたいと願った。彼はあの日、自分が翼を抜かれる人であったならどんなによかったかと想い、そして後に、必ずこの翼で弟を自由へと飛ばすのだと固く決意した。\nカストールはこの地獄のような水の中で日々を耐え忍び、苦痛の中で時間を正確に感じることができなくなった。数十年待っているかのように感じ、カストールがほぼ死にかけたとき、漆黒の地獄から再び這い上がったとき、彼の急かすような目と対峙したのは、冷たく見下す視線だった。\n「その気持ち悪い目をしまいなさい。もう一つ忠告しておくが、カストール閣下、あなたと私はただ光の持ち主の聖子に仕える者に過ぎない。人前では無用に親密になる必要はない、ただの厄介だ。」\nカストールはなぜ弟が自分を完全に忘れてしまったのか分からなかったが、罪の池を離れる時、ジュリエットのあの意味深長な視線が何を意味していたのかをようやく理解した。彼女は自分を最もコントロールできる首輪をしっかりと手に持っているのだから、恐れることはない。"
  },
  AwakerStory_81337_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_81337_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_81338_Content = {
    Text = "双子は生まれながらにお互い以外は何も持たないが、カストルは失うことの味わいをずっと味わっていた。\n傷つけられ、忘れ去られ、裏切られたその静かな心は鉄のようではないが、彼は何度も立ち上がり続けた。\n「でも大丈夫、私はあなたの分も一緒に頑張る。」カストルは面目を失った弟を見つめ、盲目的に信じていた。\n彼の心の中には微弱な炎をしっかりと握りしめ、刃のような風雪に逆らって進み続けた。\nいつか彼は自由の山頂に登り、翼で低く垂れた空の幕に触れるつもりだ。\n彼はその茨の道の果てに、子供の頃に弟が約束した明るい光があると信じている。"
  },
  AwakerStory_81338_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_81338_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_81615_Content = {
    Text = "彼女は船が航行する際に高く翻り、方向を示す旗であり、船が沈むときには最後の瞬間まで責任を果たす挽歌でもあります。\n\n彼女の責任、彼女の義務、彼女の命は船に結びついており、他には何もありません。\n\nなぜなら、航路を示すことが彼女の存在の意味だからです。\n"
  },
  AwakerStory_81615_Title = {
    Text = "基本情報"
  },
  AwakerStory_81615_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_81616_Content = {
    Text = "話すことを学ぶ前に、クーパサントはクルーズ船で育ち、すでに波が船に打ち寄せる音の音節を模倣することができました。\n\n時にはその音節は「シャー」という音で、時には「ドーン」という音で、まるで自然が彼女に歌う子守唄のようで、彼女は安心し、親しみを感じ、憧れを抱きました。\n\n彼女はいつも他の人よりも早く海の「気性」を理解し、いつも他の人よりも早く雲の「言語」を読み取ることができ、皆は彼女を生まれながらの「パイロット」と呼びました。\n\n実際、初めてこの言葉を聞いたとき、幼いクーパサントは理解できませんでした。彼女はただ本能的に自分を受け入れてくれた船長や水夫たちを助けたいと思い、彼らを嵐や他の船の災害で失うことなく安全に帰らせたいと思っていました。\n\n彼女の願いを理解したパイロットは言いました。「パイロットになりなさい、クーパサント。パイロットになり、自分の責務を果たせば、あなたの願いは叶う。」\n\n幼いクーパサントは頷き、そのパイロットが彼女の師匠となりました。彼は星空の観測方法やセクスタンの調整方法を教え、パイロットたちが代々口伝えにしてきた歌を教えてくれました。その不吉な歌を。\n\n「私は塩水に抱かれたくない、それはとても冷たいから、またリン火になりたくもない。」幼いクーパサントは異議を唱えました。\n\n彼女の師匠は何も教えず、ただ彼女の頭を撫でて微笑みました。\n\nなぜなら、時間が「パイロット」の責務の意味を教えてくれるからです——\n\n彼女は深い海の上で、唯一の指針、唯一の希望です。"
  },
  AwakerStory_81616_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_81616_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_81617_Content = {
    Text = "誰もその幽霊船がどこにあるのか知らず、「それ」が本当に存在するかどうかも誰も確かめることができない。現在私が持っている唯一の手がかりは、何か奇妙な魔力を持っているような象牙の頭部彫刻だけだ。\n\nそれを手に入れて以来、私は毎晩同じ夢を見ている。そう、どこにあるかわからない幽霊船の夢だ。「それ」の船体は生き物のようにうねる輝光を燃やしていて、凡人には知りえない次元へのドアのように見える。目が覚めても、私はあの亵渎的で病的な低い囁きを覚えている。\n\n私は自分が狂ってしまったり、これらの奇妙な、人間には絶対に発音できない音節を忘れられたらいいのにと思うが、そうはいかない。\n\nそのくそったれな夢、そのくそったれな知性の輝光が私を苦しめるので、私は「それ」を探しに行かなければならない。象牙の頭部彫刻の導きの下で。幸運なことに、ミスカトニックの教授たちが私と共に同行し、幽霊船と聖エルモの火を共に探検してくれる。彼らはその蠕動する輝光をそう呼んでいる。\n\n私に幸運を。主が私たちを守ってくれますように。\n\n——『ミスカトニック超自然現象調査ファイル』より抜粋"
  },
  AwakerStory_81617_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_81617_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_81618_Content = {
    Text = "コーパサントの日課は非常に固定されており、特定の時間に特定の場所に行けば彼女を見つけることができます。\n\n一般的に、コーパサントは6:00に起床し、冷水浴と体操を行います。7:00は朝食の時間で、オートミール粥や漬け魚に加えて大量のカフェイン補助剤を提供する必要があります。\n\n9:00から12:00はコーパサントの学習時間で、彼女はこの期間に海図を修正したり、機器を校正したりします。授業の鐘が鳴ると、コーパサントは屋外に出て旗を振って交通整理を行い、昼食時の学院の道路の混雑を大いに緩和します。\n\nコーパサントの昼食時間は「交通状況」に依存しますが、遅くても12:30を過ぎることはありません。短い休憩の後、14:00にコーパサントは海辺に現れ、風向きと気候を観察します。この時、コーパサント、ファロス、シレストの動向に注意し、彼女たちが博物館の模型船を「徴用」したり、通行人を海に誘ったりしないように注意する必要があります。\n\n19:00は夕食の時間で、長期間の航海によって破壊された睡眠周期を麻痺させるために、コーパサントは大量のアルコールと睡眠助剤を摂取する必要があります。そうしなければ、彼女は22:00に成功裏に眠りにつくことができず、航海中に発生する可能性のある「事故」に対処するために自分を覚醒させ続けます。\n\nこれによって引き起こされる状況には、聖エルモの火現象の制御不能、地域全体が昼のように明るくなること、または地域の電圧異常、制御不能、機械の異常運転、火災などが含まれます。\n\n<Red:注意、この期間中は絶対にエリカとコーパサントを接触させないでください！>\n\n最後に批評のお知らせ：\n\nコーパサントが到着した後、ウインクルは何度もコーパサントの胸元の@2を光源として抽出し、研究しようとしました。口頭での批評が行われましたので、異常を発見した場合は必ず守秘者に知らせてください。\n\n――守秘者%player%"
  },
  AwakerStory_81618_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_81618_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_81619_Content = {
    Text = "最後の瞬間まで、コーパサントは自分の責務を果たそうと努力していたが、彼女が操縦していた船は沈没してしまった。\n\n夜が深く静まり返ると、彼女は亡くなった乗客たちの夢を見る：海水が船室に浸入し、海の怪物の触腕が横行し、誰かは溺れ、誰かは海に飛び込み、誰かは最後の導きを求めてひざまずくが、それでも希望は破滅する。\n\nこの残酷な現実は彼女を責め、苦しめている——彼女は自分の職業を冒涜した。\n\nそのため、彼女は罰を受けなければならず、彼女に生涯まとわりつき、彼女を苦しめる雷は、懲罰である。しかし、それだけでは足りず、彼女は自分の職務怠慢の贖罪をしなければならない。\n\n幸いなことに、その偉大な存在は答えを与えた：神国が降臨すれば、世の中のすべてが楽土に変わる。\n\n「では、永遠に尽きることのない海の咆哮を鎮めるために、海に葬られた無実の者たちのために、全ての生きとし生ける者の方向を指し示すために、神国の降臨をお願い申し上げます。」\n\nこれは彼女の最後の、最終的な航海である。\n"
  },
  AwakerStory_81619_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_81619_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_95006_Content = {
    Text = "■ファイル番号：DIOL-A3-27\n■覚醒体コード：■■■■\n\nこの覚醒体(以下、ケティグラと呼称)の行動習慣、処事スタイル及び異なる任務に対する態度に基づき、調査員は関連する推測を行い、その後詳細な調査を展開しました。以下の内容を同期します：\nケティグラは@2地域の孤児で、幼少期に両親に捨てられました。\nケティグラは未知の手段を用いてこの地域で生き延び、多くの悲惨な境遇の子供たちを受け入れました。注意が必要なのは、この過程には大量の血腥さと暴力的手段が含まれていることです。明確に記録された中で、調査対象はある受け入れた子供の家族全員を残忍に殺害したことがあります。\nその後の長い間、ケティグラとその手下の主要な経済源は、不可視者からの依頼を受けることでした。例えば、ギャングの復讐、抗争、密売品の略奪などの「黒い」行為です。\n地元の人々の口述と、この地域のデータをもとに、ある時点でケティグラとその受け入れた子供たちを中心とした団体が、この地域のほとんどの黒い組織を統合したと推測されます。\nケティグラがどのように覚醒体になったのかは現時点では不明ですが、提灯教会の拠点が破壊された時期は、彼が覚醒体になったと推測される時期と一致します。彼の提灯教会に対する嫌悪感から、覚醒体になることと提灯教会との関連性が合理的に推測されます。\n不完全な統計によれば、現在までに43の提灯教会の拠点が彼によって破壊され、その中には7つの大型拠点、12の降神祭壇、17の実験場が含まれています。\n\n上記の調査報告及びこの覚醒体の日常活動行動を参考に、委員会は名誉会長K・トラッキの提案に基づき、ケティグラの危険度評価を再評価しました。評価結果を記録します：\n全委員の判断によれば、この覚醒体はミサゴに対して直接的または間接的な脅威を持たず、現行の協力条約が変わらない限り、その存在及び行動に干渉する必要はありません。\nしたがって、ケティグラをDIOLから除外し、彼に関連するすべての調査行動を凍結し、すべてのファイル内容を完全に封印し、Ωレベル未満の者が閲覧することを禁止します。\n\n記録者 K・トラッキ\n(ファイルの下部に書かれた小字)\nおめでとうございます！ついにあの恐れおののく連中がこのくそったれなプロジェクトをキャンセルさせました。これまでの時間を無駄にすることはありませんでした。\nこれがケティグラさんに関する最後の記録です。今後、特に問題がなければ、この番号に新しいファイルが追加されることはないでしょう。ですから、誰であれ、今このくそったれなファイルを閉じて、新鮮な空気を吸いに出かけ、もっと注目に値する対象にエネルギーを注いでください！\n——カルラポリス・トラッキ、あなたの社会的な暇人の友人。"
  },
  AwakerStory_95006_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_95006_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_95007_Content = {
    Text = "■ファイル番号：DIOL-A3-1\n■覚醒体コード：■■■■\nA.F.3@2年、この覚醒体は自らミサグと接触を試みた。\n\n「太陽！太陽！私は太陽を見た！いや！いや！！それを壊せ！さもなくば私たちは死んでしまう！」\n\n目撃者の話によれば、当事者はこの覚醒体を発見した際、叫びながら上記の発言をし、その後関連部隊に攻撃を命じた。\n\n当事者の誤判断により、この覚醒体は極めて高い攻撃性を示し、直接的に31組の反覚醒体装置、76組の通常装備、2棟の教室が破壊され、合計財産損失@2@4が発生し、現在は関連部門に引き渡されて責任追及が行われている。\n\n事後調査の結果、当該人物は提灯教会に洗脳されていたことが判明した。今後の状況については関連文書を参照してください。本ファイルでは述べない。\n\nしばらくの交流の後、交渉担当者はこの覚醒体に対し攻撃態勢を解除させることに成功した。その後、この覚醒体はデクスター勲爵の署名がある手紙を校側に渡し、ある失踪した調査員の遺品だと主張した。後にデクスター勲爵によって、この手紙は確かに彼が書いたものであると確認された。\n\n現在、ドール教授の協議により、この覚醒体は校側と何らかの合意に達したことが知られている。校側は何らかの不明確な報酬を代償に、この覚醒体に校側が扱いにくいまたは不便な委託を引き受けさせることを得た。\n\nこの覚醒体が示した破壊力を考慮し、たとえこの覚醒体がその後の会話において最高レベルの安定性とコミュニケーション能力を持っていたとしても、委員会は依然としてこれをDIOLに登録し、最高の規格で継続的にファイル更新を行うことを決定した。\n\n銀の鍵が私たちを導きますように。\n\n記録員 L・ナディア"
  },
  AwakerStory_95007_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_95007_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_95008_Content = {
    Text = "(ファイルの冒頭に書かれた小さな字)\nくそ、どうやってこのファイルを見つけたのか、私は明らかに誰にもこのものを調べることを禁止していたのに…………まあいい、あなたがこのファイルを見ているということは、あなたの権限が私をはるかに上回っているということだ。つまり、あなたはその数名の一人であり、私にはあなたがこれらのことを知るのを阻止する権利はない。\n\nしかし、どうか覚えておいてください。このファイルはどこにも存在してはならないものであり、以下の内容は正式な調査ではなく、私の個人的な現実に基づく二次的推論から成る非公式な産物です。\n\n私はあなたに厳重に警告しなければなりません。このファイルの記録過程には、詳細に説明できない調査方法、個人的な思考の主観的な推測、調査対象からの賄賂を受け取る行為が含まれています。私の上記の行為が気にならないのであれば、読み続けてください。私は私の人格を保証します。以下の内容には明確な真実性があります。\n\n■ファイル番号：■■■■-A■■-SSS\n■覚醒体コード：爆燃の主\n「私は実際には争いを好まない。」\nこんな答えを得るとは思ってもみなかった。なぜなら、すべての報告書では、調査員は彼女の戦闘を描写する際に「発狂」「歓喜」「興奮」といった言葉を加えるからだ。\n私は彼女が戦闘に対して「積極的ではなく、嫌悪せず、拒否もしない」と考えていると思っていたが、彼女はこのような事自体に嫌悪感を抱いているとは思わなかった。\n会話が進むにつれて、私はいくつかのことを徐々に理解するようになった。私がこれらの内容を記録しても良いか尋ねると、ケティグラは快く私の行為を許可してくれた。\n\n「あなたが知っておくべきことは、世界の大部分の人々にとって、生きることは贅沢だということです。」\n私はこの言葉に同意した。私や私が接触したほとんどの人々は恵まれた生活を送っているが、私はこの世界の真実の姿をはっきりと知っており、私の恵まれた生活の背後にはどれだけ多くの人々が重荷を背負っているかを理解している。\n\n「だから、多くの場面で、強い闘争心は生き延びるための報酬なのです。」\n「私たちは生活の仕方を選ぶことができません。一度泥沼に足を踏み入れたら、抜け出すことはほぼ不可能です。」\n私はこの見解に反論しようと思ったが、いくつかの事例を思い返してみると、彼らは一般人ではなく、無名の人々はほとんど彼らの回想録の中にしか存在しないことに気づいた。\n「おそらく、少し無邪気な人は『それなら、最初からやらなければよかったのでは？』と言うでしょう。この考えは素晴らしいもので、私はかつてそれをある墓に刻み、これを実行した人を記念しました。」\n「この残酷な世界で皆を守るためには、私は十分に強く、発狂した姿を見せなければなりません。そうすることで、あらゆる悪意が私を恐れることになるのです。」\n「もちろん、戦闘中に見せる感情は虚偽ではなく、私は実際に戦闘がもたらす感覚を楽しんでいます。」\n「おそらく理解しづらいかもしれませんが、これはあなたが仕事の内容を好きでも、仕事そのものを好きではないのと同じです。」\nこの説明を聞いた後、私は彼女の言葉の意味をすぐに理解した。確かに、私は仕事の中で他人のプライバシーをのぞき見することが好きだが、それは毎朝8時にベッドから起き上がり、命令に従ってどこかに一日中いることを好むわけではない。\n\n「私が捨てられたばかりの頃、私は多くの女の子と同じように、迷い、ためらい、どうすればよいかわからなかった。」\n「私は他人の助けを求めたが、世界が私に与えたのは数えきれない裏切りと痛みだけだった。」\n「徐々に、私は残酷さと発狂をもって悪意を防ぐ鎧を構築し、毒を飲んで渇きを癒すようにこの世界に適応していった。」\n「そして最後には、それらが永遠に絶え間ない炎の中で溶け、私の血肉と一体となった。」\nまるで先ほどの発言を証明するかのように、ケティグラは瞬時に極度に残忍で邪悪で発狂した笑顔を見せた。私は恐怖で淡黄色の液体を杯から自分にこぼしてしまった。\nああ、もしかしたらこれは良いことかもしれない。なぜなら、もし本当に筋肉の制御が効かなくなり、何かの液体が漏れた場合、さっきこぼした飲み物のせいだと自然に説明できるからだ。\n去る際、ケティグラは私の質問に正面から答えることはなかったが、私は以前の判断が正しいことを確信した。彼女は確かにDIOLに存在すべきではない。\n——記録者 カラポリス・トラック\n\n「私の最初の願いは、ただ家を持つことでした。」\n「裏切りも痛みもなく、笑い声に満ちた家。」\n「残念ながら、あの日まで私は理解しませんでした。」\n「それはこの残酷な世界において、最も贅沢な妄想です。」\n——ケティグラ"
  },
  AwakerStory_95008_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_95008_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_95009_Content = {
    Text = "ケティグラは彼女の象徴的な笑顔を使うのが得意で、すべての注視者の意識の最深部から、残忍で狂気に満ちた冷気を滲ませる。\nその二丁の銃は互いに離れず、銃口にまとわりつく火薬の塵が、すべての妄念に囚われた小者たちに警告を発し、無名者の犠牲がすべての偉大な基礎であることを示す。\nしかし、彼女と関わったことがある者は、狩りをするのは日常の退屈を紛らわせるために、光に照らされない平凡な人々を狩ることに過ぎないと理解するだろう。\n結局、彼女が本当に発砲するとき、銃口には火薬がないのだ。"
  },
  AwakerStory_95009_Title = {
    Text = "基本情報"
  },
  AwakerStory_95009_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_95010_Content = {
    Text = "■ファイル番号：DIOL-A3-9\n■覚醒体コード：■■■■\n\n継続的な観察により、この覚醒体はミサゴに対して異常な関心を示しておらず、むしろ興味がないと言える。彼女は委託を受けた時だけ校内に来て、すぐに去ってしまう。\nただし、報告された調査結果によると、この覚醒体には数回長時間キャンパスに滞在した記録がある。\n\nしかし、その後の調査によると、主な滞在理由は学生の問題を解決する手助けであり、安全上のリスクはなく、干渉の必要はないと判断されている。\n\n注意すべき点は、この覚醒体が守秘者に対して他の人よりもはるかに興味を持っているようで、何度も守秘者に禁止物品の@3を持参し、参加者が不明な様々な晩餐会に招待している。守秘者の重要性を考慮し、この覚醒体が守秘者に対して危険な行動を取ろうとしている場合、少なくとも4名のγ級武装要員を配置し、守秘者の安全な撤退を確保する必要がある。\n\n記録者 K·トラッキ\n\n(ファイルの裏面に書かれた小さな字)\nヘイ、兄弟、もちろん姉妹かもしれないが、それは重要ではない。\n前の不運な奴はすでにこの仕事を放り出したので、今はこのクソプロジェクトを私が担当することになった。\nもしこれを見ているなら、君はただ生き延びるだけの奴ではなく、観察力のある人間だ。自分を褒めてあげてほしい。\n聞いてくれ、私たちは「暗中監視」をしていると言い続けているが、彼女はすでに私たちに気づいていると思う。ただ、無視しているだけだ。\nなぜ私たちがこんな人を監視しなければならないのか理解できない。最初の接触には誤解があったが、それはカルト信者のせいで、彼女本人には何の関係もない。\nそれに彼女はその学生たち、特に守秘者との関係は、比喩的に言えば、祖母が孫にお菓子を買ってあげるような関係だ！誰もが毎日自分の祖母が自分をカルト信者に生け贄にすると思うわけではない…………いや、待て、もしかしたらどこかで本当にそういうことがあるかもしれないが、それは重要ではない！\n重要なのは、もし彼女が本当に何かを企てているなら、私は保証する、事態はいつの間にか進行しているだろう、委員会がゆっくり研究している間に。\nふぅ、愚痴を言うのは気持ちいい、要するに、私は彼女をこのリストから外す計画を立てている、委員会が本当に彼女にとって許しがたいことをする前に。\nあの連中が本当に彼女を怒らせたら、私は保証する、2棟のビルだけでは済まなくなるだろう。その時にはもう死んでいることを願うが、そうでなければ私は非常に苦しんで死ぬことになるだろう。\nもし君が彼女を監視することになったら、覚えておけ、過激な行動はするな。彼女が嫌いなら、学校の汚れ仕事をする雇われ者として扱えばいい。相手が不安定な状態を明確に示さない限り、絶対に正面衝突は避けろ！\nもちろん、もし小さな贈り物が欲しいなら…………彼女は君が以前彼女を監視していたことを気にしないはずだ。大胆に頼んでみろ、正直に言うと、彼女のポケットの中のお菓子は本当に美味しい。\n——カラポリス・トラッキ、君と一緒に委員会を罵る友人。"
  },
  AwakerStory_95010_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_95010_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_95094_Content = {
    Text = "彼の一生は操られた糸の下で生きており、早くから書かれた脚本は滑稽な嘘で、彼は絶えず失い、忘れ、逃していった。\n若い頃、彼が最も渇望していたのは、自由に翼を振り回し、その湖の向こうの世界を見に行くことだった。\nその願いのためにすべてを失った後、彼はあのように軽やかで無邪気な生活をすべての夢として考えることができなくなってしまった。\n果てしない怒りがその真っ黒な心臓を燃え上がらせ、彼の胸に渦巻く血の痛みと憎しみは、偽信者たちの死によってしか洗い清めることができなかった。"
  },
  AwakerStory_95094_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_95094_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  },
  AwakerStory_95095_Content = {
    Text = "波リュクスの「聖心」と提灯教会の降神の儀式との関係の可能性を考慮し、ミサグは「聖心」に対して一連の検査と実験を行う研究グループを組織した。\n波リュクスが残念に思ったのは、この「聖心」が彼の元々の心臓の機能を完全に代替し、彼の体に融合してしまったため、直接摘出または交換することができなかったことである。\n観察実験の中で、研究者たちはこの形状が瞳に似た「聖心」がしばしば波リュクスの意志とは無関係に微妙な震えや回転を生じることを発見した。それはまるで本物の目のようであった。\nしかし、光源テストを経て、「聖心」には視力に類似した機能が存在しないことが証明された。このような活動は、他の生物や物品への感応によるものであるように思われた。\n異なる物品の配置の対照実験では、融蝕や銀芯に関連する物品に近づくことで「聖心」の活動がより容易に引き起こされ、融蝕生物や覚醒体の前では「聖心」の活動が特に顕著であった。\n波リュクスが「聖心」の力を積極的に使用した際、普通の物品の物理的および化学的性質には何の変化も見られなかったが、融蝕物品や生物の前では驚異的な融蝕拡大現象が発生した。本来融蝕段階の初期にあった動植物は、肉眼で見えるほどの速度で発展段階を過ぎ、急速に融蝕末期の状態に移行した。動植物が受ける融蝕が深刻であればあるほど、このような拡散はより迅速であった。\n厳重な保護措置を講じた覚醒体実験では、「聖心」の力に直面した際、覚醒体は何らかの暗黒が迫る危険な気配を感じたため、実験は迅速に中止された。波リュクスも校側の厳正な説明の下で、聖心の力を覚醒体に対して使用しないことを保証した。\n波リュクスが非常に協力的な態度と優れた自己制御力を持っていたため、ミサグは波リュクスに強制的な管理具を装着することはなく、定期的に体検査と力の使用訓練を行っただけであった。\n実験結果を聞いた温柯尔は叫び声を上げて気を失いそうになり、自分の実験室と宿舎のドアに波リュクスが近づくことを禁止する掲示を貼り付けた。校側は何度も説得を試みたが効果はなく、波リュクス本人は温柯尔の要求を尊重する意向を大らかに示した。"
  },
  AwakerStory_95095_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_95095_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_95096_Content = {
    Text = "運命の神の最初の構想では、彼はおそらくこの世に生まれるべきではなかった。\n最初に人工双子実験から生まれたのはカストル一人だけで、この無知無覚の胚胎が処理され捨てられようとしたとき、ポリュクスはもがきながら、兄の血肉からねじれ引き裂かれて生まれた。彼は彼の命を吸い取り、彼の命を救った。彼らの血肉、魂、運命はこうして絡み合った。\n退屈な教会の修行の中で、二人の生活と運命は本来無二のものであったが、「神聖改造」儀式の始まりが、痛みと無情な苦しみによってポリュクスを聖子の宿命から目覚めさせた。二人の子供は生涯で最も大胆な壮挙を成し遂げた。彼らは一冊の古びた書籍を手に取り、世界の地図を描き出し、そして虚偽の世界から幻想の世界へと逃げた。\n脆弱で短命な美夢が破れた後、残酷な罰は彼らの魂を打ち砕くことはなかったが、その宿命の残酷な分岐によって彼らは二度と会うことができなくなった。\nジュリエットは二人を分けて供養するよう命じ、罪の池にいるカストルは知らなかったが、二人の想像した拷問はポリュクスには実施されていなかった。ジュリエットはほとんど慈悲深く残りの罰を終わらせ、すぐにポリュクスを禁閉された暗室から解放し、厳格で集中的な神学の教導に投じた。\nポリュクスの心の中の屈服と疑念は、ジュリエットの絶対的に冷静な視線に直面したとき、ある種の不安と恐怖に変わった。彼女は彼が抗うことのできない何かを掌握しているに違いなく、だからこそ彼女はこのように悠然としていた。\n彼はもがき、偽装し、決して諦めなかった。彼は多くのことをしたように思えた…………しかし、彼は何をしたのか？鏡の中には、忠実に聖子の冠をかぶった見知らぬ魂だけが残されていた。\n彼と彼らの記憶は、すでに完全に忘れ去られていた。"
  },
  AwakerStory_95096_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_95096_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_95097_Content = {
    Text = "彼は奇形の血肉であり、裂かれた後に縫い合わされた肌、空洞の胸郭、汚濁した心臓、そして無形の鎖から構成されている。\n彼は高台に担ぎ上げられ、人々は彼の足元にひざまずき、彼が無垢な魂を持っていると称賛する。\n彼は一体何なのか？彼は無数の夢の中で途方に暮れながら問いかけ、その暗緑の湖水と空虚な濃霧の中で、彼の声だけが孤独に反響している。"
  },
  AwakerStory_95097_Title = {
    Text = "基本情報"
  },
  AwakerStory_95097_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_95098_Content = {
    Text = "カストールのように積極的に学ぶ態度に比べ、ポリュクスは外界との接触に対してより慎重なスタイルを持っていた。\n観察、思考、疑念、十分な思慮と注意がかつての彼を教会の厳しい支配の下で、カストールと共に成功裏に脱出させることができた。\n幼少期から彼は他人の考えを推測することを学び、嘘をつくことを学び、笑顔で本当の思いを隠すことを学んだ。親しい兄の前でも、彼は無意識に軽やかな笑顔で相手を安心させようとする。\n「大丈夫だ。」\n「きっとできる。」\nあの巨大な手の下で、弱者はわずかな希望を見出すために全力を尽くさなければならなかった。\n長い忘却と欺瞞を経て、今の彼は危険や失敗を一切許さない。たとえタイスの助言に従ってミサグに来たとしても、彼は長い間かなりの警戒心を保っていた。\n他の覚醒体から見ると、ポリュクスはあまり言葉を交わさないが、非常に忍耐強く、しばしば微笑みを見せる親切な男だ。しかし、世慣れた年長者たちは彼を見て、兄弟の違いに感嘆する。\nタイスによれば、彼女の前でさえ、ポリュクスは意図的にカストールを自分の後ろに隠すことがあるという——彼が記憶を取り戻して以来、彼はカストールにいつも守られることを望まなくなった。\nジェンキンもまた、ポリュクスの表裏の違いについて守秘者に訴え、「カストールのものを偶然拾ったとき、ポリュクスの急に暗くなった顔を見た」と主張した。「あの男の普段の良い性格は絶対に演技だ！彼は裏では子供を食べるような変態だ！」\nしかし、守秘者の力に直面した後、ポリュクスは守秘者に対する態度を180度変え、「聖心」の激しい反応の下で、彼はその偉大な魂から世界の真実を知ったと主張し、守秘者を新たな信仰として敬意を表した。"
  },
  AwakerStory_95098_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_95098_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_96418_Content = {
    Text = "葬骸城の創設者、食屍鬼の永遠の王。\n彼の宴は最も深い期待に値する――華麗なレストラン、優雅な舞踏、そして彼が手作りした死体で作られた上品な料理は、きっとあなたに永遠に忘れられない思い出を与えるでしょう。"
  },
  AwakerStory_96418_Title = {
    Text = "基本情報"
  },
  AwakerStory_96418_UnlockDesc = {
    Text = "覚醒体レベルが1に到達した"
  },
  AwakerStory_96419_Content = {
    Text = "葬骸城を離れた後、ドレセインは人間社会において非常に強い適応力を示した。これは必然であり、人間社会は彼にとって新たな始まりではなく、むしろ帰還であった。\n言葉遣い、振る舞い、気品、礼儀…………ドレセインのすべては完璧であり、君主にふさわしいオーラを保ちながら、長い間高位にいることによる傲慢さは微塵もなかった。\nドレセインは社交を嫌ってはいなかったが、政治、経済、学術といった話題には興味が薄く、彼がこれらの場に足を運ぶ理由はただ一つ——美食であった。\n味わうことに加えて、ドレセインは料理に関することにも熱心であった。食材の選定から処理方法、香辛料の使い方から火加減のコントロールまで、ドレセインの美食に関する豊富な知識と優れた味覚は、彼と話すすべての人を魅了した。彼らは、これまでの数十年の食事がただ生き延びるためのものであり、生存のために食べる動物と何ら変わりがなかったことに気づく。生まれつき味覚を持たない可哀想な虫さえ、彼の描写の中で美食の芸術を体験し、味覚の新生を得ることができた。\nこれはもちろんドレセインの礼儀にも関係しており、彼は人間と食屍鬼の食の好みの違いを明確に理解していた。ドレセインは異なる種の間の違いを尊重し、自身の味覚をすべての人に押し付けるつもりはなかった。\n「常に異なることを異端視する者がいるが、私の城邦では、それは非常に優雅な行為ではない。私は人と人との違いを尊重する。この違いの中にこそ、食べ物の美しさについてのさらなる可能性を見ることができる。」\n「しかし、あなたは異なります、守秘者。この世で非常に特別な存在であるあなたは…………私と同じように、このような食事の中で比類のない美を体験できるはずです…………」\nこの言葉を言ったとき、ドレセインの微笑みは紫色の霧の中で煌めき、まるで優雅な毒蛇があなたの耳元でささやき、あなたをエデンの園へ導く日を待っているかのようであった。"
  },
  AwakerStory_96419_Title = {
    Text = "ストーリー・二"
  },
  AwakerStory_96419_UnlockDesc = {
    Text = "同調率がレベル5に達する"
  },
  AwakerStory_96420_Content = {
    Text = "ネクロポリスの暗い祭祀神殿で目を覚ました時、激しい痛みがデュルセインの全身を襲っていた。\n劇毒の効果はまだ消えておらず、刃物で切られるような痛みが棘のあるつる植物のように、彼の腹部から生え始め、身体の隅々まで広がっていった。彼は父親が自分を毒殺することを考えたこともあったが、それでも父親から差し出された酒を受け取った。\n賢明で、正直で、勇敢…………遥か昔、デュルセインは賢王としてのすべての美徳を備えていた。あの老いた、きらめく目から、彼は父親と彼の背後にいる勢力の考えを容易に見抜いたが、それでも彼は微笑みながら父親から差し出された毒酒を受け取り、一気に飲み干した。\n人間の城邦において、食屍は許し難い悪行であった。デュルセインは彼らに何度も説明しようと試みた、死体の味を、死霊の美を。人と人の間には永遠に相互理解は存在せず、たとえ最も近しい者同士であっても、これはデュルセインが学んだ最後の教訓であった。\n彼は自分が再び目を覚ますことはないと思っていた。劇毒の他に、もう一つの痛みを感じていた。黒い霧が彼の身体を覆い、まるで肉食の爬虫類が無数に彼を啃（かじ）っているかのようだった。一つ一つの鋭い歯が彼の肌を突き破り、刃が彼の血肉を削ぎ取っていく。黒雲が彼を噛みついていた。黒雲が彼を再形成していた。彼の身体は絶えず再生し、また絶えず啃（かじ）られていた。デュルセインは口を開き、この無人の神殿で無声の悲鳴を上げた。\nその長く、極限の痛みの中で、黒雲がデュルセインの体内に入り込み、彼の精神と融合した。黒雲が彼の精神世界と繋がった瞬間、デュルセインの味覚に彼がこれまで味わったことのない味が現れた。劇毒、凌遅…………すべての苦痛はその瞬間に消え去り、彼の世界にはその一筋の至高の美味だけが残った。彼は興奮し、それを追い求め、その源を見つけた——それはネクロポリスの神々が味わっている味だった。それは彼自身の死体の味だった。\nこの恐ろしい苦痛の中で、ネクロポリスの神々は彼と一つになっていた。彼らの肉体と精神は繋がり、互いの苦痛と歓喜の中で悲鳴を上げ、笑い合った。\nこの食事は一週間続いた。この長い食事が終わった後、デュルセインは祭壇から再び立ち上がった。憎しみも、後悔もなかった。彼は彼を殺した人々を理解し、感謝した。この殺人の中で、彼は生涯で最も極致の美味を味わい、生涯で最も極致の歓喜を得た。\n満月が昇り、ネクロポリスはその日静かに頭を垂れ、喜びに満ちた新王を迎え入れた。"
  },
  AwakerStory_96420_Title = {
    Text = "ストーリー・三"
  },
  AwakerStory_96420_UnlockDesc = {
    Text = "同調率がレベル7に達する"
  },
  AwakerStory_96421_Content = {
    Text = "ロンドン郡北西部のエテリングトン廃墟墓地は、A.F.3@2年より地元住民によって絶対禁区として指定されている。《タイムズ》のアーカイブ報道およびスコットランドヤードの失踪者記録によると、近年、霧の濃い夜間に墓地で37人が失踪しており、その中には貴族の墓を盗掘する常習犯シリル、避寒するホームレスのクック、巡回中に迷い込んだ警官グレイソン、中世の葬儀文化を研究するオックスフォードの学者ホワイトなどが含まれている。目撃者の証言によれば、すべての失踪者は濃霧が3級に達した時に墓地に入ったとされ、最終的には霧の中で行方不明となり、捜索隊は何も遺留物を発見していない。\nミスディア協定審査会は、A.F.3@2年前からこの地域を低優先度の観察対象としていたが、デヴォン公爵サミュエル・コースン(超自然研究を資金提供することで知られる)の失踪に伴い、審査会は王室からの直接の問い合わせを受け、最終的に墓地に対して特別な行動を開始した。\nA.F.3@2年7月、審査会第七行動グループのリーダーであるイライアス・ソーンが率いるチームは、12名の武装エージェントと3名の霊媒を編成し、抗失温薬剤や方向定位装置などのシルバーコア装置を持って墓地に入った。チームは霧の中で隊形を維持しながら1.2キロ進んだ後、墓地の北西角にある壊れた食屍鬼の彫像の下に隠された六角形の入口を発見した。\nソーンチームは階段を下り、5000段以上の階段を経て地下神殿の正殿に到達した際、現場の状況は事前に想定された「遺体の堆積」というイメージとは完全に異なっていた。\n神殿の実測面積は約800平方メートルで、地面の平坦度の誤差は3ミリメートルを超えず、空気中には何の塵埃粒子も検出されなかった。空間内には装飾的な構造物はなく、中央には高さ2.3メートルの花崗岩の祭壇がそびえ立ち、祭壇の表面には連続した茨の模様が彫刻されていた。祭壇の周りには安定した濃度の黒い霧が漂い、黒い霧の中心には人型の輪郭が見えた。\n祭壇の上には跪く姿のサミュエル・コースン公爵がいて、衣服は完全であったが生命兆候は失われており、死体検査では外傷が確認されなかった。ソーンチームが黒い霧の外周障壁を突破した際、公爵の遺体は黒い霧の中で分子レベルの微粒子に分解され、質量分析計は何の残留信号も捉えなかった。\n公爵の身体が分解された後、黒い霧は突然拡張し、調査チーム全体を覆った。メンバーの後の証言によれば、全員が意識を失う前に、優雅で穏やか、耳元で囁くような男性の言葉をはっきりと聞いたという。その内容は、\n「葬骸城を探求しないでください。食屍鬼の王の食事を妨げないでください。」\n「これが最後の警告です。」\nチームが意識を取り戻したとき、すでに墓地の正門の錆びた鉄の柵の外にいた。すべての設備は正常に機能していたが、神殿内部の映像資料はすべて損傷していた。\nその後の記録によれば、審査会の会長とミスカトニック大学の神秘学部長は墓地を訪れた。その後、公式にいかなる形の探査行動も行われず、後続の監視データによれば、墓地の霧は侵入者の意図が明確な時のみ攻撃的な反応を引き起こし、無意識に迷い込んだ者には一時的な方向の混乱を引き起こすだけであった。\nこれにより、墓地はこの都市と共存し続け、ただ野心が渦巻き、伝説が語り継がれるだけであった。\n\n——《エテリングトン廃墟墓地事件調査報告》"
  },
  AwakerStory_96421_Title = {
    Text = "ストーリー・一"
  },
  AwakerStory_96421_UnlockDesc = {
    Text = "同調率レベルが3に到達する"
  },
  AwakerStory_96422_Content = {
    Text = "彼は自分の一生が至高の美味を追求するために存在していると考えていた。\n王子の責務、最愛の人との隔たり、道徳の規律……彼はこれらの苦痛を忘れ、味覚の芸術の極致を求めていた。王子から君主へ、人間から神へ、一瞬も休むことなく。彼はすべての料理法を習得し、すべての遺体の微細な違いを感じ取った。彼は願いを叶えたが、歓喜の後、何かを見落としているように感じていた。\nセリネの遺体を食べ、彼女の魂を見るその瞬間まで、彼は目覚めた。生前の遺体の物語、魂の残念な願いこそが、彼が常に追い求め、味わっていたものであった。\n食事は記憶のためにあり、すべての宴は亡者と生きる者の再会である——ドゥレサインはこの言葉を葬骸城の王座に刻んだ。彼の庇護を求める者には、記憶と安息を授けるだろう。"
  },
  AwakerStory_96422_Title = {
    Text = "ストーリー・四"
  },
  AwakerStory_96422_UnlockDesc = {
    Text = "同調率レベルが9に達した"
  }
